  { name: "Vasco", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Vasco_da_Gama_logo_%282021%29.svg/240px-Vasco_da_Gama_logo_%282021%29.svg.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Fluminense_FC_escudo.png/240px-Fluminense_FC_escudo.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Botafogo_de_futebol_e_regatas_logo.svg/240px-Botafogo_de_futebol_e_regatas_logo.svg.png" },
