];

export default function App() {
  const [selectedTeamIndex, setSelectedTeamIndex] = useState<number | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [sensorPermission, setSensorPermission] = useState<boolean | null>(null);

  const requestSensorPermission = async () => {
    // iOS 13+ requires permission for device orientation
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
      try {
        const response = await (DeviceOrientationEvent as any).requestPermission();
        if (response === 'granted') {
          setSensorPermission(true);
          setIsPlaying(true);
        } else {
          setSensorPermission(false);
          alert('Permissão de sensor necessária para controlar a barra!');
        }
      } catch (e) {
        console.error(e);
        // Non-HTTPS or other error
        setIsPlaying(true); // Try anyway, might be dev environment
      }
    } else {
      // Android/Other doesn't need explicit request usually
      setSensorPermission(true);
      setIsPlaying(true);
    }
  };

  if (isPlaying && selectedTeamIndex !== null) {
    // Pick a random opponent different from player
    const playerTeam = TEAMS[selectedTeamIndex];
    let opponentIndex = Math.floor(Math.random() * TEAMS.length);
    if (opponentIndex === selectedTeamIndex) opponentIndex = (opponentIndex + 1) % TEAMS.length;
    const opponentTeam = TEAMS[opponentIndex];

    return (
      <PongGame 
        playerTeam={playerTeam} 
        opponentTeam={opponentTeam} 
        onExit={() => setIsPlaying(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col items-center justify-center p-4">
      <div className="text-center mb-8">
        <h1 className="text-4xl md:text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-green-500 mb-2 brand-font">
          FUTEBOL PONG
        </h1>
        <p className="text-gray-400 font-mono text-sm">Controle com o movimento do celular!</p>
      </div>

      <div className="bg-slate-800 p-6 rounded-2xl shadow-2xl w-full max-w-4xl border border-slate-700">
        <h2 className="text-xl font-bold mb-6 flex items-center justify-center text-yellow-400">
          <Trophy className="mr-2" /> SELECIONE SEU TIME
        </h2>

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-4 mb-8">
          {TEAMS.map((team, index) => (
            <button
              key={team.id}
              onClick={() => setSelectedTeamIndex(index)}
              className={`p-4 rounded-xl flex flex-col items-center transition-all duration-300 relative overflow-hidden group ${
                selectedTeamIndex === index 
                  ? 'bg-gradient-to-b from-slate-700 to-slate-600 border-2 border-yellow-400 shadow-[0_0_20px_rgba(250,204,21,0.3)] transform scale-105' 
                  : 'bg-slate-800 border border-slate-700 hover:bg-slate-750 hover:border-slate-500'
              }`}
            >
              <div className="w-16 h-16 mb-3 relative z-10 transition-transform group-hover:scale-110">
                <img src={team.logo} alt={team.name} className="w-full h-full object-contain drop-shadow-lg" />
              </div>
              <span className={`text-sm font-bold font-mono z-10 ${selectedTeamIndex === index ? 'text-white' : 'text-gray-400'}`}>
                {team.name}
              </span>
              {selectedTeamIndex === index && (
                <div className="absolute inset-0 bg-yellow-500/5 z-0 animate-pulse" />
              )}
            </button>
          ))}
        </div>

        <div className="flex flex-col items-center space-y-4">
          <div className="flex items-center text-xs text-gray-500 bg-slate-900/50 px-4 py-2 rounded-full">
            <Smartphone className="w-4 h-4 mr-2 text-blue-400" />
            <span className="mr-1">Sensor:</span>
            {sensorPermission === false ? (
               <span className="text-red-400 flex items-center"><AlertCircle className="w-3 h-3 mr-1"/> Bloqueado</span>
            ) : (
               <span className="text-green-400">Giroscópio/Bússola</span>
            )}
          </div>

          <button
            disabled={selectedTeamIndex === null}
            onClick={requestSensorPermission}
            className={`w-full md:w-auto px-12 py-4 rounded-full font-black text-xl tracking-widest transition-all shadow-xl ${
              selectedTeamIndex !== null
                ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white hover:scale-105 transform'
                : 'bg-slate-700 text-slate-500 cursor-not-allowed'
            }`}
          >
            ENTRAR EM CAMPO
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import { ArrowLeft, RefreshCw, Trophy } from 'lucide-react';

interface Team {
  id: string;
  name: string;
  color: string;
  logo: string;
}

interface PongGameProps {
  playerTeam: Team;
  opponentTeam: Team;
  onExit: () => void;
}

const PongGame: React.FC<PongGameProps> = ({ playerTeam, opponentTeam, onExit }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game State Refs (Mutable for loop)
  const score = useRef({ player: 0, opponent: 0 });
  const ball = useRef({ x: 0, y: 0, vx: 0, vy: 0, radius: 10, speed: 7 });
  const paddlePlayer = useRef({ x: 50, width: 25, height: 4, targetX: 50 }); // percentages
  const paddleAI = useRef({ x: 50, width: 25, height: 4, speed: 0.8 }); // percentages

  const [gameOver, setGameOver] = useState(false);
  const [winner, setWinner] = useState<Team | null>(null);
  const [tilt, setTilt] = useState(0); // Visual feedback for UI
  const [isPaused, setIsPaused] = useState(false);

  // Asset Refs
  const playerLogoRef = useRef<HTMLImageElement | null>(null);
  const opponentLogoRef = useRef<HTMLImageElement | null>(null);
  const ballImageRef = useRef<HTMLImageElement | null>(null);

  // Constants
  const WIN_SCORE = 5;

  const resetBall = (winner: 'player' | 'opponent') => {
    ball.current.x = 50;
    ball.current.y = 50;
    ball.current.vx = 0;
    ball.current.vy = 0;

    setTimeout(() => {
        const direction = winner === 'player' ? -1 : 1; // Serve towards loser
        ball.current.vy = direction * (0.6 + Math.random() * 0.4); 
        ball.current.vx = (Math.random() - 0.5) * 0.8;

        // Normalize speed
        const len = Math.sqrt(ball.current.vx**2 + ball.current.vy**2);
        ball.current.vx = (ball.current.vx / len);
        ball.current.vy = (ball.current.vy / len);
        ball.current.speed = 0.8; // Reset speed (percentage of height per tick approx)
    }, 1000);
  };

  useEffect(() => {
    // Load images
    const pImg = new Image(); pImg.src = playerTeam.logo; pImg.crossOrigin = "Anonymous";
    playerLogoRef.current = pImg;

    const oImg = new Image(); oImg.src = opponentTeam.logo; oImg.crossOrigin = "Anonymous";
    opponentLogoRef.current = oImg;

    // Use a simple circle or soccer ball sprite
    // For now we draw a circle, but let's try to load a ball if we had one. 
    // We'll proceed with drawing code for the ball.

    // Handle Orientation
    const handleOrientation = (e: DeviceOrientationEvent) => {
      // Gamma is left/right tilt (-90 to 90)
      if (e.gamma !== null) {
        setTilt(e.gamma);
        // Map gamma -30 to 30 degrees to 0-100% screen width
        let target = 50 + (e.gamma / 30) * 50; 
        target = Math.max(0, Math.min(100, target));
        paddlePlayer.current.targetX = target;
      }
    };

    window.addEventListener('deviceorientation', handleOrientation);
    resetBall('player'); // Initial serve

    return () => {
      window.removeEventListener('deviceorientation', handleOrientation);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, []);

  // Mouse/Touch fallback
  const handleTouch = (e: React.TouchEvent | React.MouseEvent) => {
    const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
    if (canvasRef.current) {
        const rect = canvasRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const percent = (x / rect.width) * 100;
        paddlePlayer.current.targetX = Math.max(0, Math.min(100, percent));
    }
  };

  // Game Loop
  useEffect(() => {
    const loop = () => {
        if (!canvasRef.current || gameOver || isPaused) {
            requestRef.current = requestAnimationFrame(loop);
            return;
        }

        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Resize
        if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) {
            canvas.width = canvas.offsetWidth;
            canvas.height = canvas.offsetHeight;
        }

        const width = canvas.width;
        const height = canvas.height;
        const aspectRatio = width / height;

        // Update Physics

        // 1. Move Player Paddle (Smooth lerp)
        const pObj = paddlePlayer.current;
        pObj.x += (pObj.targetX - pObj.x) * 0.2;

        // 2. Move AI Paddle
        const ai = paddleAI.current;
        const targetAI = ball.current.x;
        // AI Reaction delay / error
        let error = (Math.sin(Date.now() / 500) * 10); 
        const diff = (targetAI + error) - ai.x;
        ai.x += Math.max(-ai.speed, Math.min(ai.speed, diff));

        // 3. Move Ball
        const b = ball.current;
        // Convert percentage velocity to pixels for movement, but keep state in percent
        // Aspect ratio correction: Speed is based on Height. 
        // We simulate a 100x100 grid where Y is dominant.

        // Speed scaling
        const speedMultiplier = height / 100;

        let dx = b.vx * b.speed; // This is relative movement
        let dy = b.vy * b.speed;

        // Apply to percentage state
        // X needs to be scaled by aspect ratio to keep square velocity
        b.x += dx * (height / width); 
        b.y += dy;

        // Wall Collisions (Left/Right)
        if (b.x <= 0) { b.x = 0; b.vx *= -1; }
        if (b.x >= 100) { b.x = 100; b.vx *= -1; }

        // Paddle Collisions
        // Player (Bottom)
        // Paddle Y is approx 90%
        const paddleYPlayer = 90;
        const paddleYAI = 10;

        // Check Player
        if (b.y >= paddleYPlayer - 2 && b.y <= paddleYPlayer + 2 && b.vy > 0) {
            if (Math.abs(b.x - pObj.x) < pObj.width / 2 + 2) {
                b.vy *= -1;
                // Add English/Spin based on where it hit
                const hitPoint = (b.x - pObj.x) / (pObj.width / 2);
                b.vx += hitPoint * 0.5; 
                b.speed *= 1.05; // Speed up
                b.y = paddleYPlayer - 2;

                // Clamp horizontal speed
                const maxVx = 0.8;
                if (b.vx > maxVx) b.vx = maxVx;
                if (b.vx < -maxVx) b.vx = -maxVx;

                // Renormalize
                const len = Math.sqrt(b.vx**2 + b.vy**2);
                b.vx /= len; b.vy /= len;
            }
        }

        // Check AI
        if (b.y <= paddleYAI + 2 && b.y >= paddleYAI - 2 && b.vy < 0) {
             if (Math.abs(b.x - ai.x) < ai.width / 2 + 2) {
                b.vy *= -1;
                const hitPoint = (b.x - ai.x) / (ai.width / 2);
                b.vx += hitPoint * 0.5;
                b.speed *= 1.05;
                b.y = paddleYAI + 2;

                const len = Math.sqrt(b.vx**2 + b.vy**2);
                b.vx /= len; b.vy /= len;
             }
        }

        // Scoring
        if (b.y > 105) {
            score.current.opponent++;
            if (score.current.opponent >= WIN_SCORE) {
                setWinner(opponentTeam);
                setGameOver(true);
            } else {
                resetBall('opponent');
            }
        }
        if (b.y < -5) {
            score.current.player++;
            if (score.current.player >= WIN_SCORE) {
                setWinner(playerTeam);
                setGameOver(true);
            } else {
                resetBall('player');
            }
        }

        // Draw
        ctx.fillStyle = '#0f172a'; // Slate 900
        ctx.fillRect(0, 0, width, height);

        // Draw Field Lines
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, height/2);
        ctx.lineTo(width, height/2);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(width/2, height/2, width * 0.15, 0, Math.PI*2);
        ctx.stroke();

        // Draw Scores (Background Big)
        ctx.font = `bold ${width * 0.2}px "Roboto Mono"`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        // AI Score (Top half inverted?)
        ctx.fillStyle = 'rgba(255,255,255,0.05)';
        ctx.fillText(score.current.opponent.toString(), width/2, height * 0.25);
        ctx.fillText(score.current.player.toString(), width/2, height * 0.75);


        // Draw Paddles
        const drawPaddle = (xPct: number, yPct: number, widthPct: number, color: string, isTop: boolean) => {
            const w = (widthPct / 100) * width;
            const h = (4 / 100) * height; // Fixed thick paddles
            const x = (xPct / 100) * width;
            const y = (yPct / 100) * height;

            ctx.fillStyle = color;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.roundRect(x - w/2, y - h/2, w, h, 8);
            ctx.fill();
            ctx.shadowBlur = 0;

            // Draw Logo on paddle center? No, too small. Maybe glow.
        };

        drawPaddle(ai.x, paddleYAI, ai.width, opponentTeam.color, true);
        drawPaddle(pObj.x, paddleYPlayer, pObj.width, playerTeam.color, false);

        // Draw Ball
        const bx = (b.x / 100) * width;
        const by = (b.y / 100) * height;
        const br = (3 / 100) * width; // Ball radius relative to width

        ctx.beginPath();
        ctx.arc(bx, by, br, 0, Math.PI * 2);
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Render Loop
        requestRef.current = requestAnimationFrame(loop);
    };

    requestRef.current = requestAnimationFrame(loop);
    return () => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [gameOver, isPaused]);

  return (
    <div className="fixed inset-0 bg-slate-900 flex flex-col">
      {/* HUD */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-center z-10 pointer-events-none">
        <div className="flex items-center space-x-2 opacity-80">
            <div className="w-8 h-8 rounded-full bg-white p-0.5">
                <img src={opponentTeam.logo} className="w-full h-full object-contain" />
            </div>
            <span className="text-white font-bold">{opponentTeam.name}</span>
        </div>
        <div className="text-xl font-mono text-white font-bold opacity-50">
           {score.current.opponent} - {score.current.player}
        </div>
        <div className="flex items-center space-x-2 opacity-80">
             <span className="text-white font-bold">{playerTeam.name}</span>
            <div className="w-8 h-8 rounded-full bg-white p-0.5">
                <img src={playerTeam.logo} className="w-full h-full object-contain" />
            </div>
        </div>
      </div>

      <canvas 
        ref={canvasRef} 
        className="flex-1 w-full touch-none"
        onTouchMove={handleTouch}
        onMouseMove={handleTouch}
      />

      {/* Tilt Indicator / Hint */}
      {!gameOver && (
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 text-white/30 text-xs text-center pointer-events-none">
             INCLINE O CELULAR<br/>PARA MOVER
             <div className="w-20 h-1 bg-white/10 mt-1 rounded-full overflow-hidden mx-auto">
                <div 
                  className="h-full bg-white/50 transition-all duration-100" 
                  style={{ 
                      width: '20%', 
                      transform: `translateX(${200 + (tilt * 2)}%)` 
                  }} 
                />
             </div>
          </div>
      )}

      {/* Game Over Screen */}
      {gameOver && winner && (
        <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 animate-in fade-in">
          <div className="bg-slate-800 p-8 rounded-2xl text-center border-2 border-yellow-500 shadow-2xl max-w-sm w-full mx-4">
             {winner.id === playerTeam.id ? (
                 <>
                    <Trophy className="w-20 h-20 text-yellow-400 mx-auto mb-4 animate-bounce" />
                    <h2 className="text-3xl font-black text-white mb-2 brand-font">VITÓRIA!</h2>
                    <p className="text-gray-400 mb-6">Seu time dominou o campo.</p>
                 </>
             ) : (
                 <>
                    <div className="grayscale">
                        <img src={playerTeam.logo} className="w-20 h-20 mx-auto mb-4 opacity-50" />
                    </div>
                    <h2 className="text-3xl font-black text-red-500 mb-2 brand-font">DERROTA</h2>
                    <p className="text-gray-400 mb-6">Tente novamente na próxima temporada.</p>
                 </>
             )}

             <div className="text-2xl font-mono text-white mb-8 border-y border-slate-700 py-2">
                {score.current.player} x {score.current.opponent}
             </div>

             <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={onExit}
                  className="px-4 py-3 bg-slate-700 hover:bg-slate-600 rounded-lg text-white font-bold flex items-center justify-center"
                >
                  <ArrowLeft className="mr-2 w-4 h-4" /> MENU
                </button>
                <button 
                  onClick={() => window.location.reload()} 
                  className="px-4 py-3 bg-yellow-500 hover:bg-yellow-400 rounded-lg text-black font-bold flex items-center justify-center"
                >
                  <RefreshCw className="mr-2 w-4 h-4" /> REVANCHE
                </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

