import React, { useEffect, useRef, useState } from 'react';
import { ArrowLeft, Smartphone, Trophy } from 'lucide-react';

interface Team {
  id: number;
  name: string;
  color: string;
  logoUrl: string;
}

interface PongGameProps {
  playerTeam: Team;
  opponentTeam: Team;
  onExit: () => void;
}

const PongGame: React.FC<PongGameProps> = ({ playerTeam, opponentTeam, onExit }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Game State Refs (Mutable for high-performance loop)
  // Coordinates are in % (0-100) to be responsive
  const ball = useRef({ x: 50, y: 50, vx: 0, vy: 0, speed: 0.6, radius: 2 }); 
  const player = useRef({ x: 50, width: 20, score: 0 }); 
  const ai = useRef({ x: 50, width: 20, score: 0, speed: 0.8 }); 

  const [gameState, setGameState] = useState<'start' | 'playing' | 'finished'>('start');
  const [winner, setWinner] = useState<Team | null>(null);
  const [permissionGranted, setPermissionGranted] = useState(false);
  const [debugTilt, setDebugTilt] = useState(0);

  const WIN_SCORE = 5;
  const ASPECT_RATIO = 0.6; // Width / Height (Phone shape)

  // --- Physics Engine ---
  const resetBall = (server: 'player' | 'ai') => {
    ball.current.x = 50;
    ball.current.y = 50;
    ball.current.speed = 0.6;
    // Randomize start angle slightly
    const angle = (Math.random() - 0.5) * 1.0; 
    const dir = server === 'player' ? -1 : 1; // Send towards opponent

    // Normalize velocity
    ball.current.vx = Math.sin(angle) * ball.current.speed;
    ball.current.vy = Math.cos(angle) * ball.current.speed * dir;
  };

  const updatePhysics = () => {
    if (gameState !== 'playing') return;

    const b = ball.current;
    const p = player.current;
    const a = ai.current;

    // 1. Move Ball
    b.x += b.vx;
    b.y += b.vy;

    // 2. Wall Collisions (Left/Right)
    if (b.x <= 0 || b.x >= 100) {
        b.vx *= -1;
        b.x = Math.max(0, Math.min(100, b.x));
    }

    // 3. Paddle Collisions
    // Player (Bottom)
    if (b.y >= 92 && b.y <= 95) {
        if (b.x >= p.x - p.width/2 && b.x <= p.x + p.width/2) {
            // Hit!
            b.y = 92;
            b.vy *= -1.05; // Speed up slightly
            b.speed *= 1.05;

            // Add "English" (spin) based on where it hit the paddle
            const hitPoint = b.x - p.x;
            b.vx += hitPoint * 0.1;
        }
    }

    // AI (Top)
    if (b.y <= 8 && b.y >= 5) {
        if (b.x >= a.x - a.width/2 && b.x <= a.x + a.width/2) {
             // Hit!
             b.y = 8;
             b.vy *= -1.05;
             b.speed *= 1.05;

             const hitPoint = b.x - a.x;
             b.vx += hitPoint * 0.1;
        }
    }

    // 4. Scoring
    if (b.y > 100) {
        // AI Scored
        a.score += 1;
        if (a.score >= WIN_SCORE) {
            setWinner(opponentTeam);
            setGameState('finished');
        } else {
            resetBall('player');
        }
    } else if (b.y < 0) {
        // Player Scored
        p.score += 1;
        if (p.score >= WIN_SCORE) {
            setWinner(playerTeam);
            setGameState('finished');
        } else {
            resetBall('ai');
        }
    }

    // 5. AI Movement
    // Simple tracking with reaction delay simulation
    const targetX = b.y < 50 ? b.x : 50; // Only track if ball is in AI half or returning to center
    const dx = targetX - a.x;
    if (Math.abs(dx) > a.speed) {
        a.x += Math.sign(dx) * a.speed;
    }
    a.x = Math.max(a.width/2, Math.min(100 - a.width/2, a.x));
  };

  // --- Rendering ---
  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      // Clear
      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Scale factors
      const w = canvas.width;
      const h = canvas.height;
      const scalex = (val: number) => (val / 100) * w;
      const scaley = (val: number) => (val / 100) * h;

      // Draw Court Lines
      ctx.strokeStyle = '#374151';
      ctx.lineWidth = 2;
      ctx.setLineDash([10, 10]);
      ctx.beginPath();
      ctx.moveTo(0, h/2);
      ctx.lineTo(w, h/2);
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw Center Circle
      ctx.beginPath();
      ctx.arc(w/2, h/2, w * 0.15, 0, Math.PI*2);
      ctx.stroke();

      // Draw Paddles
      const p = player.current;
      const a = ai.current;

      // Player Paddle
      ctx.fillStyle = playerTeam.color;
      ctx.shadowColor = playerTeam.color;
      ctx.shadowBlur = 10;
      ctx.fillRect(
          scalex(p.x - p.width/2), 
          scaley(93), 
          scalex(p.width), 
          scaley(2)
      );

      // AI Paddle
      ctx.fillStyle = opponentTeam.color;
      ctx.shadowColor = opponentTeam.color;
      ctx.fillRect(
          scalex(a.x - a.width/2), 
          scaley(5), 
          scalex(a.width), 
          scaley(2)
      );
      ctx.shadowBlur = 0;

      // Draw Ball
      const b = ball.current;
      ctx.fillStyle = '#fff';
      ctx.beginPath();
      ctx.arc(scalex(b.x), scaley(b.y), scalex(b.radius), 0, Math.PI*2);
      ctx.fill();

      // Draw Scores (Background)
      ctx.fillStyle = 'rgba(255,255,255,0.1)';
      ctx.font = 'bold 80px "Righteous"';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      // AI Score (Top half, rotated?)
      ctx.fillText(a.score.toString(), w/2, h * 0.25);

      // Player Score (Bottom half)
      ctx.fillText(p.score.toString(), w/2, h * 0.75);
  };

  const loop = () => {
      updatePhysics();
      draw();
      requestRef.current = requestAnimationFrame(loop);
  };

  useEffect(() => {
      requestRef.current = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(requestRef.current!);
  }, [gameState]);


  // --- Sensor Logic ---
  const handleOrientation = (e: DeviceOrientationEvent) => {
    // Gamma is the left-to-right tilt in degrees (-90 to 90)
    const tilt = e.gamma || 0;
    setDebugTilt(tilt);

    // Map tilt (-30 to 30) to screen position (0 to 100)
    // Clamp tilt
    const clampedTilt = Math.max(-30, Math.min(30, tilt));
    const position = ((clampedTilt + 30) / 60) * 100;

    // Smooth update
    player.current.x = player.current.x + (position - player.current.x) * 0.2;
    // Boundary check
    player.current.x = Math.max(player.current.width/2, Math.min(100 - player.current.width/2, player.current.x));
  };

  const requestAccess = async () => {
    if (typeof (DeviceOrientationEvent as any).requestPermission === 'function') {
        try {
            const permission = await (DeviceOrientationEvent as any).requestPermission();
            if (permission === 'granted') {
                window.addEventListener('deviceorientation', handleOrientation);
                setPermissionGranted(true);
                setGameState('playing');
                resetBall('ai');
            }
        } catch (e) {
            alert("Erro ao acessar sensores. Verifique as permissões.");
        }
    } else {
        // Android / Non-iOS 13+
        window.addEventListener('deviceorientation', handleOrientation);
        setPermissionGranted(true);
        setGameState('playing');
        resetBall('ai');
    }
  };

  useEffect(() => {
    return () => {
        window.removeEventListener('deviceorientation', handleOrientation);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-50 bg-gray-900 flex flex-col">
      {/* Header */}
      <div className="flex justify-between items-center p-4 bg-gray-800 border-b border-gray-700">
          <button onClick={onExit} className="p-2 bg-gray-700 rounded-full text-white">
              <ArrowLeft />
          </button>
          <div className="text-center">
              <h2 className="text-yellow-400 font-brand text-xl">PONG ARENA</h2>
              <div className="text-xs text-gray-400 flex justify-center space-x-4">
                  <span style={{color: playerTeam.color}}>{playerTeam.name}</span>
                  <span>VS</span>
                  <span style={{color: opponentTeam.color}}>{opponentTeam.name} (IA)</span>
              </div>
          </div>
          <div className="w-10"></div> {/* Spacer */}
      </div>

      {/* Canvas Container */}
      <div className="flex-1 relative bg-black">
          <canvas 
            ref={canvasRef} 
            width={400} 
            height={600} 
            className="w-full h-full object-contain block touch-none"
          />

          {/* Start / Permission Overlay */}
          {gameState === 'start' && (
              <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center p-6 text-center">
                  <Smartphone className="w-16 h-16 text-blue-400 mb-4 animate-pulse" />
                  <h3 className="text-2xl font-bold text-white mb-2">Controle por Movimento</h3>
                  <p className="text-gray-300 mb-8">
                      Incline seu celular para esquerda e direita para controlar a barra.
                  </p>
                  <button 
                    onClick={requestAccess}
                    className="px-8 py-4 bg-blue-600 rounded-xl font-bold text-white text-xl hover:bg-blue-500 shadow-lg"
                  >
                    INICIAR PARTIDA
                  </button>
              </div>
          )}

          {/* Game Over Overlay */}
          {gameState === 'finished' && winner && (
              <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
                  <Trophy className={`w-20 h-20 mb-4 ${winner.id === playerTeam.id ? 'text-yellow-400' : 'text-gray-500'}`} />
                  <h2 className="text-4xl font-black text-white mb-2 uppercase">
                      {winner.id === playerTeam.id ? 'VITÓRIA!' : 'DERROTA'}
                  </h2>
                  <p className="text-xl text-gray-400 mb-8">
                      {winner.id === playerTeam.id 
                        ? `O ${playerTeam.name} dominou a arena!` 
                        : `O ${opponentTeam.name} venceu desta vez.`}
                  </p>
                  <div className="flex flex-col space-y-3 w-full max-w-xs">
                    <button 
                        onClick={() => {
                            player.current.score = 0;
                            ai.current.score = 0;
                            setGameState('playing');
                            resetBall('ai');
                        }}
                        className="w-full py-3 bg-white text-black font-bold rounded-lg"
                    >
                        JOGAR NOVAMENTE
                    </button>
                    <button 
                        onClick={onExit}
                        className="w-full py-3 bg-gray-800 text-white font-bold rounded-lg border border-gray-600"
                    >
                        VOLTAR AO MENU
                    </button>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};

