  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);
  const [showPong, setShowPong] = useState(false); // State to toggle Pong Game

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleStartPong = () => {
      if (gameState.betMarbleId === null) {
          alert("Escolha um time primeiro para jogar Pong!");
          return;
      }
      setShowPong(true);
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong Mode ---
  if (showPong) {
      const playerTeam = TEAMS[gameState.betMarbleId || 0];
      // Select random opponent different from player
      const opponents = TEAMS.filter((_, i) => i !== (gameState.betMarbleId || 0));
      const randomOpponent = opponents[Math.floor(Math.random() * opponents.length)];

      // Map simplified Team structure to Pong Props
      const pTeam = { id: gameState.betMarbleId || 0, name: playerTeam.name, color: playerTeam.color, logoUrl: playerTeam.logo };
      const oTeam = { id: 99, name: randomOpponent.name, color: randomOpponent.color, logoUrl: randomOpponent.logo };

      return <PongGame playerTeam={pTeam} opponentTeam={oTeam} onExit={() => setShowPong(false)} />;
  }

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartPong}
                className={`w-20 rounded-lg font-black text-xl flex items-center justify-center transition-all ${
                  gameState.betMarbleId !== null
                    ? 'bg-purple-600 hover:bg-purple-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Desafio Pong (IA)"
            >
               <Gamepad2 className="w-8 h-8" />
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2033.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/890.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/574.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Vasco alterado para 2033. Flamengo mantido em 629.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/629.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2033.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/890.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/574.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Vasco alterado para 3454. Flamengo mantido em 629.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/629.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/890.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/574.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Flamengo alterado para 819. Vasco mantido em 3454.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/890.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/574.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Fluminense alterado para 3445. Flamengo (819) e Vasco (3454) mantidos.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/574.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Botafogo alterado para 3453. Outros times do RJ também ajustados anteriormente.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3453.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão
// Botafogo ajustado para URL da Wikimedia pois o ID 574 falhou e o 3453 era o Botafogo-SP.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/602.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
// Cruzeiro ajustado para URL da Wikimedia.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/1039.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
// Atlético MG ajustado para URL da Wikimedia.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false);
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      timer = setTimeout(() => {
        handleNextRound();
      }, 4000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        <RaceEngine 
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_4s_linear] w-full origin-left" style={{ animationDuration: '4s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
// Atlético MG ajustado para URL da Wikimedia.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    setIsFollowingBet(false); // Always reset to follow leader (1st place) on new round
    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // Changed from 4000 to 3000 as requested
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* Added key={gameState.round} to force re-mount on new round, ensuring physics starts FRESH after popup closes */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Now Clickable with Camera Toggle */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <span className="text-gray-400 text-xs uppercase">Aposta:</span>}
           <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
               <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
           </div>
           <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
           {gameState.gameMode === 'points' && (
             <span className="pl-2 border-l border-gray-600 text-blue-300">
               Score: {gameState.marbles.find(m => m.id === gameState.betMarbleId)?.score}
             </span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import { Marble, GameState, PhysicsConfig, GameMode } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
// Atlético MG ajustado para URL da Wikimedia.
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 10th)
const POINTS_SYSTEM = [10, 8, 6, 5, 4, 3, 2, 1, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: 9,
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? 9 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? 9 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-blue-400">
              <Settings className="mr-2" /> Configuração da Física
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <button 
              disabled={gameState.betMarbleId === null}
              onClick={handleStartTournament}
              className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all ${
                gameState.betMarbleId !== null
                  ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                  : 'bg-gray-700 text-gray-500 cursor-not-allowed'
              }`}
            >
              INICIAR CORRIDA
            </button>
          </div>
        </div>
      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type < 0.15) {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type < 0.25) {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type < 0.35) {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type < 0.45) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type < 0.55) {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type < 0.70) {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type < 0.85) {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // START DELAY: Allow 1000ms before moving marbles.
    // This prevents the race from starting while the popup is still fading out.
    if (Date.now() - startTime.current < 1000) {
        return; 
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Smooth camera: aim for the cluster of top 3
          const leaders = activeMarblesList.slice(0, 3); 
          const avgY = leaders.reduce((a, b) => a + b.y, 0) / leaders.length;
          targetY = avgY - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        const img = new Image();
        img.src = m.logoUrl;
        // REMOVED crossOrigin = "Anonymous" to allow non-CORS CDNs to display (tainted canvas is OK here)
        imagesRef.current[m.id] = img;
    });

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      // RESET POSITION TO TOP
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Background Circle (White) to make transparency logos pop
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Draw Logo Image clipped to circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.clip();

      const img = imagesRef.current[m.id];
      if (img && img.complete && img.naturalHeight !== 0) {
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      } else {
        // Fallback if image fails
        ctx.fillStyle = m.color;
        ctx.fill();
      }
      ctx.restore();

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type < 0.15) {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type < 0.25) {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type < 0.35) {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type < 0.45) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type < 0.55) {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type < 0.70) {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type < 0.85) {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // START DELAY: Allow 1000ms before moving marbles.
    // This prevents the race from starting while the popup is still fading out.
    if (Date.now() - startTime.current < 1000) {
        return; 
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic - STRICTLY follow the first place marble
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Changed: Do NOT average top 3. Just take the leader.
          // This ensures the camera stays with the leader even if they are far ahead.
          targetY = activeMarblesList[0].y - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        const img = new Image();
        img.src = m.logoUrl;
        // REMOVED crossOrigin = "Anonymous" to allow non-CORS CDNs to display (tainted canvas is OK here)
        imagesRef.current[m.id] = img;
    });

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      // RESET POSITION TO TOP
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Background Circle (White) to make transparency logos pop
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Draw Logo Image clipped to circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.clip();

      const img = imagesRef.current[m.id];
      if (img && img.complete && img.naturalHeight !== 0) {
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      } else {
        // Fallback if image fails
        ctx.fillStyle = m.color;
        ctx.fill();
      }
      ctx.restore();

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Funnel
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.4, y1: 150, x2: COURSE_WIDTH * 0.4, y2: 180, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH * 0.6, y1: 150, x2: COURSE_WIDTH * 0.6, y2: 180, type: 'wall' });

    currentY = 220;

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = Math.random();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type < 0.15) {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type < 0.25) {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type < 0.35) {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type < 0.45) {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type < 0.55) {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type < 0.70) {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type < 0.80) {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type < 0.92) {
        // --- BIG FUNNEL ---
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; // Marbles are radius 18 (diam 36). 55 gives clearance.

        // Left Angle Wall
        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Right Angle Wall
        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Chaos Pin below the exit to scatter them
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // START DELAY: Allow 1000ms before moving marbles.
    // This prevents the race from starting while the popup is still fading out.
    if (Date.now() - startTime.current < 1000) {
        return; 
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }

      solidDynamics.push(obj);

      if (obj.type === 'spinner') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic - STRICTLY follow the first place marble
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Changed: Do NOT average top 3. Just take the leader.
          // This ensures the camera stays with the leader even if they are far ahead.
          targetY = activeMarblesList[0].y - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        const img = new Image();
        img.src = m.logoUrl;
        // REMOVED crossOrigin = "Anonymous" to allow non-CORS CDNs to display (tainted canvas is OK here)
        imagesRef.current[m.id] = img;
    });

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: COURSE_WIDTH * 0.4 + (Math.random() * COURSE_WIDTH * 0.2),
      // RESET POSITION TO TOP
      y: -50 - (index * 40),
      vx: (Math.random() - 0.5) * 5,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Background Circle (White) to make transparency logos pop
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.fillStyle = '#ffffff';
      ctx.shadowColor = 'rgba(0,0,0,0.5)';
      ctx.shadowBlur = 5;
      ctx.fill();
      ctx.shadowBlur = 0;

      // Draw Logo Image clipped to circle
      ctx.save();
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.clip();

      const img = imagesRef.current[m.id];
      if (img && img.complete && img.naturalHeight !== 0) {
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
      } else {
        // Fallback if image fails
        ctx.fillStyle = m.color;
        ctx.fill();
      }
      ctx.restore();

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

