  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Fortaleza_Esporte_Clube_logo.svg/512px-Fortaleza_Esporte_Clube_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2020.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://images.fotmob.com/image_resources/logo/teamlogo/10238.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Fortaleza_Esporte_Clube_logo.svg/240px-Fortaleza_Esporte_Clube_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://ssl.gstatic.com/onebox/media/sports/logos/mefrB1d1JjZq_xV-83M_tQ_96x96.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6271.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Fortaleza_Esporte_Clube_logo.svg/512px-Fortaleza_Esporte_Clube_logo.svg.png" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <img src={m.logoUrl} alt={m.name} className="w-full h-full object-contain" />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <img src={champion.logoUrl} alt={champion.name} className="w-full h-full object-contain" />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <img src={m.logoUrl} className="w-full h-full object-contain"/>
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import RaceEngine from './components/RaceEngine';
import PongGame from './components/PongGame';
import { Marble, GameState, PhysicsConfig, GameMode, ObstacleSettings } from './types';
import { Trophy, Settings, Skull, Play, Medal, X, Pause, Camera, Sliders, Gamepad2 } from 'lucide-react';
import { audio } from './services/audioService';

// Data for Brazilian Teams
// CORREÇÃO: IDs Oficiais da ESPN para o Brasileirão e URLs da Wikimedia para estabilidade
const TEAMS = [
  { name: "São Paulo", color: "#C62925", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2026.png" },
