                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <img src={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.logoUrl} className="w-full h-full object-contain" />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <img src={m.logoUrl} className="w-full h-full object-contain"/>
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <img src={gameState.marbles.find(m => m.id === gameState.betMarbleId)?.logoUrl} className="w-full h-full object-contain" />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // 1. Start Box (Horse Race Style)
    // Wide area at top to fit all marbles horizontally
    lines.push({ x1: 0, y1: 0, x2: 0, y2: GATE_Y + 50, type: 'wall' }); // Left Wall
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: GATE_Y + 50, type: 'wall' }); // Right Wall

    // Funnel below the gate to mix them up after start
    lines.push({ x1: 0, y1: GATE_Y + 50, x2: COURSE_WIDTH * 0.4, y2: GATE_Y + 200, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: GATE_Y + 50, x2: COURSE_WIDTH * 0.6, y2: GATE_Y + 200, type: 'wall' });

    currentY = GATE_Y + 250;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type === 'spinner') {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
