  { name: "Santos", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2674.png" }, 
  { name: "Palmeiras", color: "#006437", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/2029.png" },
  { name: "Corinthians", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/874.png" },
  { name: "Flamengo", color: "#C3281E", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/819.png" },
  { name: "Vasco", color: "#000000", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3454.png" },
  { name: "Fluminense", color: "#8A191D", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/3445.png" },
  { name: "Botafogo", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Botafogo_de_Futebol_e_Regatas_logo.svg/500px-Botafogo_de_Futebol_e_Regatas_logo.svg.png" },
  { name: "Cruzeiro", color: "#005CA9", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Logo_Cruzeiro_1996.png/500px-Logo_Cruzeiro_1996.png" },
  { name: "Atlético MG", color: "#000000", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/27/Clube_Atl%C3%A9tico_Mineiro_logo.svg/500px-Clube_Atl%C3%A9tico_Mineiro_logo.svg.png" },
  { name: "Grêmio", color: "#0D80BF", logo: "https://a.espncdn.com/i/teamlogos/soccer/500/6273.png" },
  { name: "Internacional", color: "#E30613", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Escudo_do_Sport_Club_Internacional.svg/500px-Escudo_do_Sport_Club_Internacional.svg.png" },
  { name: "Bahia", color: "#0083CA", logo: "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Esporte_Clube_Bahia_logo.svg/512px-Esporte_Clube_Bahia_logo.svg.png" },
  { name: "Fortaleza", color: "#132E66", logo: "" }
];

// Points distribution for Points Mode (1st to 14th)
const POINTS_SYSTEM = [12, 10, 8, 7, 6, 5, 4, 3, 2, 1, 0, 0, 0, 0];

const INITIAL_MARBLES: Marble[] = TEAMS.map((team, i) => ({
  id: i,
  name: team.name,
  color: team.color,
  logoUrl: team.logo,
  x: 0, y: 0, vx: 0, vy: 0, 
  radius: 18, 
  angle: 0,
  omega: 0,
  score: 0,
  finished: false, finishTime: 0, rank: 0
}));

// Helper para renderizar logo ou sigla
const TeamLogo = ({ marble, className }: { marble: Marble | undefined, className?: string }) => {
  if (!marble) return null;

  if (marble.logoUrl) {
    return <img src={marble.logoUrl} alt={marble.name} className={`object-contain ${className || "w-full h-full"}`} />;
  }

  return (
    <div 
      className={`flex items-center justify-center font-black text-white rounded-full ${className || "w-full h-full"}`} 
      style={{ backgroundColor: marble.color, fontSize: '40%' }}
    >
      {marble.name.substring(0, 3).toUpperCase()}
    </div>
  );
};

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    gameMode: 'elimination',
    phase: 'betting',
    round: 1,
    totalRounds: TEAMS.length - 1, // Dynamic based on team count
    marbles: INITIAL_MARBLES,
    activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
    betMarbleId: null,
    lastEliminatedId: null,
    roundPoints: {}
  });

  const [physicsConfig, setPhysicsConfig] = useState<PhysicsConfig>({
    gravity: 0.25,
    restitution: 0.6,
    friction: 0.99
  });

  const [obstacleSettings, setObstacleSettings] = useState<ObstacleSettings>({
    spinner: true,
    slider: true,
    repulsor: true,
    conveyor: true,
    teleporter: true,
    hollow_circle: true,
    laser: true,
    fan: true,
    funnel: true
  });

  const [isPaused, setIsPaused] = useState(false);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [showObstacleConfig, setShowObstacleConfig] = useState(false);
  const [showPong, setShowPong] = useState(false);

  // Default to false (Follow Leader)
  const [isFollowingBet, setIsFollowingBet] = useState(false);

  // Memoize activeMarblesList to prevent unnecessary re-initialization of RaceEngine
  const activeMarblesList = useMemo(() => 
    gameState.marbles.filter(m => gameState.activeMarbleIds.includes(m.id)),
    [gameState.marbles, gameState.activeMarbleIds]
  );

  // --- Handlers ---

  const handleModeSelect = (mode: GameMode) => {
    setGameState(prev => ({
      ...prev,
      gameMode: mode,
      totalRounds: mode === 'elimination' ? TEAMS.length - 1 : 10 // 10 rounds for points mode
    }));
  };

  const handleStartTournament = () => {
    if (gameState.betMarbleId === null) return;

    audio.init();
    audio.resume();

    setGameState(prev => ({ ...prev, phase: 'racing' }));
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false); // Reset to follow leader on start
  };

  const handleExitTournament = () => {
      resetGame();
  };

  const handleRaceFinish = (results: Marble[]) => {
    if (gameState.gameMode === 'elimination') {
      const loser = results[results.length - 1];
      audio.playEliminated();
      setGameState(prev => ({
        ...prev,
        phase: 'round_result',
        lastEliminatedId: loser.id,
        roundPoints: {}
      }));
    } else {
      // Points Mode logic
      const currentRoundPoints: Record<number, number> = {};
      const updatedMarbles = [...gameState.marbles];

      results.forEach((m, index) => {
        const points = POINTS_SYSTEM[index] || 0;
        currentRoundPoints[m.id] = points;

        // Update total score
        const marbleIndex = updatedMarbles.findIndex(mar => mar.id === m.id);
        if (marbleIndex !== -1) {
          updatedMarbles[marbleIndex] = {
            ...updatedMarbles[marbleIndex],
            score: updatedMarbles[marbleIndex].score + points
          };
        }
      });

      audio.playFinish();

      setGameState(prev => ({
        ...prev,
        marbles: updatedMarbles,
        phase: 'round_result',
        roundPoints: currentRoundPoints
      }));
    }
  };

  const handleNextRound = () => {
    // CRITICAL: Always reset camera to follow leader at start of new round
    setIsFollowingBet(false); 

    if (gameState.gameMode === 'elimination') {
      const nextActiveIds = gameState.activeMarbleIds.filter(id => id !== gameState.lastEliminatedId);

      if (nextActiveIds.length === 1) {
        audio.playFinish(); 
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'champion'
        }));
      } else {
        setGameState(prev => ({
          ...prev,
          activeMarbleIds: nextActiveIds,
          phase: 'racing',
          round: prev.round + 1,
          lastEliminatedId: null
        }));
      }
    } else {
      // Points Mode
      if (gameState.round >= gameState.totalRounds) {
         // End of tournament
         const sortedByScore = [...gameState.marbles].sort((a, b) => b.score - a.score);
         const winnerIds = [sortedByScore[0].id]; 

         audio.playFinish();
         setGameState(prev => ({
           ...prev,
           activeMarbleIds: winnerIds,
           phase: 'champion'
         }));
      } else {
        // Points Mode: Just increment round, phase -> racing
        setGameState(prev => ({
          ...prev,
          phase: 'racing',
          round: prev.round + 1,
          roundPoints: {}
        }));
      }
    }
  };

  const resetGame = () => {
    setGameState({
      gameMode: gameState.gameMode,
      phase: 'betting',
      round: 1,
      totalRounds: gameState.gameMode === 'elimination' ? TEAMS.length - 1 : 10,
      marbles: INITIAL_MARBLES.map(m => ({...m, score: 0})),
      activeMarbleIds: INITIAL_MARBLES.map(m => m.id),
      betMarbleId: null,
      lastEliminatedId: null,
      roundPoints: {}
    });
    setIsPaused(false);
    setShowExitConfirm(false);
    setIsFollowingBet(false);
  };

  const toggleObstacle = (key: keyof ObstacleSettings) => {
    setObstacleSettings(prev => ({ ...prev, [key]: !prev[key] }));
  };

  // --- Auto Advance Effect ---
  useEffect(() => {
    let timer: ReturnType<typeof setTimeout>;
    if (gameState.phase === 'round_result') {
      // 3 Seconds Popup Duration
      timer = setTimeout(() => {
        handleNextRound();
      }, 3000);
    }
    return () => clearTimeout(timer);
  }, [gameState.phase, gameState.activeMarbleIds, gameState.round]);

  // --- Render Pong ---
  if (showPong && gameState.betMarbleId !== null) {
      const playerTeamData = TEAMS[gameState.betMarbleId];
      // Pick a random opponent that is not the player
      let oppId = Math.floor(Math.random() * TEAMS.length);
      if (oppId === gameState.betMarbleId) oppId = (oppId + 1) % TEAMS.length;
      const opponentTeamData = TEAMS[oppId];

      const playerTeam = {
          ...playerTeamData,
          id: gameState.betMarbleId,
          logoUrl: playerTeamData.logo
      };
      const opponentTeam = {
          ...opponentTeamData,
          id: oppId,
          logoUrl: opponentTeamData.logo
      };

      return <PongGame playerTeam={playerTeam} opponentTeam={opponentTeam} onExit={() => setShowPong(false)} />;
  }


  // --- Render Components ---

  // 1. Betting / Config Screen
  if (gameState.phase === 'betting') {
    return (
      <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 text-white">
        <h1 className="text-5xl md:text-7xl mb-2 text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-red-500 brand-font tracking-widest text-center">
          MARBLE ROYALE
        </h1>
        <h2 className="text-xl md:text-2xl text-green-400 mb-2 font-bold tracking-widest">
          BRASILEIRÃO EDITION
        </h2>
        <p className="text-gray-500 font-mono text-sm mb-6 tracking-wide">
          Desenvolvido por Prof Covre
        </p>

        {/* Mode Selector */}
        <div className="flex space-x-4 mb-6 bg-gray-800 p-2 rounded-lg border border-gray-700">
           <button 
             onClick={() => handleModeSelect('elimination')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'elimination' ? 'bg-red-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             MATA-MATA
           </button>
           <button 
             onClick={() => handleModeSelect('points')}
             className={`px-4 py-2 rounded-md font-bold transition-all ${gameState.gameMode === 'points' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
           >
             PONTOS CORRIDOS
           </button>
        </div>

        <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 w-full max-w-4xl shadow-2xl">
          <div className="mb-6">
            <h2 className="text-xl font-bold mb-4 flex items-center text-yellow-400">
              <Trophy className="mr-2" /> Escolha seu Time
            </h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {gameState.marbles.map(m => (
                <button
                  key={m.id}
                  onClick={() => setGameState(prev => ({ ...prev, betMarbleId: m.id }))}
                  className={`p-3 rounded-lg flex flex-col items-center transition-all ${
                    gameState.betMarbleId === m.id 
                      ? 'bg-yellow-500/20 border-2 border-yellow-400 scale-105' 
                      : 'bg-gray-700 border border-transparent hover:bg-gray-600'
                  }`}
                >
                  <div className="w-12 h-12 rounded-full mb-2 shadow-lg bg-gray-200 flex items-center justify-center p-0.5 relative overflow-hidden">
                     <TeamLogo marble={m} />
                  </div>
                  <span className="text-xs font-bold font-mono">{m.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mb-8 border-t border-gray-700 pt-6">
            <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold flex items-center text-blue-400">
                  <Settings className="mr-2" /> Configurações
               </h2>
               <button 
                  onClick={() => setShowObstacleConfig(true)}
                  className="flex items-center text-sm bg-gray-700 hover:bg-gray-600 px-3 py-1.5 rounded transition-colors"
               >
                  <Sliders className="w-4 h-4 mr-2" />
                  Personalizar Obstáculos
               </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="text-xs text-gray-400 block mb-1">Gravidade ({(physicsConfig.gravity * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.8" step="0.05"
                  value={physicsConfig.gravity}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, gravity: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
              <div>
                <label className="text-xs text-gray-400 block mb-1">Elasticidade ({(physicsConfig.restitution * 100).toFixed(0)}%)</label>
                <input 
                  type="range" min="0.1" max="0.9" step="0.1"
                  value={physicsConfig.restitution}
                  onChange={(e) => setPhysicsConfig(prev => ({...prev, restitution: parseFloat(e.target.value)}))}
                  className="w-full accent-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="flex space-x-3">
            <button 
                disabled={gameState.betMarbleId === null}
                onClick={handleStartTournament}
                className={`flex-1 py-4 rounded-lg font-black text-xl tracking-widest transition-all flex items-center justify-center ${
                gameState.betMarbleId !== null
                    ? 'bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-400 hover:to-emerald-500 text-white shadow-lg transform hover:-translate-y-1'
                    : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
            >
                INICIAR CORRIDA
            </button>

            <button 
                disabled={gameState.betMarbleId === null}
                onClick={() => setShowPong(true)}
                className={`w-24 rounded-lg font-bold text-sm transition-all flex flex-col items-center justify-center ${
                    gameState.betMarbleId !== null
                        ? 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg'
                        : 'bg-gray-700 text-gray-500 cursor-not-allowed'
                }`}
                title="Jogar Pong com Sensor"
            >
                <Gamepad2 className="w-6 h-6 mb-1" />
                PONG
            </button>
          </div>

        </div>

        {/* Obstacle Config Modal */}
        {showObstacleConfig && (
           <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
              <div className="bg-gray-800 border border-gray-600 rounded-xl p-6 max-w-lg w-full shadow-2xl animate-in zoom-in-95">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-xl font-bold flex items-center"><Sliders className="mr-2 w-5 h-5"/> Obstáculos Ativos</h3>
                    <button onClick={() => setShowObstacleConfig(false)}><X className="text-gray-400 hover:text-white" /></button>
                 </div>

                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-h-[60vh] overflow-y-auto pr-2">
                    {[
                      { id: 'spinner', label: 'Giradores' },
                      { id: 'slider', label: 'Esmagadores' },
                      { id: 'repulsor', label: 'Repulsores' },
                      { id: 'conveyor', label: 'Esteiras' },
                      { id: 'teleporter', label: 'Teletransportes' },
                      { id: 'hollow_circle', label: 'Círculos Ocos' },
                      { id: 'laser', label: 'Lasers' },
                      { id: 'fan', label: 'Ventiladores' },
                      { id: 'funnel', label: 'Funis Gigantes' }
                    ].map((obs) => (
                      <button 
                        key={obs.id}
                        onClick={() => toggleObstacle(obs.id as keyof ObstacleSettings)}
                        className={`flex items-center justify-between p-3 rounded-lg border transition-all ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-900/30 border-blue-500/50' : 'bg-gray-700/30 border-gray-700'}`}
                      >
                         <span className="font-mono text-sm">{obs.label}</span>
                         <div className={`w-10 h-6 rounded-full relative transition-colors ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'bg-blue-500' : 'bg-gray-600'}`}>
                            <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform ${obstacleSettings[obs.id as keyof ObstacleSettings] ? 'left-5' : 'left-1'}`} />
                         </div>
                      </button>
                    ))}
                 </div>

                 <div className="mt-6 flex justify-end">
                    <button 
                      onClick={() => setShowObstacleConfig(false)}
                      className="px-6 py-2 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-lg"
                    >
                      CONFIRMAR
                    </button>
                 </div>
              </div>
           </div>
        )}

      </div>
    );
  }

  // 2. Champion Screen
  if (gameState.phase === 'champion') {
    const championId = gameState.activeMarbleIds[0];
    const champion = gameState.marbles.find(m => m.id === championId)!;
    const playerWon = gameState.betMarbleId === championId;

    return (
      <div className="min-h-screen bg-black flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
        <div className="relative mb-8">
           <div className="absolute inset-0 bg-yellow-500 blur-3xl opacity-20 animate-pulse"></div>
           <Trophy className="w-32 h-32 text-yellow-400 relative z-10 mx-auto mb-4" />
           <div className="w-32 h-32 rounded-full mx-auto relative z-10 shadow-[0_0_50px_rgba(255,255,255,0.5)] border-4 border-white bg-gray-100 flex items-center justify-center p-2">
             <TeamLogo marble={champion} />
           </div>
        </div>

        <h1 className="text-6xl font-black text-white mb-2 brand-font">{champion.name}</h1>
        <p className="text-2xl text-yellow-500 font-mono mb-4">CAMPEÃO DO TORNEIO</p>

        {gameState.gameMode === 'points' && (
           <div className="text-xl text-blue-400 mb-8 font-mono font-bold">
              Pontuação Final: {champion.score} pts
           </div>
        )}

        <div className={`p-6 rounded-xl border-2 mb-8 max-w-md w-full ${playerWon ? 'bg-green-900/30 border-green-500' : 'bg-red-900/30 border-red-500'}`}>
          <h3 className="text-xl font-bold mb-2">{playerWon ? "PARABÉNS!" : "NÃO FOI DESSA VEZ"}</h3>
          <p className="text-gray-300">
            {playerWon 
              ? `Sua aposta no ${champion.name} deu certo!` 
              : `Você apostou no ${gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}. Tente novamente!`}
          </p>
        </div>

        {gameState.gameMode === 'points' && (
          <div className="w-full max-w-md bg-gray-800 rounded-lg p-4 mb-8 overflow-y-auto max-h-60">
             <h4 className="text-gray-400 mb-2 font-bold uppercase text-xs tracking-wider">Tabela Final</h4>
             {[...gameState.marbles].sort((a,b) => b.score - a.score).map((m, idx) => (
                <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0">
                   <div className="flex items-center space-x-3">
                      <span className="text-gray-500 font-mono w-4">{idx + 1}</span>
                      <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                        <TeamLogo marble={m} />
                      </div>
                      <span>{m.name}</span>
                   </div>
                   <span className="font-mono font-bold text-yellow-500">{m.score}</span>
                </div>
             ))}
          </div>
        )}

        <button 
          onClick={resetGame}
          className="px-8 py-3 bg-white text-black font-bold rounded-full hover:scale-105 transition-transform"
        >
          NOVO TORNEIO
        </button>
      </div>
    );
  }

  // 3. Racing / Round Result Screen (Game Loop)
  return (
    <div className="relative w-full h-screen bg-gray-900 overflow-hidden">

      {/* Race View */}
      <div className="absolute inset-0 z-0">
        {/* key={gameState.round} ensures the component Re-mounts completely when round changes.
            This resets the physics engine and guarantees a fresh start for every round. */}
        <RaceEngine 
          key={gameState.round}
          activeMarbles={activeMarblesList}
          config={physicsConfig}
          obstacleSettings={obstacleSettings}
          onRaceFinish={handleRaceFinish}
          betMarbleId={gameState.betMarbleId}
          isPaused={isPaused}
          isFollowingBet={isFollowingBet}
        />
      </div>

      {/* Overlay UI */}
      <div className="absolute top-0 left-0 w-full p-4 flex justify-between items-start z-10 pointer-events-none">
         <div className="flex items-center">
            <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white pointer-events-auto">
              <div className="text-xs text-gray-400 font-bold uppercase">Rodada</div>
              <div className="text-2xl font-mono text-yellow-400">{gameState.round} <span className="text-sm text-gray-500">/ {gameState.totalRounds}</span></div>
            </div>
         </div>

         {/* Right Side UI: Points + Exit */}
         <div className="flex flex-col items-end pointer-events-auto">
             <button
                onClick={() => setIsPaused(true)}
                className="bg-yellow-600/80 backdrop-blur p-2 rounded-full border border-yellow-400 text-white mb-2 hover:bg-yellow-500 transition-colors shadow-lg z-50"
                title="Pausar"
             >
                 <Pause className="w-6 h-6" />
             </button>

             {gameState.gameMode === 'points' && (
               <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white min-w-[150px]">
                 <div className="text-xs text-gray-400 font-bold uppercase mb-1">Top Pontos</div>
                 {gameState.marbles
                   .sort((a,b) => b.score - a.score)
                   .slice(0, 3)
                   .map((m, i) => (
                     <div key={m.id} className="flex justify-between text-xs mb-1">
                       <span className={`${i===0?'text-yellow-400': 'text-gray-300'}`}>{i+1}. {m.name}</span>
                       <span className="font-mono">{m.score}</span>
                     </div>
                   ))}
               </div>
             )}

             {gameState.gameMode === 'elimination' && (
                <div className="bg-black/50 backdrop-blur p-3 rounded-lg border border-gray-700 text-white text-right">
                  <div className="text-xs text-gray-400 font-bold uppercase">Sobreviventes</div>
                  <div className="text-2xl font-mono text-blue-400">{activeMarblesList.length}</div>
                </div>
             )}
         </div>
      </div>

      {/* Pause Menu */}
      {isPaused && !showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
            <div className="bg-gray-800 border border-gray-600 p-8 rounded-2xl shadow-2xl max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-200">
                <h2 className="text-3xl font-bold text-white mb-8 brand-font">JOGO PAUSADO</h2>
                <div className="flex flex-col space-y-4">
                    <button 
                        onClick={() => setIsPaused(false)}
                        className="w-full py-4 bg-green-600 hover:bg-green-500 text-white font-bold rounded-lg text-xl shadow-lg transition-transform hover:scale-105 flex items-center justify-center"
                    >
                        <Play className="mr-2 fill-current" /> RETOMAR
                    </button>
                    <button 
                        onClick={() => setShowExitConfirm(true)}
                        className="w-full py-4 bg-gray-700 hover:bg-red-900/50 hover:border-red-500 border border-transparent text-gray-300 hover:text-red-400 font-bold rounded-lg text-xl transition-colors flex items-center justify-center"
                    >
                        <X className="mr-2" /> SAIR DO JOGO
                    </button>
                </div>
            </div>
        </div>
      )}

      {/* Exit Confirmation */}
      {showExitConfirm && (
        <div className="absolute inset-0 z-50 bg-black/90 backdrop-blur-md flex items-center justify-center p-4">
             <div className="bg-gray-900 border-2 border-red-600 p-8 rounded-2xl shadow-[0_0_50px_rgba(220,38,38,0.5)] max-w-sm w-full text-center animate-in zoom-in-95 duration-200">
                <Skull className="w-16 h-16 text-red-500 mx-auto mb-4" />
                <h2 className="text-2xl font-bold text-white mb-2">ABANDONAR TORNEIO?</h2>
                <p className="text-gray-400 mb-8">Todo o progresso atual será perdido e você voltará para a tela de apostas.</p>

                <div className="flex space-x-4">
                    <button 
                        onClick={() => setShowExitConfirm(false)}
                        className="flex-1 py-3 bg-gray-700 hover:bg-gray-600 text-white font-bold rounded-lg"
                    >
                        CANCELAR
                    </button>
                    <button 
                        onClick={() => {
                            setShowExitConfirm(false);
                            setIsPaused(false);
                            handleExitTournament();
                        }}
                        className="flex-1 py-3 bg-red-600 hover:bg-red-500 text-white font-bold rounded-lg shadow-lg hover:shadow-red-500/50 transition-all"
                    >
                        SAIR
                    </button>
                </div>
             </div>
        </div>
      )}

      {/* Round Result Modal - 3 Seconds Duration */}
      {gameState.phase === 'round_result' && (
        <div className="absolute inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-gray-800 rounded-2xl p-8 max-w-sm w-full text-center border border-gray-700 shadow-2xl animate-in slide-in-from-bottom-10 fade-in duration-300 relative overflow-hidden">
            <h2 className="text-3xl font-bold text-white mb-6 brand-font">FIM DA RODADA {gameState.round}</h2>

            {gameState.gameMode === 'elimination' ? (
              <div className="bg-red-900/20 border border-red-500/50 p-4 rounded-xl mb-6">
                 <Skull className="w-8 h-8 text-red-500 mx-auto mb-2" />
                 <div className="text-red-400 font-bold text-sm uppercase mb-1">Eliminado</div>
                 {gameState.lastEliminatedId !== null && (
                   <div className="flex items-center justify-center space-x-2 mt-2">
                      <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                         <TeamLogo marble={gameState.marbles.find(m => m.id === gameState.lastEliminatedId)} />
                      </div>
                      <span className="text-xl text-white font-mono">
                        {gameState.marbles.find(m => m.id === gameState.lastEliminatedId)?.name}
                      </span>
                   </div>
                 )}
              </div>
            ) : (
              <div className="bg-gray-900/50 border border-gray-600 p-4 rounded-xl mb-6 max-h-[300px] overflow-y-auto">
                 <div className="flex items-center justify-center mb-4 text-yellow-400">
                    <Medal className="mr-2" /> Resultado da Rodada
                 </div>
                 {[...activeMarblesList].sort((a,b) => a.rank - b.rank).map((m, idx) => (
                   <div key={m.id} className="flex justify-between items-center py-2 border-b border-gray-700 last:border-0 text-sm">
                      <div className="flex items-center space-x-2">
                         <span className="w-4 text-gray-500">{idx + 1}</span>
                         <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                            <TeamLogo marble={m} />
                         </div>
                         <span>{m.name}</span>
                      </div>
                      <div className="flex flex-col text-right">
                        <span className="text-green-400 font-bold">+{gameState.roundPoints[m.id]}</span>
                        <span className="text-[10px] text-gray-500">Total: {m.score}</span>
                      </div>
                   </div>
                 ))}
              </div>
            )}

            {gameState.gameMode === 'elimination' && gameState.lastEliminatedId === gameState.betMarbleId && (
              <div className="text-red-400 text-sm font-bold mb-6">
                SEU TIME FOI ELIMINADO! 😱
              </div>
            )}

            {/* Auto Advance Progress Bar - 3 Seconds */}
            <div className="mt-4">
                <p className="text-gray-400 text-xs mb-2 uppercase tracking-widest">Próxima rodada em instantes...</p>
                <div className="w-full h-2 bg-gray-700 rounded-full overflow-hidden">
                    <div className="h-full bg-blue-500 animate-[width_3s_linear] w-full origin-left" style={{ animationDuration: '3s', animationName: 'shrink', animationTimingFunction: 'linear', animationFillMode: 'forwards' }}></div>
                    <style>{`
                        @keyframes shrink {
                            from { width: 100%; }
                            to { width: 0%; }
                        }
                    `}</style>
                </div>
            </div>

          </div>
        </div>
      )}

      {/* Bet Indicator (Bottom) - Toggle Camera */}
      {gameState.phase === 'racing' && (
        <button
           onClick={() => setIsFollowingBet(!isFollowingBet)}
           className={`absolute bottom-6 left-1/2 transform -translate-x-1/2 px-6 py-2 rounded-full border flex items-center space-x-2 transition-all shadow-lg hover:scale-105 active:scale-95 z-40 ${isFollowingBet ? 'bg-yellow-900/80 border-yellow-400' : 'bg-black/60 border-yellow-500/30'}`}
        >
           {isFollowingBet ? <Camera className="w-4 h-4 text-yellow-400 animate-pulse" /> : <Camera className="w-4 h-4 text-gray-400" />}

           {isFollowingBet ? (
               <div className="flex items-center space-x-2">
                   <div className="w-6 h-6 rounded-full bg-gray-200 flex items-center justify-center p-0.5">
                       <TeamLogo marble={gameState.marbles.find(m => m.id === gameState.betMarbleId)} />
                   </div>
                   <span className="font-bold text-yellow-400">{gameState.marbles.find(m => m.id === gameState.betMarbleId)?.name}</span>
               </div>
           ) : (
               <span className="text-gray-300 font-bold uppercase text-sm">CÂMERA: LÍDER</span>
           )}
        </button>
      )}

    </div>
  );
}

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- NOVO OBSTÁCULO: LINHAS INTERMITENTES INCLINADAS (Logo após a largada) ---
    // Ajustado para começar mais perto da largada já que removemos o funil
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 5;
    const plinkoRowHeight = 70;
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // 1. Start Box (Horse Race Style)
    // Wide area at top to fit all marbles horizontally. Extends straight down to Plinko start.
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoStartY, type: 'wall' }); // Left Wall
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoStartY, type: 'wall' }); // Right Wall

    // Funnel REMOVED as requested. Walls above cover the gap.

    // Paredes laterais para a área das linhas (Plinko Section)
    lines.push({ x1: 0, y1: plinkoStartY, x2: 0, y2: plinkoEndY, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: plinkoStartY, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' });

    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        // Intercalar as linhas (linhas pares x ímpares)
        const stagger = (r % 2 === 0) ? 0 : 45; 

        // Desenhar linhas tracejadas ao longo da largura
        for (let px = 10; px < COURSE_WIDTH; px += 90) {
            // Verificar limites para não desenhar fora ou colado na parede
            if (px + stagger + 50 < COURSE_WIDTH) {
                lines.push({
                    x1: px + stagger,
                    y1: py,
                    x2: px + stagger + 50, // Comprimento da linha
                    y2: py + 15,           // Inclinação para baixo (y2 > y1)
                    type: 'wall'
                });
            }
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    // Parede Funil Esquerda
    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Parede Funil Direita
    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Atualizar onde começa a geração procedural
    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type === 'spinner') {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type === 'slider_h') {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type === 'slider_v') {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type === 'repulsor') {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type === 'conveyor') {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type === 'teleporter') {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        // --- HOLLOW CIRCLE (New Obstacle) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
           id: `hollow_${i}`,
           type: 'hollow_circle',
           x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60,
           y: currentY + 250,
           width: 250, // Diameter
           angle: 0,
           speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02),
           range: Math.PI / 2.5 // Gap size
        });

      } else if (type === 'laser') {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        // --- BIG FUNNEL ---
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; // Marbles are radius 18 (diam 36). 55 gives clearance.

        // Left Angle Wall
        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Right Angle Wall
        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Chaos Pin below the exit to scatter them
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate Logic - Handle start
    const timeSinceStart = Date.now() - startTime.current;

    // If we haven't opened the gate yet
    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); // Loud gong/sound for start
            spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8); // Explosion of green particles
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const hollowCircles: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }
      if (obj.type === 'hollow_circle') { hollowCircles.push(obj); }

      if (obj.type !== 'hollow_circle') {
          solidDynamics.push(obj);
      }

      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    // START GATE PHYSICAL BARRIER
    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Hollow Circle Physics
        for (const circle of hollowCircles) {
           const dx = m.x - circle.x;
           const dy = m.y - circle.y;
           const dist = Math.sqrt(dx*dx + dy*dy);
           const r = (circle.width / 2);
           const thickness = 6;

           if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
               let angle = Math.atan2(dy, dx);
               if (angle < 0) angle += Math.PI * 2;

               let rot = circle.angle % (Math.PI * 2);
               if (rot < 0) rot += Math.PI * 2;

               let diff = Math.abs(angle - rot);
               if (diff > Math.PI) diff = Math.PI * 2 - diff; 

               const halfGap = (circle.range || 1.0) / 2;

               if (diff < halfGap) {
                   // Inside gap
               } else {
                   const nx = dx / dist;
                   const ny = dy / dist;

                   const pushSign = dist < r ? -1 : 1;
                   const overlap = (m.radius + thickness) - Math.abs(dist - r);

                   if (overlap > 0) {
                       m.x += nx * pushSign * overlap * 0.5;
                       m.y += ny * pushSign * overlap * 0.5;

                       const nX = nx * pushSign;
                       const nY = ny * pushSign;

                       const dot = m.vx * nX + m.vy * nY;

                       m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                       m.vy = (m.vy - 2 * dot * nY) * config.restitution;

                       m.vx *= config.friction;
                       m.vy *= config.friction;
                   }
               }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // CHECK GATE COLLISION
        if (!gateOpenRef.current) {
            checkLineCollision(m, gateLine);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic - STRICTLY follow the first place marble
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Changed: Do NOT average top 3. Just take the leader.
          // This ensures the camera stays with the leader even if they are far ahead.
          targetY = activeMarblesList[0].y - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false; // Reset Gate
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // HORIZONTAL START POSITIONS
    const totalWidth = COURSE_WIDTH * 0.9;
    const startX = COURSE_WIDTH * 0.05;
    const spacing = totalWidth / Math.max(1, activeMarbles.length);

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: startX + (spacing * index) + (spacing/2), // Evenly spaced horizontally
      y: GATE_Y - 50, // Just above the gate
      vx: 0,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;

             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.lineCap = 'round'; 
             ctx.stroke();

             ctx.beginPath();
             ctx.arc(0, 0, r - 10, 0, Math.PI * 2);
             ctx.strokeStyle = 'rgba(217, 70, 239, 0.3)';
             ctx.lineWidth = 2;
             ctx.stroke();
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // DRAW GATE (If Closed)
    if (!gateOpenRef.current) {
        ctx.beginPath();
        ctx.moveTo(0, GATE_Y);
        ctx.lineTo(COURSE_WIDTH, GATE_Y);
        ctx.strokeStyle = '#ef4444'; // Red barrier
        ctx.lineWidth = 10;
        ctx.stroke();

        // Draw Countdown Text
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));

        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = 'bold 80px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), COURSE_WIDTH / 2, GATE_Y + 150);
        ctx.font = '20px "Roboto Mono"';
        ctx.fillText("PREPARAR...", COURSE_WIDTH / 2, GATE_Y + 180);
    }

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Logo Image clipped to circle
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        // Draw Background Circle (White) to make transparency logos pop
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        ctx.save();
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        // Fallback if image fails or no URL
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color;
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Draw Name Abbreviation inside
        ctx.save();
        // Since we are rotated by -m.angle, drawing text here will make it spin with the marble
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
        ctx.restore();
      }

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- NOVO OBSTÁCULO: ESTEIRAS ZIG-ZAG INFINITAS ---
    // Substitui a antiga Plinko por 4 linhas de esteiras alternadas
    const zigZagStartY = GATE_Y + 80;
    const zigZagRows = 4;
    const zigZagRowHeight = 110; 
    const zigZagEndY = zigZagStartY + (zigZagRows * zigZagRowHeight);

    // 1. Start Box (Horse Race Style)
    lines.push({ x1: 0, y1: 0, x2: 0, y2: zigZagStartY, type: 'wall' }); // Left Wall
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: zigZagStartY, type: 'wall' }); // Right Wall

    // Paredes laterais para a área das esteiras
    lines.push({ x1: 0, y1: zigZagStartY, x2: 0, y2: zigZagEndY, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: zigZagStartY, x2: COURSE_WIDTH, y2: zigZagEndY, type: 'wall' });

    for (let r = 0; r < zigZagRows; r++) {
        // Linhas Pares (0, 2): Inclinadas para Direita, Movem para Direita
        // Linhas Ímpares (1, 3): Inclinadas para Esquerda, Movem para Esquerda
        const isRight = r % 2 === 0; 

        const gapSize = 110; // Espaço para cair na ponta
        const beltLength = COURSE_WIDTH - gapSize;

        // Calcular centro da esteira para que ela encoste na parede de origem e deixe o gap na destino
        // Se vai pra direita: começa no x=0 (encostado esquerda), termina em width-gap
        // Se vai pra esquerda: começa no x=gap, termina em width (encostado direita)

        let cx;
        if (isRight) {
             cx = (beltLength / 2) - 10; // Leve overlap na parede esquerda
        } else {
             cx = COURSE_WIDTH - (beltLength / 2) + 10; // Leve overlap na parede direita
        }

        const cy = zigZagStartY + (r * zigZagRowHeight) + 60;

        // Ângulo positivo gira horário (Baixo-Direita). Negativo gira anti-horário (Baixo-Esquerda).
        const slope = 0.15; // ~8.5 graus
        const angle = isRight ? slope : -slope;

        dynamics.push({
            id: `zigzag_conveyor_${r}`,
            type: 'conveyor',
            x: cx,
            y: cy,
            width: beltLength + 20, 
            height: 25, // Espessura
            angle: angle,
            // A velocidade visual (offset) e a força física
            speed: isRight ? 0.08 : -0.08, 
            force: 25 // Força forte para garantir que a esteira empurre
        });

        // Adicionar um bumper na parede oposta do gap para evitar que bolinhas fiquem presas no canto
        const bumperX = isRight ? COURSE_WIDTH : 0;
        // pins.push({ x: bumperX, y: cy + 30, radius: 20, type: 'bumper' });
    }

    // --- FUNIL PÓS-ESTEIRAS ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    // Parede Funil Esquerda
    lines.push({
        x1: 0, y1: zigZagEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: zigZagEndY + funnelHeight,
        type: 'wall'
    });

    // Parede Funil Direita
    lines.push({
        x1: COURSE_WIDTH, y1: zigZagEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: zigZagEndY + funnelHeight,
        type: 'wall'
    });

    // Atualizar onde começa a geração procedural
    currentY = zigZagEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type === 'spinner') {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type === 'slider_h') {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type === 'slider_v') {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type === 'repulsor') {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type === 'conveyor') {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type === 'teleporter') {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        // --- HOLLOW CIRCLE (New Obstacle) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
           id: `hollow_${i}`,
           type: 'hollow_circle',
           x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60,
           y: currentY + 250,
           width: 250, // Diameter
           angle: 0,
           speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02),
           range: Math.PI / 2.5 // Gap size
        });

      } else if (type === 'laser') {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        // --- BIG FUNNEL ---
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; // Marbles are radius 18 (diam 36). 55 gives clearance.

        // Left Angle Wall
        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Right Angle Wall
        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Chaos Pin below the exit to scatter them
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const imagesRef = useRef<Record<string, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const finishLineY = useRef(0);
  const raceFinished = useRef(false);
  const finishedMarbles = useRef<Marble[]>([]);
  const gateOpen = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180;

  // Initialize Marbles
  useEffect(() => {
    // Deep copy to avoid mutating props directly if they are reused
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 100, // Random start x
      y: 50 + Math.floor(i / 5) * 40, // Staggered start y
      vx: 0,
      vy: 0,
      finished: false,
      rank: 0
    }));

    // Load Images
    activeMarbles.forEach(m => {
        if (m.logoUrl && !imagesRef.current[m.name]) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.name] = img;
        }
    });

    generateLevel();
    finishedMarbles.current = [];
    raceFinished.current = false;
    gateOpen.current = false;

    setTimeout(() => {
        gateOpen.current = true;
        audio.playFinish(); // Start whistle
    }, 3000);

    // Start Loop
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [activeMarbles]); 

  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;

    // ZigZag Section
    const zigZagStartY = GATE_Y + 80;
    const zigZagRows = 4;
    const zigZagRowHeight = 110; 
    const zigZagEndY = zigZagStartY + (zigZagRows * zigZagRowHeight);

    lines.push({ x1: 0, y1: 0, x2: 0, y2: zigZagStartY, type: 'wall' }); 
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: zigZagStartY, type: 'wall' }); 

    lines.push({ x1: 0, y1: zigZagStartY, x2: 0, y2: zigZagEndY, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: zigZagStartY, x2: COURSE_WIDTH, y2: zigZagEndY, type: 'wall' });

    for (let r = 0; r < zigZagRows; r++) {
        const isRight = r % 2 === 0; 
        const gapSize = 110; 
        const beltLength = COURSE_WIDTH - gapSize;
        let cx;
        if (isRight) {
             cx = (beltLength / 2) - 10; 
        } else {
             cx = COURSE_WIDTH - (beltLength / 2) + 10; 
        }

        const cy = zigZagStartY + (r * zigZagRowHeight) + 60;
        const slope = 0.15; 
        const angle = isRight ? slope : -slope;

        dynamics.push({
            id: `zigzag_conveyor_${r}`,
            type: 'conveyor',
            x: cx,
            y: cy,
            width: beltLength + 20, 
            height: 25, 
            angle: angle,
            speed: isRight ? 0.08 : -0.08, 
            force: 25 
        });
    }

    const funnelHeight = 180;
    const funnelExitGap = 70;

    lines.push({
        x1: 0, y1: zigZagEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: zigZagEndY + funnelHeight,
        type: 'wall'
    });

    lines.push({
        x1: COURSE_WIDTH, y1: zigZagEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: zigZagEndY + funnelHeight,
        type: 'wall'
    });

    let currentY = zigZagEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 200 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 200, angle: 0, speed: -3.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 
        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });
        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: currentY + 250, width: width, height: height, angle: angle, speed: 0.1, force: 18 });

      } else if (type === 'teleporter') {
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        let targetY = isTrap ? Math.max(100, currentY - (300 + Math.random() * 400)) : currentY + (500 + Math.random() * 300);
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 200, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, blinkPhase: Math.random() * Math.PI * 2, blinkSpeed: 0.02 + Math.random() * 0.02, active: true });
        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60, y: currentY + 250, width: 250, angle: 0, speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02), range: Math.PI / 2.5 });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.1, y: currentY + 300, width: 0, height: COURSE_WIDTH * 0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;
    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  const loop = () => {
    update();
    draw();
    requestRef.current = requestAnimationFrame(loop);
  };

  const update = () => {
    if (isPaused) return;
    const marbles = marblesRef.current;
    if (marbles.length === 0) return;

    if (!gateOpen.current) return;

    // Dynamic Updates
    dynamicRef.current.forEach(obs => {
        if (obs.type === 'spinner') obs.angle += obs.speed!;
        else if (obs.type === 'slider_h') {
             obs.x += obs.speed!;
             if (Math.abs(obs.x - (obs.initialX || obs.x)) > (obs.range || 0) / 2) obs.speed = -obs.speed!;
        } else if (obs.type === 'slider_v') {
             obs.y += obs.speed!;
             if (Math.abs(obs.y - (obs.initialY || obs.y)) > (obs.range || 0) / 2) obs.speed = -obs.speed!;
        } else if (obs.type === 'laser') {
            obs.timer = (obs.timer || 0) + 1;
            if (obs.timer > 100) { obs.active = !obs.active; obs.timer = 0; }
        } else if (obs.type === 'teleporter') {
            obs.blinkPhase = (obs.blinkPhase || 0) + (obs.blinkSpeed || 0.05);
        } else if (obs.type === 'hollow_circle') {
            obs.angle += obs.speed!;
        }
    });

    const dt = 0.2; 

    marbles.forEach(marble => {
        if (marble.finished) return;

        marble.vy += config.gravity * dt;
        marble.vx *= config.friction;
        marble.vy *= config.friction;

        marble.x += marble.vx * dt;
        marble.y += marble.vy * dt;

        linesRef.current.forEach(line => {
             const minX = Math.min(line.x1, line.x2) - marble.radius;
             const maxX = Math.max(line.x1, line.x2) + marble.radius;
             const minY = Math.min(line.y1, line.y2) - marble.radius;
             const maxY = Math.max(line.y1, line.y2) + marble.radius;

             if (marble.x < minX || marble.x > maxX || marble.y < minY || marble.y > maxY) return;

             const dx = line.x2 - line.x1;
             const dy = line.y2 - line.y1;
             const len2 = dx*dx + dy*dy;
             let t = ((marble.x - line.x1) * dx + (marble.y - line.y1) * dy) / len2;
             t = Math.max(0, Math.min(1, t));
             const closeX = line.x1 + t * dx;
             const closeY = line.y1 + t * dy;

             const distX = marble.x - closeX;
             const distY = marble.y - closeY;
             const dist = Math.sqrt(distX*distX + distY*distY);

             if (dist < marble.radius) {
                 const nx = distX / dist;
                 const ny = distY / dist;
                 const overlap = marble.radius - dist;

                 marble.x += nx * overlap;
                 marble.y += ny * overlap;

                 const dot = marble.vx * nx + marble.vy * ny;
                 marble.vx -= 2 * dot * nx * config.restitution;
                 marble.vy -= 2 * dot * ny * config.restitution;

                 audio.playBump(Math.abs(dot));
             }
        });

        dynamicRef.current.forEach(obs => {
            if (obs.type === 'spinner') {
                const r = obs.width / 2;
                const dist = Math.sqrt((marble.x - obs.x)**2 + (marble.y - obs.y)**2);
                if (dist < r + marble.radius) {
                     const angle = Math.atan2(marble.y - obs.y, marble.x - obs.x);
                     marble.vx += Math.cos(angle) * 1;
                     marble.vy += Math.sin(angle) * 1;
                }
            } else if (obs.type === 'conveyor') {
                const dx = marble.x - obs.x;
                const dy = marble.y - obs.y;
                const localX = dx * Math.cos(-obs.angle) - dy * Math.sin(-obs.angle);
                const localY = dx * Math.sin(-obs.angle) + dy * Math.cos(-obs.angle);

                if (Math.abs(localX) < obs.width/2 && Math.abs(localY) < obs.height!/2) {
                     marble.vx += Math.cos(obs.angle) * (obs.speed! * obs.force!);
                     marble.vy += Math.sin(obs.angle) * (obs.speed! * obs.force!);
                }
            }
        });

        if (marble.y >= finishLineY.current && !marble.finished) {
            marble.finished = true;
            marble.finishTime = Date.now();
            finishedMarbles.current.push(marble);
            marble.rank = finishedMarbles.current.length;

            spawnParticles(marble.x, marble.y, marble.color, 20, 5);
            audio.playFinish();

            if (finishedMarbles.current.length === marbles.length) {
                raceFinished.current = true;
                onRaceFinish(finishedMarbles.current);
            }
        }
    });

    let targetY = 0;
    if (isFollowingBet && betMarbleId !== null) {
        const betM = marbles.find(m => m.id === betMarbleId);
        if (betM) targetY = betM.y - 300;
    } else {
        const leader = marbles.reduce((prev, curr) => (curr.y > prev.y ? curr : prev), marbles[0]);
        targetY = leader ? leader.y - 300 : 0;
    }
    cameraY.current += (targetY - cameraY.current) * 0.1;
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    ctx.translate(0, -cameraY.current);

    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 5;
    ctx.beginPath();
    linesRef.current.forEach(l => {
        ctx.moveTo(l.x1, l.y1);
        ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    dynamicRef.current.forEach(obs => {
        ctx.save();
        ctx.translate(obs.x, obs.y);
        ctx.rotate(obs.angle);

        if (obs.type === 'spinner') {
            ctx.fillStyle = '#EF4444';
            ctx.fillRect(-obs.width/2, -10, obs.width, 20);
        } else if (obs.type === 'conveyor') {
            ctx.fillStyle = '#3B82F6';
            ctx.globalAlpha = 0.5;
            ctx.fillRect(-obs.width/2, -obs.height!/2, obs.width, obs.height!);
            ctx.fillStyle = '#fff';
            for(let k=-obs.width/2; k<obs.width/2; k+=40) {
                 ctx.fillText(obs.speed! > 0 ? '>>' : '<<', k, 5);
            }
            ctx.globalAlpha = 1;
        }
        ctx.restore();
    });

    marblesRef.current.forEach(m => {
        ctx.save();
        ctx.translate(m.x, m.y);

        ctx.beginPath();
        ctx.arc(2, 2, m.radius, 0, Math.PI*2);
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fill();

        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI*2);
        ctx.fillStyle = m.color;
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.stroke();

        const img = imagesRef.current[m.name];
        if (img) {
             ctx.beginPath();
             ctx.arc(0, 0, m.radius, 0, Math.PI*2);
             ctx.clip();
             ctx.drawImage(img, -m.radius, -m.radius, m.radius*2, m.radius*2);
        } else {
            ctx.fillStyle = '#fff';
            ctx.font = '10px bold sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(m.name.substring(0,3).toUpperCase(), 0, 0);
        }

        ctx.restore();
    });

    particlesRef.current.forEach((p, i) => {
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
            return;
        }
        p.x += p.vx;
        p.y += p.vy;
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI*2);
        ctx.fill();
        ctx.globalAlpha = 1.0;
    });

    ctx.strokeStyle = '#10B981';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(0, finishLineY.current);
    ctx.lineTo(COURSE_WIDTH, finishLineY.current);
    ctx.stroke();

    ctx.restore();
  };

  return <canvas ref={canvasRef} width={600} height={800} className="w-full h-full object-cover md:object-contain" />;
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;
  const GATE_Y = 180; // Position of the starting gate
  const GATE_DELAY = 3000; // Time before gate opens (ms)

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // Config
    const segments = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;
    let currentY = 0;

    // --- OBSTÁCULO: LINHAS INTERMITENTES (PLINKO) ---
    // Restaurado da versão estável
    const plinkoStartY = GATE_Y + 100;
    const plinkoRows = 5;
    const plinkoRowHeight = 70;
    const plinkoEndY = plinkoStartY + (plinkoRows * plinkoRowHeight);

    // 1. Start Box (Horse Race Style)
    lines.push({ x1: 0, y1: 0, x2: 0, y2: plinkoStartY, type: 'wall' }); // Left Wall
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH, y2: plinkoStartY, type: 'wall' }); // Right Wall

    // Paredes laterais para a área das linhas (Plinko Section)
    lines.push({ x1: 0, y1: plinkoStartY, x2: 0, y2: plinkoEndY, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: plinkoStartY, x2: COURSE_WIDTH, y2: plinkoEndY, type: 'wall' });

    for (let r = 0; r < plinkoRows; r++) {
        const py = plinkoStartY + (r * plinkoRowHeight);
        // Intercalar as linhas (linhas pares x ímpares)
        const stagger = (r % 2 === 0) ? 0 : 45; 

        // Desenhar linhas tracejadas ao longo da largura
        for (let px = 10; px < COURSE_WIDTH; px += 90) {
            // Verificar limites para não desenhar fora ou colado na parede
            if (px + stagger + 50 < COURSE_WIDTH) {
                lines.push({
                    x1: px + stagger,
                    y1: py,
                    x2: px + stagger + 50, // Comprimento da linha
                    y2: py + 15,           // Inclinação para baixo (y2 > y1)
                    type: 'wall'
                });
            }
        }
    }

    // --- FUNIL PÓS-PLINKO ---
    const funnelHeight = 180;
    const funnelExitGap = 70;

    // Parede Funil Esquerda
    lines.push({
        x1: 0, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 - funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Parede Funil Direita
    lines.push({
        x1: COURSE_WIDTH, y1: plinkoEndY,
        x2: COURSE_WIDTH / 2 + funnelExitGap / 2, y2: plinkoEndY + funnelHeight,
        type: 'wall'
    });

    // Atualizar onde começa a geração procedural
    currentY = plinkoEndY + funnelHeight + 50;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    // 2. Procedural Segments
    for (let i = 0; i < segments; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      // -- DYNAMIC MOVING OBSTACLES --

      if (type === 'spinner') {
        // --- DOUBLE SPINNERS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `spin_${i}_1`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.35,
          y: currentY + 250,
          width: 150,
          angle: 0,
          speed: 0.12,
        });
        dynamics.push({
          id: `spin_${i}_2`,
          type: 'spinner',
          x: COURSE_WIDTH * 0.65,
          y: currentY + 350,
          width: 150,
          angle: Math.PI / 2,
          speed: -0.15,
        });

      } else if (type === 'slider_h') {
        // --- MOVING SLIDERS (Cross Horizontal) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({
            id: `slide_h_top_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 200,
            width: 200,
            angle: 0,
            speed: 2.5,
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 200
        });

        dynamics.push({
            id: `slide_h_bot_${i}`,
            type: 'slider_h',
            x: COURSE_WIDTH / 2,
            y: currentY + 350,
            width: 200,
            angle: 0,
            speed: -3.0, 
            range: 180,
            initialX: COURSE_WIDTH / 2,
            initialY: currentY + 350
        });

      } else if (type === 'slider_v') {
        // --- VERTICAL CRUSHERS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
            id: `slide_v_L_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.25,
            y: currentY + 250,
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.25,
            initialY: currentY + 250
        });

        dynamics.push({
            id: `slide_v_R_${i}`,
            type: 'slider_v',
            x: COURSE_WIDTH * 0.75,
            y: currentY + 350, 
            width: 120,
            angle: 0,
            speed: 1.5,
            range: 80,
            initialX: COURSE_WIDTH * 0.75,
            initialY: currentY + 350
        });

      } else if (type === 'repulsor') {
        // --- REPULSORS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `repulse_${i}`,
          type: 'repulsor',
          x: COURSE_WIDTH / 2,
          y: currentY + 300,
          width: 50, 
          range: 140, 
          angle: 0,
          speed: 0.1, 
          force: 3.0
        });

      } else if (type === 'conveyor') {
        // --- CONVEYOR BELTS ---
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 

        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({
          id: `conveyor_${i}`,
          type: 'conveyor',
          x: cx,
          y: currentY + 250,
          width: width, 
          height: height, 
          angle: angle, 
          speed: 0.1, 
          force: 18 
        });

      } else if (type === 'teleporter') {
        // --- ADVANCED TELEPORTERS ---
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);

        let targetY;
        if (isTrap) {
            targetY = Math.max(100, currentY - (300 + Math.random() * 400));
        } else {
            targetY = currentY + (500 + Math.random() * 300);
        }

        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
          id: `teleport_${i}`,
          type: 'teleporter',
          x: entranceX,
          y: currentY + 200,
          width: 70, 
          destX: exitX,
          destY: targetY,
          angle: 0,
          speed: 0,
          blinkPhase: Math.random() * Math.PI * 2,
          blinkSpeed: 0.02 + Math.random() * 0.02, 
          active: true
        });

        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        // --- HOLLOW CIRCLE (New Obstacle) ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        dynamics.push({
           id: `hollow_${i}`,
           type: 'hollow_circle',
           x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60,
           y: currentY + 250,
           width: 250, // Diameter
           angle: 0,
           speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02),
           range: Math.PI / 2.5 // Gap size
        });

      } else if (type === 'laser') {
        // --- LASER CANNONS ---
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({
          id: `laser_${i}`,
          type: 'laser',
          x: COURSE_WIDTH * 0.1, 
          y: currentY + 300,
          width: 0, 
          height: COURSE_WIDTH * 0.8, 
          angle: 0, 
          speed: 0,
          force: 25, 
          active: true,
          timer: 0
        });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        // --- BIG FUNNEL ---
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55; // Marbles are radius 18 (diam 36). 55 gives clearance.

        // Left Angle Wall
        lines.push({
            x1: 0, y1: funnelTopY,
            x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Right Angle Wall
        lines.push({
            x1: COURSE_WIDTH, y1: funnelTopY,
            x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight,
            type: 'wall'
        });

        // Chaos Pin below the exit to scatter them
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
         // --- WIND CANNONS ---
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({
          id: `fan_${i}_1`,
          type: 'fan',
          x: 20, 
          y: currentY + 250,
          width: 40,
          height: 300, 
          angle: 0, 
          speed: 0,
          force: 0.7
        });

        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    // 3. Finish Area
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate Logic - Handle start
    const timeSinceStart = Date.now() - startTime.current;

    // If we haven't opened the gate yet
    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); // Loud gong/sound for start
            spawnParticles(COURSE_WIDTH/2, GATE_Y, '#10b981', 30, 8); // Explosion of green particles
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Separate dynamic types
    const fans: DynamicObstacle[] = [];
    const repulsors: DynamicObstacle[] = [];
    const conveyors: DynamicObstacle[] = [];
    const lasers: DynamicObstacle[] = [];
    const teleporters: DynamicObstacle[] = [];
    const hollowCircles: DynamicObstacle[] = [];
    const solidDynamics: DynamicObstacle[] = [];

    dynamicObjs.forEach(obj => {
      if (obj.type === 'fan') { fans.push(obj); return; }
      if (obj.type === 'repulsor') { repulsors.push(obj); return; }
      if (obj.type === 'conveyor') { conveyors.push(obj); return; }
      if (obj.type === 'laser') { lasers.push(obj); return; }
      if (obj.type === 'teleporter') { teleporters.push(obj); return; }
      if (obj.type === 'hollow_circle') { hollowCircles.push(obj); }

      if (obj.type !== 'hollow_circle') {
          solidDynamics.push(obj);
      }

      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      }
    });

    lasers.forEach(l => {
       l.timer = (l.timer || 0) + 1;
       if (l.timer > 180) {
           l.active = !l.active;
           l.timer = 0;
       }
    });

    // Update Teleporter Opacity/State (Intermittent logic)
    teleporters.forEach(t => {
        if (t.blinkPhase !== undefined && t.blinkSpeed !== undefined) {
            const val = Math.sin(timeRef.current * t.blinkSpeed + t.blinkPhase);
            const opacity = (val + 1) / 2; 
            t.active = opacity > 0.3; 
            t.timer = opacity; 
        }
    });

    const dynamicLines: LineSegment[] = [];
    solidDynamics.forEach(obj => {
      const halfW = obj.width / 2;
      const dx = Math.cos(obj.angle) * halfW;
      const dy = Math.sin(obj.angle) * halfW;
      dynamicLines.push({
        x1: obj.x - dx, y1: obj.y - dy,
        x2: obj.x + dx, y2: obj.y + dy,
        type: obj.type === 'spinner' ? 'bouncer' : 'floor'
      });
    });

    // START GATE PHYSICAL BARRIER
    const gateLine: LineSegment = { x1: 0, y1: GATE_Y, x2: COURSE_WIDTH, y2: GATE_Y, type: 'wall' };

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // Fan Physics
        for (const fan of fans) {
          const dx = m.x - fan.x;
          const dy = m.y - fan.y;
          const localX = dx * Math.cos(-fan.angle) - dy * Math.sin(-fan.angle);
          const localY = dx * Math.sin(-fan.angle) + dy * Math.cos(-fan.angle);
          const halfWidth = fan.width / 2; 
          const range = fan.height || 200;

          if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
             const force = fan.force || 0.5;
             const forceX = Math.cos(fan.angle) * force;
             const forceY = Math.sin(fan.angle) * force;
             m.vx += forceX * dt;
             m.vy += forceY * dt;

             if (Math.random() < 0.1) {
                spawnParticles(m.x, m.y, '#e2e8f0', 1, 1);
             }
          }
        }

        // Repulsor Physics
        for (const rep of repulsors) {
          const dx = m.x - rep.x;
          const dy = m.y - rep.y;
          const distSq = dx*dx + dy*dy;
          const range = rep.range || 100;

          if (distSq < range * range) {
             const dist = Math.sqrt(distSq);
             const nx = dx / dist;
             const ny = dy / dist;
             const pulse = (Math.sin(timeRef.current * rep.speed) + 1) * 0.5;
             const force = (rep.force || 1) * (1 - dist/range) * (0.5 + pulse);
             m.vx += nx * force * dt * 50;
             m.vy += ny * force * dt * 50;
          }
        }

        // Conveyor Physics
        for (const conv of conveyors) {
           const dx = m.x - conv.x;
           const dy = m.y - conv.y;

           const localParallel = dx * Math.cos(-conv.angle) - dy * Math.sin(-conv.angle); 
           const localPerp = dx * Math.sin(-conv.angle) + dy * Math.cos(-conv.angle); 

           const halfLength = conv.width / 2;
           const halfWidth = (conv.height || 50) / 2;

           if (Math.abs(localParallel) < halfLength && Math.abs(localPerp) < halfWidth) {
              const force = conv.force || 10;
              const forceX = Math.cos(conv.angle) * force;
              const forceY = Math.sin(conv.angle) * force;
              m.vx += forceX * dt;
              m.vy += forceY * dt;

              if (Math.random() < 0.05) {
                 spawnParticles(m.x, m.y, 'rgba(255,255,255,0.3)', 1, 0.5);
              }
           }
        }

        // Hollow Circle Physics
        for (const circle of hollowCircles) {
           const dx = m.x - circle.x;
           const dy = m.y - circle.y;
           const dist = Math.sqrt(dx*dx + dy*dy);
           const r = (circle.width / 2);
           const thickness = 6;

           if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
               let angle = Math.atan2(dy, dx);
               if (angle < 0) angle += Math.PI * 2;

               let rot = circle.angle % (Math.PI * 2);
               if (rot < 0) rot += Math.PI * 2;

               let diff = Math.abs(angle - rot);
               if (diff > Math.PI) diff = Math.PI * 2 - diff; 

               const halfGap = (circle.range || 1.0) / 2;

               if (diff < halfGap) {
                   // Inside gap
               } else {
                   const nx = dx / dist;
                   const ny = dy / dist;

                   const pushSign = dist < r ? -1 : 1;
                   const overlap = (m.radius + thickness) - Math.abs(dist - r);

                   if (overlap > 0) {
                       m.x += nx * pushSign * overlap * 0.5;
                       m.y += ny * pushSign * overlap * 0.5;

                       const nX = nx * pushSign;
                       const nY = ny * pushSign;

                       const dot = m.vx * nX + m.vy * nY;

                       m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                       m.vy = (m.vy - 2 * dot * nY) * config.restitution;

                       m.vx *= config.friction;
                       m.vy *= config.friction;
                   }
               }
           }
        }

        // Laser Physics
        for (const laser of lasers) {
            if (!laser.active) continue;
            const len = laser.height || 300;
            const lx1 = laser.x;
            const ly1 = laser.y;
            const lx2 = lx1 + Math.cos(laser.angle) * len;
            const ly2 = ly1 + Math.sin(laser.angle) * len;

            const A = m.x - lx1;
            const B = m.y - ly1;
            const C = lx2 - lx1;
            const D = ly2 - ly1;

            const dot = A * C + B * D;
            const lenSq = C * C + D * D;
            let param = -1;
            if (lenSq !== 0) param = dot / lenSq;

            let xx, yy;

            if (param < 0) {
                xx = lx1; yy = ly1;
            } else if (param > 1) {
                xx = lx2; yy = ly2;
            } else {
                xx = lx1 + param * C;
                yy = ly1 + param * D;
            }

            const dx = m.x - xx;
            const dy = m.y - yy;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < m.radius + 5) { 
                const force = laser.force || 20;
                m.vx += (dx/dist) * force * dt * 10;
                m.vy += (dy/dist) * force * dt * 10;
                m.vx += (Math.random() - 0.5) * 10;
                m.vy += (Math.random() - 0.5) * 10;
                spawnParticles(m.x, m.y, '#ef4444', 3, 4);
            }
        }

        // Teleporter Physics
        for (const tele of teleporters) {
            if (!tele.active) continue; 

            const dx = m.x - tele.x;
            const dy = m.y - tele.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < (tele.width/2) && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {

                 const isBackwards = (tele.destY || 0) < tele.y;
                 const color = isBackwards ? '#ef4444' : '#d946ef';

                 spawnParticles(m.x, m.y, color, 15, 4); 

                 m.x = tele.destX || m.x;
                 m.y = tele.destY || m.y;

                 m.vx *= 0.2; 
                 m.vy = isBackwards ? 0 : Math.abs(m.vy) + 2; 

                 teleportCooldowns.current[m.id] = now + 1500; 
                 audio.playPinHit(8); 

                 spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
            }
        }

        m.angle += m.omega * dt;
        m.omega *= 0.999; 

        m.vx *= Math.pow(config.friction, dt);
        m.vy *= Math.pow(config.friction, dt);

        if (m.vx*m.vx + m.vy*m.vy < 0.2) {
             m.vx += (Math.random() - 0.5); 
             m.vy += 0.5; 
        }

        // CHECK GATE COLLISION
        if (!gateOpenRef.current) {
            checkLineCollision(m, gateLine);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;

    // Explicit Camera Logic:
    // 1. If following bet -> Follow bet marble.
    // 2. If bet marble finishes or isFollowingBet is false -> Follow Leader (1st place active marble).
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        // Only follow if it exists and hasn't finished (or maybe follow even if finished? Usually better to follow active)
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             // Fallback to leader if bet marble is finished
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        // Follow Leader Logic - STRICTLY follow the first place marble
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          // Changed: Do NOT average top 3. Just take the leader.
          // This ensures the camera stays with the leader even if they are far ahead.
          targetY = activeMarblesList[0].y - 300;
        } 
    }

    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0) {
      if (!raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
      }
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;

      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBumper = pin.type === 'bumper';

      const intensity = Math.sqrt(ball.vx*ball.vx + ball.vy*ball.vy);
      if (intensity > 1) {
          audio.playPinHit(intensity);
      }

      // Calculate approximate contact point
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;

      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) {
                 const cx = m1.x + nx * m1.radius;
                 const cy = m1.y + ny * m1.radius;
                 spawnParticles(cx, cy, '#fff', 3, 2);
             }
         }

         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false; // Reset Gate
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // HORIZONTAL START POSITIONS (Restored from stable version)
    const totalWidth = COURSE_WIDTH * 0.9;
    const startX = COURSE_WIDTH * 0.05;
    const spacing = totalWidth / Math.max(1, activeMarbles.length);

    marblesRef.current = activeMarbles.map((m, index) => ({
      ...m,
      x: startX + (spacing * index) + (spacing/2), // Evenly spaced horizontally
      y: GATE_Y - 50, // Just above the gate
      vx: 0,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();

  }, [activeMarbles]); 

  // --- Drawing Subroutines ---

  const drawRepulsor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
    const currentRadius = obj.width/2 + pulse * (obj.range! - obj.width/2);

    ctx.beginPath();
    ctx.arc(0, 0, obj.width/2, 0, Math.PI * 2);
    ctx.fillStyle = '#8b5cf6';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, currentRadius, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(139, 92, 246, ${1 - pulse})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  };

  const drawConveyor = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
    const length = obj.width;  
    const thickness = obj.height || 50; 

    ctx.beginPath();
    ctx.rect(-length/2, -thickness/2, length, thickness);
    ctx.fillStyle = '#334155';
    ctx.fill();
    ctx.strokeStyle = '#475569';
    ctx.stroke();

    const spacing = 40;
    const offset = (timeRef.current * obj.speed * 50) % spacing;

    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';

    for(let x = -length/2; x < length/2; x += spacing) {
        const currentX = x + offset;
        if (currentX > length/2) continue;

        ctx.save();
        ctx.translate(currentX, 0); 
        ctx.beginPath();
        ctx.moveTo(-5, -8);
        ctx.lineTo(5, 0);
        ctx.lineTo(-5, 8);
        ctx.fill();
        ctx.restore();
    }
  };

  const drawLaser = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle) => {
     ctx.fillStyle = '#111';
     ctx.beginPath();
     ctx.arc(0, 0, 10, 0, Math.PI * 2);
     ctx.fill();
     ctx.strokeStyle = '#ef4444';
     ctx.lineWidth = 2;
     ctx.stroke();

     if (obj.active) {
         const len = obj.height || 300;
         ctx.beginPath();
         ctx.moveTo(0, 0);
         ctx.lineTo(len, 0); 

         ctx.shadowColor = '#ef4444';
         ctx.shadowBlur = 15;
         ctx.strokeStyle = '#fca5a5';
         ctx.lineWidth = 4;
         ctx.stroke();

         ctx.shadowBlur = 0;
         ctx.strokeStyle = '#fff';
         ctx.lineWidth = 1;
         ctx.stroke();
     } else {
         ctx.fillStyle = timeRef.current % 30 < 15 ? '#ef4444' : '#550000';
         ctx.beginPath();
         ctx.arc(0, 0, 4, 0, Math.PI * 2);
         ctx.fill();
     }
  };

  const drawTeleporter = (ctx: CanvasRenderingContext2D, obj: DynamicObstacle, isExit = false) => {
      const opacity = obj.timer !== undefined ? obj.timer : 1.0;
      if (opacity < 0.1 && !isExit) return; 

      ctx.save();
      ctx.globalAlpha = isExit ? 1.0 : opacity; 

      const radius = obj.width / 2;
      const angleOffset = timeRef.current * (isExit ? -0.1 : 0.1);
      const isBackwards = (obj.destY || 0) < obj.y;

      const primaryColor = isExit ? '#06b6d4' : (isBackwards ? '#ef4444' : '#d946ef');
      const glowColor = isExit ? 'rgba(6,182,212,0.5)' : (isBackwards ? 'rgba(239, 68, 68, 0.5)' : 'rgba(217,70,239,0.5)');

      ctx.beginPath();
      ctx.arc(0, 0, radius, 0, Math.PI * 2);
      ctx.strokeStyle = primaryColor;
      ctx.lineWidth = 3;
      ctx.shadowColor = primaryColor;
      ctx.shadowBlur = 10 * opacity;
      ctx.stroke();
      ctx.shadowBlur = 0;

      ctx.save();
      ctx.rotate(angleOffset);
      for(let i=0; i<3; i++) {
          ctx.rotate((Math.PI * 2) / 3);
          ctx.beginPath();
          ctx.moveTo(0, 0);
          ctx.quadraticCurveTo(radius/2, 0, radius, radius/2);
          ctx.strokeStyle = glowColor;
          ctx.lineWidth = 2;
          ctx.stroke();
      }
      ctx.restore();

      ctx.fillStyle = '#fff';
      ctx.font = '10px Arial';
      ctx.textAlign = 'center';

      let label = isExit ? 'OUT' : (isBackwards ? 'TRAP' : 'IN');
      if (!isExit && opacity < 0.3) label = ''; 

      ctx.fillText(label, 0, 4);
      ctx.restore(); 
  };

  const drawParticles = (ctx: CanvasRenderingContext2D) => {
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
          ctx.fill();
      });
      ctx.globalAlpha = 1.0;
  };

  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110; // Slightly wider for names
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 

       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);

       // Small colored dot fallback if needed, but mainly name color
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();

       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);

       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  // --- Render Loop ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    linesRef.current.forEach(l => {
      ctx.strokeStyle = l.type === 'wall' ? '#4b5563' : '#60a5fa';
      if (l.type === 'wall') ctx.lineWidth = 6;
      else ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
      ctx.stroke();
    });

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           ctx.save();
           ctx.translate(obj.x, obj.y);
           drawTeleporter(ctx, obj, false);
           ctx.restore();
           if (obj.destX !== undefined && obj.destY !== undefined) {
               ctx.save();
               ctx.translate(obj.destX, obj.destY);
               drawTeleporter(ctx, obj, true);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);

          const range = obj.height || 200;
          const gradient = ctx.createLinearGradient(0, 0, range, 0);
          gradient.addColorStop(0, 'rgba(255, 255, 255, 0.4)');
          gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

          ctx.fillStyle = gradient;
          ctx.fillRect(0, -obj.width/2, range, obj.width);

          ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
          ctx.lineWidth = 1;
          const offset = (timeRef.current * 5) % 50;
          for(let i=0; i<3; i++) {
             const yPos = -obj.width/2 + (obj.width/4) * (i+1);
             ctx.beginPath();
             ctx.moveTo(10 + offset, yPos);
             ctx.lineTo(range - 20, yPos);
             ctx.stroke();
          }

       } else if (obj.type === 'repulsor') {
          drawRepulsor(ctx, obj);
       } else if (obj.type === 'conveyor') {
          drawConveyor(ctx, obj);
       } else if (obj.type === 'laser') {
          drawLaser(ctx, obj);
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;

             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.lineCap = 'round'; 
             ctx.stroke();

             ctx.beginPath();
             ctx.arc(0, 0, r - 10, 0, Math.PI * 2);
             ctx.strokeStyle = 'rgba(217, 70, 239, 0.3)';
             ctx.lineWidth = 2;
             ctx.stroke();
       } else {
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();

         if (obj.type === 'spinner') {
           ctx.beginPath();
           ctx.arc(0, 0, 5, 0, Math.PI * 2);
           ctx.fillStyle = '#fff';
           ctx.fill();
         }
       }
       ctx.restore();
    });

    // DRAW GATE (If Closed)
    if (!gateOpenRef.current) {
        ctx.beginPath();
        ctx.moveTo(0, GATE_Y);
        ctx.lineTo(COURSE_WIDTH, GATE_Y);
        ctx.strokeStyle = '#ef4444'; // Red barrier
        ctx.lineWidth = 10;
        ctx.stroke();

        // Draw Countdown Text
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));

        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = 'bold 80px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), COURSE_WIDTH / 2, GATE_Y + 150);
        ctx.font = '20px "Roboto Mono"';
        ctx.fillText("PREPARAR...", COURSE_WIDTH / 2, GATE_Y + 180);
    }

    drawParticles(ctx);

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    // Draw Finish Line
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);
    for(let i=0; i<20; i++) {
        ctx.fillStyle = i%2===0 ? '#fff' : '#000';
        ctx.fillRect(i * (COURSE_WIDTH/20), finishLineY.current, COURSE_WIDTH/20, 10);
    }

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 

      // Draw Logo Image clipped to circle
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        // Draw Background Circle (White) to make transparency logos pop
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff';
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        ctx.save();
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        // Fallback if image fails or no URL
        ctx.beginPath();
        ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color;
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 5;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Draw Name Abbreviation inside
        ctx.save();
        // Since we are rotated by -m.angle, drawing text here will make it spin with the marble
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
        ctx.restore();
      }

      // Draw Border Ring (Team Color)
      ctx.beginPath();
      ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color;
      ctx.lineWidth = 2;
      ctx.stroke();

      // Glass Shine Effect
      ctx.beginPath();
      ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)';
      ctx.fill();

      ctx.restore(); 

      // Selection Highlight
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2);
        ctx.stroke();
      }

      if (!m.finished) {
        ctx.fillStyle = '#fff';
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 

    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => {
      update();
      draw();
      requestRef.current = requestAnimationFrame(loop);
    };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const gateLinesRef = useRef<LineSegment[]>([]); // New: Walls that disappear after start
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;

  // MIXER START CONFIGURATION
  const START_CX = COURSE_WIDTH / 2;
  const START_CY = 200;
  const START_RADIUS = 120;
  const GATE_DELAY = 3000; // 3 seconds to mix

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const gateLines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // --- 1. MIXER START (Liquidificador) ---
    // Create a circle of line segments
    const segments = 32;
    const step = (Math.PI * 2) / segments;

    for (let i = 0; i < segments; i++) {
        const a1 = i * step;
        const a2 = (i + 1) * step;

        const x1 = START_CX + Math.cos(a1) * START_RADIUS;
        const y1 = START_CY + Math.sin(a1) * START_RADIUS;
        const x2 = START_CX + Math.cos(a2) * START_RADIUS;
        const y2 = START_CY + Math.sin(a2) * START_RADIUS;

        // Angles where sin > 0.4 are roughly the bottom part of the circle (y goes down)
        // We make the bottom part "Gate Lines" which are removed after 3s
        const isBottom = Math.sin(a1) > 0.4 || Math.sin(a2) > 0.4;

        if (isBottom) {
            gateLines.push({ x1, y1, x2, y2, type: 'wall' });
        } else {
            lines.push({ x1, y1, x2, y2, type: 'wall' });
        }
    }

    // Add Mixing Propeller
    dynamics.push({
        id: 'mixer_blade',
        type: 'spinner',
        x: START_CX,
        y: START_CY,
        width: START_RADIUS * 1.5,
        angle: 0,
        speed: 0.2, // Fast spin
    });

    // Funnel below mixer to guide marbles to track
    const funnelTopY = START_CY + START_RADIUS + 50;
    const funnelHeight = 150;

    // Left Funnel Wall
    lines.push({ x1: 0, y1: funnelTopY - 50, x2: COURSE_WIDTH * 0.4, y2: funnelTopY + funnelHeight, type: 'wall' });
    // Right Funnel Wall
    lines.push({ x1: COURSE_WIDTH, y1: funnelTopY - 50, x2: COURSE_WIDTH * 0.6, y2: funnelTopY + funnelHeight, type: 'wall' });

    let currentY = funnelTopY + funnelHeight + 50;

    // --- 2. Procedural Segments ---
    const segmentCount = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 200 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 200, angle: 0, speed: -3.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 
        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });
        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: currentY + 250, width: width, height: height, angle: angle, speed: 0.1, force: 18 });

      } else if (type === 'teleporter') {
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        let targetY = isTrap ? Math.max(100, currentY - (300 + Math.random() * 400)) : currentY + (500 + Math.random() * 300);
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 200, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, blinkPhase: Math.random() * Math.PI * 2, blinkSpeed: 0.02 + Math.random() * 0.02, active: true });
        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60, y: currentY + 250, width: 250, angle: 0, speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02), range: Math.PI / 2.5 });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.1, y: currentY + 300, width: 0, height: COURSE_WIDTH * 0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    gateLinesRef.current = gateLines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate/Mixer Logic
    const timeSinceStart = Date.now() - startTime.current;

    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); 
            spawnParticles(START_CX, START_CY + START_RADIUS, '#10b981', 40, 5); 
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Dynamic Updates
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      } else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      } else if (obj.type === 'teleporter') {
        const val = Math.sin(timeRef.current * (obj.blinkSpeed || 0.05) + (obj.blinkPhase || 0));
        obj.active = val > -0.3; // More uptime
        obj.timer = (val + 1) / 2; 
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'conveyor' || obj.type === 'slider_h' || obj.type === 'slider_v') {
          const halfW = obj.width / 2;
          const dx = Math.cos(obj.angle) * halfW;
          const dy = Math.sin(obj.angle) * halfW;
          dynamicLines.push({
            x1: obj.x - dx, y1: obj.y - dy,
            x2: obj.x + dx, y2: obj.y + dy,
            type: obj.type === 'spinner' ? 'bouncer' : 'floor'
          });
      }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // --- DYNAMIC FIELDS (Fans, Repulsors, etc) ---
        dynamicObjs.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
                const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
                const halfWidth = obj.width / 2; 
                const range = obj.height || 200;
                if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
                    m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
                    m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
                }
            } else if (obj.type === 'repulsor') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const distSq = dx*dx + dy*dy;
                if (distSq < (obj.range || 100)**2) {
                    const dist = Math.sqrt(distSq);
                    const force = (obj.force || 1) * (1 - dist/(obj.range||100));
                    m.vx += (dx/dist) * force * dt * 50;
                    m.vy += (dy/dist) * force * dt * 50;
                }
            } else if (obj.type === 'conveyor') {
               const dx = m.x - obj.x;
               const dy = m.y - obj.y;
               const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
               const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
               if (Math.abs(localParallel) < obj.width/2 && Math.abs(localPerp) < (obj.height||50)/2) {
                  m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                  m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
               }
            } else if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = (obj.width / 2);
                const thickness = 6;
                if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit Wall
                        const nx = dx / dist;
                        const ny = dy / dist;
                        const pushSign = dist < r ? -1 : 1;
                        const overlap = (m.radius + thickness) - Math.abs(dist - r);
                        if (overlap > 0) {
                            m.x += nx * pushSign * overlap * 0.5;
                            m.y += ny * pushSign * overlap * 0.5;
                            const nX = nx * pushSign;
                            const nY = ny * pushSign;
                            const dot = m.vx * nX + m.vy * nY;
                            m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                            m.vy = (m.vy - 2 * dot * nY) * config.restitution;
                        }
                    }
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                if (dx*dx + dy*dy < (obj.width/2)**2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                     m.x = obj.destX || m.x;
                     m.y = obj.destY || m.y;
                     m.vx *= 0.2; 
                     m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2; 
                     teleportCooldowns.current[m.id] = now + 1500; 
                     audio.playPinHit(8); 
                     spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
                }
            } else if (obj.type === 'laser' && obj.active) {
                // Simplified Laser (Line Segment distance check)
                const len = obj.height || 300;
                const x2 = obj.x + Math.cos(obj.angle) * len;
                const y2 = obj.y + Math.sin(obj.angle) * len;
                // ... (reuse line collision logic logic simplified) ...
                const A = m.x - obj.x; const B = m.y - obj.y;
                const C = x2 - obj.x; const D = y2 - obj.y;
                const dot = A * C + B * D;
                const lenSq = C * C + D * D;
                let param = -1;
                if (lenSq !== 0) param = dot / lenSq;
                let xx, yy;
                if (param < 0) { xx = obj.x; yy = obj.y; }
                else if (param > 1) { xx = x2; yy = y2; }
                else { xx = obj.x + param * C; yy = obj.y + param * D; }
                const dx = m.x - xx; const dy = m.y - yy;
                if (dx*dx + dy*dy < (m.radius + 5)**2) {
                     m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     spawnParticles(m.x, m.y, '#ef4444', 3, 4);
                }
            }
        });

        // COLLISIONS
        // Check Gate Lines only if closed
        if (!gateOpenRef.current) {
            for (const line of gateLinesRef.current) checkLineCollision(m, line);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          targetY = activeMarblesList[0].y - 300;
        } 
    }
    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;
      const isBumper = pin.type === 'bumper';
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;
      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) spawnParticles(m1.x + nx * m1.radius, m1.y + ny * m1.radius, '#fff', 3, 2);
         }
         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // MIXER START POSITIONS: Randomly inside circle
    marblesRef.current = activeMarbles.map((m) => {
      const r = (START_RADIUS - 40) * Math.sqrt(Math.random());
      const theta = Math.random() * 2 * Math.PI;
      return {
          ...m,
          x: START_CX + r * Math.cos(theta),
          y: START_CY + r * Math.sin(theta),
          vx: (Math.random()-0.5)*2,
          vy: (Math.random()-0.5)*2,
          angle: 0,
          omega: 0,
          finished: false,
          rank: 0
      };
    });

    audio.resume();
  }, [activeMarbles]); 

  // --- Drawing ---
  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110;
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';

    // Draw Gate Lines (if closed, or fading out?)
    if (!gateOpenRef.current) {
        ctx.strokeStyle = '#ef4444';
        ctx.beginPath();
        gateLinesRef.current.forEach(l => {
            ctx.moveTo(l.x1, l.y1);
            ctx.lineTo(l.x2, l.y2);
        });
        ctx.stroke();
    }

    // Draw Static Lines
    ctx.strokeStyle = '#4b5563';
    ctx.lineWidth = 6;
    ctx.beginPath();
    linesRef.current.forEach(l => {
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           // ... (Same teleporter draw) ...
           const opacity = obj.timer !== undefined ? obj.timer : 1.0;
           if (opacity > 0.1) {
             ctx.save();
             ctx.translate(obj.x, obj.y);
             ctx.globalAlpha = opacity;
             ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
             ctx.strokeStyle = '#d946ef'; ctx.stroke();
             ctx.fillText(obj.destY! < obj.y ? 'TRAP' : 'IN', -10, 0);
             ctx.restore();
           }
           if (obj.destX) {
               ctx.save(); ctx.translate(obj.destX, obj.destY!);
               ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
               ctx.strokeStyle = '#06b6d4'; ctx.stroke();
               ctx.fillText('OUT', -10, 0);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = 'rgba(255,255,255,0.1)';
          ctx.fillRect(0, -obj.width/2, obj.height||200, obj.width);
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);
       } else if (obj.type === 'repulsor') {
          const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
          ctx.beginPath(); ctx.arc(0,0,obj.width/2 + pulse * 20, 0, Math.PI*2);
          ctx.strokeStyle = '#8b5cf6'; ctx.stroke();
          ctx.beginPath(); ctx.arc(0,0,obj.width/2, 0, Math.PI*2);
          ctx.fillStyle = '#8b5cf6'; ctx.fill();
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.stroke();
       } else {
         // Generic rectangle for slider/spinner/conveyor
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();
         if (obj.type === 'conveyor') {
             ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.setLineDash([5,5]);
             ctx.stroke(); ctx.setLineDash([]);
         }
       }
       ctx.restore();
    });

    // Countdown Text inside Mixer
    if (!gateOpenRef.current) {
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));
        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.font = 'bold 60px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), START_CX, START_CY - 100);
    }

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff'; ctx.fill();
        ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
      }
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.fill();
      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
      if (!m.finished) {
        ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const gateLinesRef = useRef<LineSegment[]>([]); // New: Walls that disappear after start
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;

  // MIXER START CONFIGURATION
  const START_CX = COURSE_WIDTH / 2;
  const START_CY = 200;
  const START_RADIUS = 120;
  const GATE_DELAY = 3000; // 3 seconds to mix

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const gateLines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // --- 1. MIXER START (Liquidificador) ---
    // Create a circle of line segments
    const segments = 32;
    const step = (Math.PI * 2) / segments;

    for (let i = 0; i < segments; i++) {
        const a1 = i * step;
        const a2 = (i + 1) * step;

        const x1 = START_CX + Math.cos(a1) * START_RADIUS;
        const y1 = START_CY + Math.sin(a1) * START_RADIUS;
        const x2 = START_CX + Math.cos(a2) * START_RADIUS;
        const y2 = START_CY + Math.sin(a2) * START_RADIUS;

        // Angles where sin > 0.4 are roughly the bottom part of the circle (y goes down)
        // We make the bottom part "Gate Lines" which are removed after 3s
        const isBottom = Math.sin(a1) > 0.4 || Math.sin(a2) > 0.4;

        if (isBottom) {
            gateLines.push({ x1, y1, x2, y2, type: 'wall' });
        } else {
            lines.push({ x1, y1, x2, y2, type: 'wall' });
        }
    }

    // Add Mixing Propellers (X Shape)
    const bladeLength = START_RADIUS * 1.95; // Almost touching the walls
    const mixSpeed = 0.08; // Slower speed

    dynamics.push({
        id: 'mixer_blade_1',
        type: 'spinner',
        x: START_CX,
        y: START_CY,
        width: bladeLength,
        angle: 0,
        speed: mixSpeed,
    });

    dynamics.push({
        id: 'mixer_blade_2',
        type: 'spinner',
        x: START_CX,
        y: START_CY,
        width: bladeLength,
        angle: Math.PI / 2, // 90 degrees offset to form an X
        speed: mixSpeed,
    });

    // Funnel below mixer to guide marbles to track
    const funnelTopY = START_CY + START_RADIUS + 50;
    const funnelHeight = 150;

    // Left Funnel Wall
    lines.push({ x1: 0, y1: funnelTopY - 50, x2: COURSE_WIDTH * 0.4, y2: funnelTopY + funnelHeight, type: 'wall' });
    // Right Funnel Wall
    lines.push({ x1: COURSE_WIDTH, y1: funnelTopY - 50, x2: COURSE_WIDTH * 0.6, y2: funnelTopY + funnelHeight, type: 'wall' });

    let currentY = funnelTopY + funnelHeight + 50;

    // --- 2. Procedural Segments ---
    const segmentCount = 12 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 10 });
            options.push({ type: 'slider_v', weight: 10 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 15 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 10 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 4 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.35, y: currentY + 250, width: 150, angle: 0, speed: 0.12 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.65, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.15 });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 200, width: 200, angle: 0, speed: 2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 200 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 350, width: 200, angle: 0, speed: -3.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 350 });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.25, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.25, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.75, y: currentY + 350, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.75, initialY: currentY + 350 });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 50, range: 140, angle: 0, speed: 0.1, force: 3.0 });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 5);
        let angle = Math.PI / 2;
        let cx = COURSE_WIDTH * 0.5;
        let width = 200; 
        let height = 100; 
        if (dirType === 1) { angle = Math.PI / 4; cx = COURSE_WIDTH * 0.4; } 
        else if (dirType === 2) { angle = 3 * Math.PI / 4; cx = COURSE_WIDTH * 0.6; } 
        else if (dirType === 3) { angle = 0; cx = COURSE_WIDTH * 0.3; width = 150; height = 150; } 
        else if (dirType === 4) { angle = Math.PI; cx = COURSE_WIDTH * 0.7; width = 150; height = 150; }
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });
        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: currentY + 250, width: width, height: height, angle: angle, speed: 0.1, force: 18 });

      } else if (type === 'teleporter') {
        const isTrap = Math.random() > 0.5; 
        const entranceX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        const exitX = COURSE_WIDTH * (0.2 + Math.random() * 0.6);
        let targetY = isTrap ? Math.max(100, currentY - (300 + Math.random() * 400)) : currentY + (500 + Math.random() * 300);
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `teleport_${i}`, type: 'teleporter', x: entranceX, y: currentY + 200, width: 70, destX: exitX, destY: targetY, angle: 0, speed: 0, blinkPhase: Math.random() * Math.PI * 2, blinkSpeed: 0.02 + Math.random() * 0.02, active: true });
        pins.push({ x: entranceX + (Math.random() > 0.5 ? 80 : -80), y: currentY + 200, radius: 20, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `hollow_${i}`, type: 'hollow_circle', x: COURSE_WIDTH / 2 + (Math.random() - 0.5) * 60, y: currentY + 250, width: 250, angle: 0, speed: (Math.random() > 0.5 ? 1 : -1) * (0.02 + Math.random() * 0.02), range: Math.PI / 2.5 });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `laser_${i}`, type: 'laser', x: COURSE_WIDTH * 0.1, y: currentY + 300, width: 0, height: COURSE_WIDTH * 0.8, angle: 0, speed: 0, force: 25, active: true, timer: 0 });
        lines.push({ x1: 0, y1: currentY + 280, x2: COURSE_WIDTH * 0.15, y2: currentY + 320, type: 'wall' });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const funnelHeight = 250;
        const exitGap = 55;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + funnelHeight, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + funnelHeight + 80, radius: 20, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `fan_${i}_1`, type: 'fan', x: 20, y: currentY + 250, width: 40, height: 300, angle: 0, speed: 0, force: 0.7 });
        pins.push({ x: COURSE_WIDTH * 0.6, y: currentY + 250, radius: 25, type: 'bumper' });
      }

      currentY += segmentHeight;
    }

    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    gateLinesRef.current = gateLines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate/Mixer Logic
    const timeSinceStart = Date.now() - startTime.current;

    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); 
            spawnParticles(START_CX, START_CY + START_RADIUS, '#10b981', 40, 5); 
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Dynamic Updates
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      } else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      } else if (obj.type === 'teleporter') {
        const val = Math.sin(timeRef.current * (obj.blinkSpeed || 0.05) + (obj.blinkPhase || 0));
        obj.active = val > -0.3; // More uptime
        obj.timer = (val + 1) / 2; 
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'conveyor' || obj.type === 'slider_h' || obj.type === 'slider_v') {
          const halfW = obj.width / 2;
          const dx = Math.cos(obj.angle) * halfW;
          const dy = Math.sin(obj.angle) * halfW;
          dynamicLines.push({
            x1: obj.x - dx, y1: obj.y - dy,
            x2: obj.x + dx, y2: obj.y + dy,
            type: obj.type === 'spinner' ? 'bouncer' : 'floor'
          });
      }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // --- DYNAMIC FIELDS (Fans, Repulsors, etc) ---
        dynamicObjs.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
                const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
                const halfWidth = obj.width / 2; 
                const range = obj.height || 200;
                if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
                    m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
                    m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
                }
            } else if (obj.type === 'repulsor') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const distSq = dx*dx + dy*dy;
                if (distSq < (obj.range || 100)**2) {
                    const dist = Math.sqrt(distSq);
                    const force = (obj.force || 1) * (1 - dist/(obj.range||100));
                    m.vx += (dx/dist) * force * dt * 50;
                    m.vy += (dy/dist) * force * dt * 50;
                }
            } else if (obj.type === 'conveyor') {
               const dx = m.x - obj.x;
               const dy = m.y - obj.y;
               const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
               const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
               if (Math.abs(localParallel) < obj.width/2 && Math.abs(localPerp) < (obj.height||50)/2) {
                  m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                  m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
               }
            } else if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = (obj.width / 2);
                const thickness = 6;
                if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit Wall
                        const nx = dx / dist;
                        const ny = dy / dist;
                        const pushSign = dist < r ? -1 : 1;
                        const overlap = (m.radius + thickness) - Math.abs(dist - r);
                        if (overlap > 0) {
                            m.x += nx * pushSign * overlap * 0.5;
                            m.y += ny * pushSign * overlap * 0.5;
                            const nX = nx * pushSign;
                            const nY = ny * pushSign;
                            const dot = m.vx * nX + m.vy * nY;
                            m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                            m.vy = (m.vy - 2 * dot * nY) * config.restitution;
                        }
                    }
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                if (dx*dx + dy*dy < (obj.width/2)**2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                     m.x = obj.destX || m.x;
                     m.y = obj.destY || m.y;
                     m.vx *= 0.2; 
                     m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2; 
                     teleportCooldowns.current[m.id] = now + 1500; 
                     audio.playPinHit(8); 
                     spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
                }
            } else if (obj.type === 'laser' && obj.active) {
                // Simplified Laser (Line Segment distance check)
                const len = obj.height || 300;
                const x2 = obj.x + Math.cos(obj.angle) * len;
                const y2 = obj.y + Math.sin(obj.angle) * len;
                // ... (reuse line collision logic logic simplified) ...
                const A = m.x - obj.x; const B = m.y - obj.y;
                const C = x2 - obj.x; const D = y2 - obj.y;
                const dot = A * C + B * D;
                const lenSq = C * C + D * D;
                let param = -1;
                if (lenSq !== 0) param = dot / lenSq;
                let xx, yy;
                if (param < 0) { xx = obj.x; yy = obj.y; }
                else if (param > 1) { xx = x2; yy = y2; }
                else { xx = obj.x + param * C; yy = obj.y + param * D; }
                const dx = m.x - xx; const dy = m.y - yy;
                if (dx*dx + dy*dy < (m.radius + 5)**2) {
                     m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     spawnParticles(m.x, m.y, '#ef4444', 3, 4);
                }
            }
        });

        // COLLISIONS
        // Check Gate Lines only if closed
        if (!gateOpenRef.current) {
            for (const line of gateLinesRef.current) checkLineCollision(m, line);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          targetY = activeMarblesList[0].y - 300;
        } 
    }
    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;
      const isBumper = pin.type === 'bumper';
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;
      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) spawnParticles(m1.x + nx * m1.radius, m1.y + ny * m1.radius, '#fff', 3, 2);
         }
         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // MIXER START POSITIONS: Randomly inside circle
    marblesRef.current = activeMarbles.map((m) => {
      const r = (START_RADIUS - 40) * Math.sqrt(Math.random());
      const theta = Math.random() * 2 * Math.PI;
      return {
          ...m,
          x: START_CX + r * Math.cos(theta),
          y: START_CY + r * Math.sin(theta),
          vx: (Math.random()-0.5)*2,
          vy: (Math.random()-0.5)*2,
          angle: 0,
          omega: 0,
          finished: false,
          rank: 0
      };
    });

    audio.resume();
  }, [activeMarbles]); 

  // --- Drawing ---
  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110;
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';

    // Draw Gate Lines (if closed, or fading out?)
    if (!gateOpenRef.current) {
        ctx.strokeStyle = '#ef4444';
        ctx.beginPath();
        gateLinesRef.current.forEach(l => {
            ctx.moveTo(l.x1, l.y1);
            ctx.lineTo(l.x2, l.y2);
        });
        ctx.stroke();
    }

    // Draw Static Lines
    ctx.strokeStyle = '#4b5563';
    ctx.lineWidth = 6;
    ctx.beginPath();
    linesRef.current.forEach(l => {
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           // ... (Same teleporter draw) ...
           const opacity = obj.timer !== undefined ? obj.timer : 1.0;
           if (opacity > 0.1) {
             ctx.save();
             ctx.translate(obj.x, obj.y);
             ctx.globalAlpha = opacity;
             ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
             ctx.strokeStyle = '#d946ef'; ctx.stroke();
             ctx.fillText(obj.destY! < obj.y ? 'TRAP' : 'IN', -10, 0);
             ctx.restore();
           }
           if (obj.destX) {
               ctx.save(); ctx.translate(obj.destX, obj.destY!);
               ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
               ctx.strokeStyle = '#06b6d4'; ctx.stroke();
               ctx.fillText('OUT', -10, 0);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = 'rgba(255,255,255,0.1)';
          ctx.fillRect(0, -obj.width/2, obj.height||200, obj.width);
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);
       } else if (obj.type === 'repulsor') {
          const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
          ctx.beginPath(); ctx.arc(0,0,obj.width/2 + pulse * 20, 0, Math.PI*2);
          ctx.strokeStyle = '#8b5cf6'; ctx.stroke();
          ctx.beginPath(); ctx.arc(0,0,obj.width/2, 0, Math.PI*2);
          ctx.fillStyle = '#8b5cf6'; ctx.fill();
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.stroke();
       } else {
         // Generic rectangle for slider/spinner/conveyor
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();
         if (obj.type === 'conveyor') {
             ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.setLineDash([5,5]);
             ctx.stroke(); ctx.setLineDash([]);
         }
       }
       ctx.restore();
    });

    // Countdown Text inside Mixer
    if (!gateOpenRef.current) {
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));
        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.font = 'bold 60px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), START_CX, START_CY - 100);
    }

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff'; ctx.fill();
        ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
      }
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.fill();
      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
      if (!m.finished) {
        ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const gateLinesRef = useRef<LineSegment[]>([]); // Walls that disappear after start
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);
  const gateOpenRef = useRef(false);

  // Constants
  const COURSE_WIDTH = 600;

  // MIXER START CONFIGURATION
  const START_CX = COURSE_WIDTH / 2;
  const START_CY = 200;
  const START_RADIUS = 120;
  const GATE_DELAY = 3000; // 3 seconds to mix

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const gateLines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    // --- 1. MIXER START (Liquidificador em X) ---
    // Create a circle of line segments
    const segments = 32;
    const step = (Math.PI * 2) / segments;

    for (let i = 0; i < segments; i++) {
        const a1 = i * step;
        const a2 = (i + 1) * step;

        const x1 = START_CX + Math.cos(a1) * START_RADIUS;
        const y1 = START_CY + Math.sin(a1) * START_RADIUS;
        const x2 = START_CX + Math.cos(a2) * START_RADIUS;
        const y2 = START_CY + Math.sin(a2) * START_RADIUS;

        // Bottom part (Gate Lines) - angles roughly between 30 and 150 degrees (sin > 0.5)
        const isBottom = Math.sin(a1) > 0.5 || Math.sin(a2) > 0.5;

        if (isBottom) {
            gateLines.push({ x1, y1, x2, y2, type: 'wall' });
        } else {
            lines.push({ x1, y1, x2, y2, type: 'wall' });
        }
    }

    // Add Mixing Propellers (X Shape)
    // Radius is 120, so diameter is 240. Width should be slightly less to not clip through walls.
    const bladeWidth = START_RADIUS * 1.9; 
    const mixSpeed = 0.06; // Slower speed as requested

    dynamics.push({
        id: 'mixer_blade_1',
        type: 'spinner',
        x: START_CX,
        y: START_CY,
        width: bladeWidth,
        angle: 0,
        speed: mixSpeed,
    });

    dynamics.push({
        id: 'mixer_blade_2',
        type: 'spinner',
        x: START_CX,
        y: START_CY,
        width: bladeWidth,
        angle: Math.PI / 2, // 90 degrees offset to form X
        speed: -mixSpeed, // Spin opposite or same? Same direction usually keeps momentum better in mixer
    });

    // Funnel below mixer to guide marbles to track
    const funnelTopY = START_CY + START_RADIUS + 20;
    const funnelHeight = 120;
    const funnelExitWidth = 80;

    // Left Funnel Wall
    lines.push({ x1: START_CX - 80, y1: funnelTopY, x2: START_CX - funnelExitWidth/2, y2: funnelTopY + funnelHeight, type: 'wall' });
    // Right Funnel Wall
    lines.push({ x1: START_CX + 80, y1: funnelTopY, x2: START_CX + funnelExitWidth/2, y2: funnelTopY + funnelHeight, type: 'wall' });

    let currentY = funnelTopY + funnelHeight + 60;

    // --- 2. Procedural Segments ---
    // Increased variety and ensured density
    const segmentCount = 14 + Math.floor(Math.random() * 4); 
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Standard Outer Walls for the segment
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        // Double spinners with guiding walls
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 160, angle: 0, speed: 0.1 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 160, angle: Math.PI / 2, speed: -0.1 });

        // Center pin to bounce off
        pins.push({ x: COURSE_WIDTH/2, y: currentY + 300, radius: 25, type: 'bumper' });

      } else if (type === 'slider_h') {
        // Horizontal Smashers
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 220, width: 220, angle: 0, speed: 2.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 220 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 340, width: 220, angle: 0, speed: -2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 340 });

      } else if (type === 'slider_v') {
        // Vertical Pistons
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        const gap = 120;
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 - gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 90, initialX: COURSE_WIDTH * 0.5 - gap, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_C_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5, y: currentY + 350, width: 120, angle: 0, speed: 1.8, range: 90, initialX: COURSE_WIDTH * 0.5, initialY: currentY + 350 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 + gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 90, initialX: COURSE_WIDTH * 0.5 + gap, initialY: currentY + 250 });

      } else if (type === 'repulsor') {
        // Center Repulsor Field
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 60, range: 160, angle: 0, speed: 0.15, force: 3.5 });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 350, radius: 15, type: 'pin' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 350, radius: 15, type: 'pin' });

      } else if (type === 'conveyor') {
        // Conveyor Belts
        const dirType = Math.floor(Math.random() * 4);
        let cx = COURSE_WIDTH * 0.5;
        let cy = currentY + 250;
        let w = 250; let h = 120;
        let ang = 0;

        if (dirType === 0) { ang = 0; cx = COURSE_WIDTH * 0.3; } // Push Right
        else if (dirType === 1) { ang = Math.PI; cx = COURSE_WIDTH * 0.7; } // Push Left
        else if (dirType === 2) { ang = Math.PI/4; w = 300; h=50; } // Diagonal Down Right
        else { ang = 3*Math.PI/4; w = 300; h=50; } // Diagonal Down Left

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: cy, width: w, height: h, angle: ang, speed: 0, force: 20 });

      } else if (type === 'teleporter') {
        // Portals (Trap or Shortcut)
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        const entranceX = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 100 : -100);
        // Exit can be further down or a trap (back up)
        const isTrap = Math.random() < 0.4;
        const exitY = isTrap ? currentY - 500 : currentY + 800;
        const exitX = COURSE_WIDTH * 0.5 + (Math.random() * 200 - 100);

        dynamics.push({ 
            id: `teleport_${i}`, type: 'teleporter', 
            x: entranceX, y: currentY + 250, width: 80, 
            destX: exitX, destY: exitY, 
            angle: 0, speed: 0, 
            blinkPhase: Math.random() * Math.PI, blinkSpeed: 0.05, 
            active: true 
        });

        // Add a bumper near the teleporter to make it harder to enter
        pins.push({ x: entranceX, y: currentY + 180, radius: 15, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        // Spinning Hollow Circle with gap
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ 
            id: `hollow_${i}`, type: 'hollow_circle', 
            x: COURSE_WIDTH / 2, y: currentY + 280, 
            width: 280, angle: 0, 
            speed: (Math.random() > 0.5 ? 1 : -1) * 0.04, 
            range: Math.PI / 3 // Gap size
        });

      } else if (type === 'laser') {
        // Intermittent Lasers
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        // Horizontal laser barrier
        dynamics.push({ 
            id: `laser_${i}`, type: 'laser', 
            x: COURSE_WIDTH * 0.1, y: currentY + 300, 
            width: 0, height: COURSE_WIDTH * 0.8, // Length
            angle: 0, speed: 0, force: 40, 
            active: true, timer: 0 
        });

      } else if (type === 'funnel') {
        // Big Funnel
        const funnelTopY = currentY + 50;
        const h = 300;
        const exitGap = 60;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + h, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + h, type: 'wall' });
        // Bumper at exit to cause chaos
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + h + 60, radius: 25, type: 'bumper' });

      } else if (type === 'fan') {
        // Side Fans
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        // Fan blowing right
        dynamics.push({ id: `fan_${i}_L`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 350, angle: 0, speed: 0, force: 1.2 });
        // Fan blowing left further down
        dynamics.push({ id: `fan_${i}_R`, type: 'fan', x: COURSE_WIDTH - 20, y: currentY + 350, width: 50, height: 350, angle: Math.PI, speed: 0, force: 1.2 });
      }

      currentY += segmentHeight;
    }

    // Final Stretch
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    gateLinesRef.current = gateLines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    // Gate/Mixer Logic
    const timeSinceStart = Date.now() - startTime.current;

    if (!gateOpenRef.current) {
        if (timeSinceStart > GATE_DELAY) {
            gateOpenRef.current = true;
            audio.playPinHit(15); 
            spawnParticles(START_CX, START_CY + START_RADIUS, '#10b981', 40, 5); 
        }
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Dynamic Updates
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      } else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      } else if (obj.type === 'teleporter') {
        const val = Math.sin(timeRef.current * (obj.blinkSpeed || 0.05) + (obj.blinkPhase || 0));
        obj.active = val > -0.3; // More uptime
        obj.timer = (val + 1) / 2; 
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'conveyor' || obj.type === 'slider_h' || obj.type === 'slider_v') {
          const halfW = obj.width / 2;
          const dx = Math.cos(obj.angle) * halfW;
          const dy = Math.sin(obj.angle) * halfW;
          dynamicLines.push({
            x1: obj.x - dx, y1: obj.y - dy,
            x2: obj.x + dx, y2: obj.y + dy,
            type: obj.type === 'spinner' ? 'bouncer' : 'floor'
          });
      }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // --- DYNAMIC FIELDS (Fans, Repulsors, etc) ---
        dynamicObjs.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
                const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
                const halfWidth = obj.width / 2; 
                const range = obj.height || 200;
                if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
                    m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
                    m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
                }
            } else if (obj.type === 'repulsor') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const distSq = dx*dx + dy*dy;
                if (distSq < (obj.range || 100)**2) {
                    const dist = Math.sqrt(distSq);
                    const force = (obj.force || 1) * (1 - dist/(obj.range||100));
                    m.vx += (dx/dist) * force * dt * 50;
                    m.vy += (dy/dist) * force * dt * 50;
                }
            } else if (obj.type === 'conveyor') {
               const dx = m.x - obj.x;
               const dy = m.y - obj.y;
               const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
               const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
               if (Math.abs(localParallel) < obj.width/2 && Math.abs(localPerp) < (obj.height||50)/2) {
                  m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                  m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
               }
            } else if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = (obj.width / 2);
                const thickness = 6;
                if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit Wall
                        const nx = dx / dist;
                        const ny = dy / dist;
                        const pushSign = dist < r ? -1 : 1;
                        const overlap = (m.radius + thickness) - Math.abs(dist - r);
                        if (overlap > 0) {
                            m.x += nx * pushSign * overlap * 0.5;
                            m.y += ny * pushSign * overlap * 0.5;
                            const nX = nx * pushSign;
                            const nY = ny * pushSign;
                            const dot = m.vx * nX + m.vy * nY;
                            m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                            m.vy = (m.vy - 2 * dot * nY) * config.restitution;
                        }
                    }
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                if (dx*dx + dy*dy < (obj.width/2)**2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                     m.x = obj.destX || m.x;
                     m.y = obj.destY || m.y;
                     m.vx *= 0.2; 
                     m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2; 
                     teleportCooldowns.current[m.id] = now + 1500; 
                     audio.playPinHit(8); 
                     spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
                }
            } else if (obj.type === 'laser' && obj.active) {
                // Simplified Laser (Line Segment distance check)
                const len = obj.height || 300;
                const x2 = obj.x + Math.cos(obj.angle) * len;
                const y2 = obj.y + Math.sin(obj.angle) * len;
                // ... (reuse line collision logic logic simplified) ...
                const A = m.x - obj.x; const B = m.y - obj.y;
                const C = x2 - obj.x; const D = y2 - obj.y;
                const dot = A * C + B * D;
                const lenSq = C * C + D * D;
                let param = -1;
                if (lenSq !== 0) param = dot / lenSq;
                let xx, yy;
                if (param < 0) { xx = obj.x; yy = obj.y; }
                else if (param > 1) { xx = x2; yy = y2; }
                else { xx = obj.x + param * C; yy = obj.y + param * D; }
                const dx = m.x - xx; const dy = m.y - yy;
                if (dx*dx + dy*dy < (m.radius + 5)**2) {
                     m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     spawnParticles(m.x, m.y, '#ef4444', 3, 4);
                }
            }
        });

        // COLLISIONS
        // Check Gate Lines only if closed
        if (!gateOpenRef.current) {
            for (const line of gateLinesRef.current) checkLineCollision(m, line);
        }

        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          targetY = activeMarblesList[0].y - 300;
        } 
    }
    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;
      const isBumper = pin.type === 'bumper';
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;
      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) spawnParticles(m1.x + nx * m1.radius, m1.y + ny * m1.radius, '#fff', 3, 2);
         }
         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    gateOpenRef.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // MIXER START POSITIONS: Randomly inside circle
    marblesRef.current = activeMarbles.map((m) => {
      const r = (START_RADIUS - 40) * Math.sqrt(Math.random());
      const theta = Math.random() * 2 * Math.PI;
      return {
          ...m,
          x: START_CX + r * Math.cos(theta),
          y: START_CY + r * Math.sin(theta),
          vx: (Math.random()-0.5)*2,
          vy: (Math.random()-0.5)*2,
          angle: 0,
          omega: 0,
          finished: false,
          rank: 0
      };
    });

    audio.resume();
  }, [activeMarbles]); 

  // --- Drawing ---
  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110;
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Lines
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';

    // Draw Gate Lines (if closed, or fading out?)
    if (!gateOpenRef.current) {
        ctx.strokeStyle = '#ef4444';
        ctx.beginPath();
        gateLinesRef.current.forEach(l => {
            ctx.moveTo(l.x1, l.y1);
            ctx.lineTo(l.x2, l.y2);
        });
        ctx.stroke();
    }

    // Draw Static Lines
    ctx.strokeStyle = '#4b5563';
    ctx.lineWidth = 6;
    ctx.beginPath();
    linesRef.current.forEach(l => {
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           // ... (Same teleporter draw) ...
           const opacity = obj.timer !== undefined ? obj.timer : 1.0;
           if (opacity > 0.1) {
             ctx.save();
             ctx.translate(obj.x, obj.y);
             ctx.globalAlpha = opacity;
             ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
             ctx.strokeStyle = '#d946ef'; ctx.stroke();
             ctx.fillText(obj.destY! < obj.y ? 'TRAP' : 'IN', -10, 0);
             ctx.restore();
           }
           if (obj.destX) {
               ctx.save(); ctx.translate(obj.destX, obj.destY!);
               ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
               ctx.strokeStyle = '#06b6d4'; ctx.stroke();
               ctx.fillText('OUT', -10, 0);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = 'rgba(255,255,255,0.1)';
          ctx.fillRect(0, -obj.width/2, obj.height||200, obj.width);
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);
       } else if (obj.type === 'repulsor') {
          const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
          ctx.beginPath(); ctx.arc(0,0,obj.width/2 + pulse * 20, 0, Math.PI*2);
          ctx.strokeStyle = '#8b5cf6'; ctx.stroke();
          ctx.beginPath(); ctx.arc(0,0,obj.width/2, 0, Math.PI*2);
          ctx.fillStyle = '#8b5cf6'; ctx.fill();
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.stroke();
       } else {
         // Generic rectangle for slider/spinner/conveyor
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();
         if (obj.type === 'conveyor') {
             ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.setLineDash([5,5]);
             ctx.stroke(); ctx.setLineDash([]);
         }
       }
       ctx.restore();
    });

    // Countdown Text inside Mixer
    if (!gateOpenRef.current) {
        const elapsed = Date.now() - startTime.current;
        const timeLeft = Math.max(0, Math.ceil((GATE_DELAY - elapsed) / 1000));
        ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
        ctx.font = 'bold 60px "Righteous"';
        ctx.textAlign = 'center';
        ctx.fillText(timeLeft.toString(), START_CX, START_CY - 100);
    }

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff'; ctx.fill();
        ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
      }
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.fill();
      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
      if (!m.finished) {
        ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Mutable refs for performance)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Cache for loaded images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  // Constants
  const COURSE_WIDTH = 600;

  // --- Particle Helper ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03, // Random fade speed
        color: color,
        size: 1 + Math.random() * 2
      });
    }
  };

  // --- Level Generation ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    let currentY = 150;

    // --- 1. PLINKO START (Triângulo de Pinos) ---
    // Funnel walls at top
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 150, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 150, type: 'wall' });

    // Plinko Grid
    const rows = 9;
    for (let r = 0; r < rows; r++) {
       const cols = r + 3;
       const rowY = currentY + r * 50;
       const spacing = 70;
       const rowWidth = (cols - 1) * spacing;
       const startX = (COURSE_WIDTH - rowWidth) / 2;

       for (let c = 0; c < cols; c++) {
           pins.push({
               x: startX + c * spacing,
               y: rowY,
               radius: 6,
               type: 'pin'
           });
       }
    }
    currentY += rows * 50 + 50;

    // Funnel after Plinko
    lines.push({ x1: 0, y1: currentY - 50, x2: COURSE_WIDTH * 0.4, y2: currentY + 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH * 0.6, y2: currentY + 100, type: 'wall' });
    currentY += 150;

    // --- 2. Procedural Segments ---
    const segmentCount = 15; 
    const segmentHeight = 400;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';

        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;

        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Standard Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 150, angle: 0, speed: 0.1 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 150, angle: Math.PI / 2, speed: -0.1 });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 220, width: 220, angle: 0, speed: 2.0, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 220 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 340, width: 220, angle: 0, speed: -2.5, range: 180, initialX: COURSE_WIDTH / 2, initialY: currentY + 340 });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        const gap = 120;
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 - gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 90, initialX: COURSE_WIDTH * 0.5 - gap, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 + gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 90, initialX: COURSE_WIDTH * 0.5 + gap, initialY: currentY + 250 });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 60, range: 160, angle: 0, speed: 0.15, force: 3.5 });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 350, radius: 15, type: 'pin' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 350, radius: 15, type: 'pin' });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 4);
        let cx = COURSE_WIDTH * 0.5;
        let cy = currentY + 250;
        let w = 250; let h = 120;
        let ang = 0;

        if (dirType === 0) { ang = 0; cx = COURSE_WIDTH * 0.3; } // Push Right
        else if (dirType === 1) { ang = Math.PI; cx = COURSE_WIDTH * 0.7; } // Push Left
        else if (dirType === 2) { ang = Math.PI/4; w = 300; h=50; } // Diagonal Down Right
        else { ang = 3*Math.PI/4; w = 300; h=50; } // Diagonal Down Left

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: cy, width: w, height: h, angle: ang, speed: 0, force: 20 });

      } else if (type === 'teleporter') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        const entranceX = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 100 : -100);
        const isTrap = Math.random() < 0.4;
        const exitY = isTrap ? currentY - 500 : currentY + 800;
        const exitX = COURSE_WIDTH * 0.5 + (Math.random() * 200 - 100);

        dynamics.push({ 
            id: `teleport_${i}`, type: 'teleporter', 
            x: entranceX, y: currentY + 250, width: 80, 
            destX: exitX, destY: exitY, 
            angle: 0, speed: 0, 
            blinkPhase: Math.random() * Math.PI, blinkSpeed: 0.05, 
            active: true 
        });
        pins.push({ x: entranceX, y: currentY + 180, radius: 15, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ 
            id: `hollow_${i}`, type: 'hollow_circle', 
            x: COURSE_WIDTH / 2, y: currentY + 280, 
            width: 280, angle: 0, 
            speed: (Math.random() > 0.5 ? 1 : -1) * 0.04, 
            range: Math.PI / 3 
        });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({ 
            id: `laser_${i}`, type: 'laser', 
            x: COURSE_WIDTH * 0.1, y: currentY + 300, 
            width: 0, height: COURSE_WIDTH * 0.8, 
            angle: 0, speed: 0, force: 40, 
            active: true, timer: 0 
        });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const h = 300;
        const exitGap = 60;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + h, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + h, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + h + 60, radius: 25, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        dynamics.push({ id: `fan_${i}_L`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 350, angle: 0, speed: 0, force: 1.2 });
        dynamics.push({ id: `fan_${i}_R`, type: 'fan', x: COURSE_WIDTH - 20, y: currentY + 350, width: 50, height: 350, angle: Math.PI, speed: 0, force: 1.2 });
      }

      currentY += segmentHeight;
    }

    // Final Stretch
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Logic ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // --- MERCY RULE CHECK ---
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    const totalMarbles = marbles.length;

    if (totalMarbles > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = totalMarbles; 
            loser.finishTime = now - startTime.current + 99999; 
        }

        if (!raceFinished.current) {
            raceFinished.current = true;
            const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
            audio.playFinish(); 
            setTimeout(() => onRaceFinish(sorted), 1000);
            return;
        }
    }

    // Dynamic Updates
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      } else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      } else if (obj.type === 'teleporter') {
        const val = Math.sin(timeRef.current * (obj.blinkSpeed || 0.05) + (obj.blinkPhase || 0));
        obj.active = val > -0.3; // More uptime
        obj.timer = (val + 1) / 2; 
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'conveyor' || obj.type === 'slider_h' || obj.type === 'slider_v') {
          const halfW = obj.width / 2;
          const dx = Math.cos(obj.angle) * halfW;
          const dy = Math.sin(obj.angle) * halfW;
          dynamicLines.push({
            x1: obj.x - dx, y1: obj.y - dy,
            x2: obj.x + dx, y2: obj.y + dy,
            type: obj.type === 'spinner' ? 'bouncer' : 'floor'
          });
      }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // --- SAFETY BOUNDARIES ---
        if (m.x < m.radius) {
            m.x = m.radius;
            m.vx = Math.abs(m.vx) * 0.5; 
        } else if (m.x > COURSE_WIDTH - m.radius) {
            m.x = COURSE_WIDTH - m.radius;
            m.vx = -Math.abs(m.vx) * 0.5; 
        }

        // --- DYNAMIC FIELDS (Fans, Repulsors, etc) ---
        dynamicObjs.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
                const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
                const halfWidth = obj.width / 2; 
                const range = obj.height || 200;
                if (localX > 0 && localX < range && Math.abs(localY) < halfWidth) {
                    m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
                    m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
                }
            } else if (obj.type === 'repulsor') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const distSq = dx*dx + dy*dy;
                if (distSq < (obj.range || 100)**2) {
                    const dist = Math.sqrt(distSq);
                    const force = (obj.force || 1) * (1 - dist/(obj.range||100));
                    m.vx += (dx/dist) * force * dt * 50;
                    m.vy += (dy/dist) * force * dt * 50;
                }
            } else if (obj.type === 'conveyor') {
               const dx = m.x - obj.x;
               const dy = m.y - obj.y;
               const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
               const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
               if (Math.abs(localParallel) < obj.width/2 && Math.abs(localPerp) < (obj.height||50)/2) {
                  m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                  m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
               }
            } else if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = (obj.width / 2);
                const thickness = 6;
                if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit Wall
                        const nx = dx / dist;
                        const ny = dy / dist;
                        const pushSign = dist < r ? -1 : 1;
                        const overlap = (m.radius + thickness) - Math.abs(dist - r);
                        if (overlap > 0) {
                            m.x += nx * pushSign * overlap * 0.5;
                            m.y += ny * pushSign * overlap * 0.5;
                            const nX = nx * pushSign;
                            const nY = ny * pushSign;
                            const dot = m.vx * nX + m.vy * nY;
                            m.vx = (m.vx - 2 * dot * nX) * config.restitution;
                            m.vy = (m.vy - 2 * dot * nY) * config.restitution;
                        }
                    }
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x;
                const dy = m.y - obj.y;
                if (dx*dx + dy*dy < (obj.width/2)**2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                     m.x = obj.destX || m.x;
                     m.y = obj.destY || m.y;
                     m.vx *= 0.2; 
                     m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2; 
                     teleportCooldowns.current[m.id] = now + 1500; 
                     audio.playPinHit(8); 
                     spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
                }
            } else if (obj.type === 'laser' && obj.active) {
                // Simplified Laser (Line Segment distance check)
                const len = obj.height || 300;
                const x2 = obj.x + Math.cos(obj.angle) * len;
                const y2 = obj.y + Math.sin(obj.angle) * len;
                // ... (reuse line collision logic logic simplified) ...
                const A = m.x - obj.x; const B = m.y - obj.y;
                const C = x2 - obj.x; const D = y2 - obj.y;
                const dot = A * C + B * D;
                const lenSq = C * C + D * D;
                let param = -1;
                if (lenSq !== 0) param = dot / lenSq;
                let xx, yy;
                if (param < 0) { xx = obj.x; yy = obj.y; }
                else if (param > 1) { xx = x2; yy = y2; }
                else { xx = obj.x + param * C; yy = obj.y + param * D; }
                const dx = m.x - xx; const dy = m.y - yy;
                if (dx*dx + dy*dy < (m.radius + 5)**2) {
                     m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * 20 * dt * 10;
                     spawnParticles(m.x, m.y, '#ef4444', 3, 4);
                }
            }
        });

        // COLLISIONS
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          const finishedSoFar = marbles.filter(b => b.finished).length;
          m.rank = finishedSoFar;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy + m.omega*m.radius*m.omega*m.radius);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // --- CAMERA LOGIC ---
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        if (betMarble && !betMarble.finished) {
            targetY = betMarble.y - 300; 
        } else {
             const activeMarblesList = marbles.filter(m => !m.finished);
             if (activeMarblesList.length > 0) {
                 activeMarblesList.sort((a, b) => b.y - a.y);
                 targetY = activeMarblesList[0].y - 300;
             }
        }
    } else {
        const activeMarblesList = marbles.filter(m => !m.finished);
        if (activeMarblesList.length > 0) {
          activeMarblesList.sort((a, b) => b.y - a.y);
          targetY = activeMarblesList[0].y - 300;
        } 
    }
    cameraY.current += (targetY - cameraY.current) * 0.08;

    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) {
        audio.playBump(intensity);
        if (intensity > 3.0) {
            spawnParticles(cx, cy, isBouncy ? '#ef4444' : '#94a3b8', Math.floor(intensity), intensity * 0.5);
        }
    }

    const restitution = isBouncy ? 1.5 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const vSurf = vDotT + ball.omega * ball.radius;

    const mass = 1.0;
    const jT_ideal = -vSurf / (3.5 / mass);
    const mu = 0.5;
    const maxJt = mu * Math.abs(jN);

    let jT = jT_ideal;
    if (Math.abs(jT) > maxJt) {
       jT = Math.sign(jT) * maxJt;
    }

    ball.vx += jT * tx;
    ball.vy += jT * ty;
    ball.omega += (2.5 * jT) / (mass * ball.radius);
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1;
    const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx;
    const closeY = line.y1 + t * dy;

    const distX = ball.x - closeX;
    const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist;
      const ny = distY / dist;

      const overlap = ball.radius - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;

      const isBouncy = isDynamic && line.type === 'bouncer';
      resolveCollisionPhysics(ball, nx, ny, isBouncy, closeX, closeY);

      if (isDynamic) {
        ball.vx += (Math.random() - 0.5) * 2;
        ball.vy += (Math.random() - 0.5) * 2;
      }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x;
    const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = minDist - dist;
      ball.x += nx * overlap;
      ball.y += ny * overlap;
      const isBumper = pin.type === 'bumper';
      const cx = pin.x + nx * pin.radius;
      const cy = pin.y + ny * pin.radius;
      resolveCollisionPhysics(ball, nx, ny, isBumper, cx, cy);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x;
    const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;

    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist;
      const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;

      m1.x -= nx * overlap;
      m1.y -= ny * overlap;
      m2.x += nx * overlap;
      m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx;
      const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;

      if (dot > 0) {
         if (dot > 2) {
             audio.playPinHit(dot * 0.5);
             if (dot > 5) spawnParticles(m1.x + nx * m1.radius, m1.y + ny * m1.radius, '#fff', 3, 2);
         }
         const impulse = dot * 0.9; 
         m1.vx -= impulse * nx;
         m1.vy -= impulse * ny;
         m2.vx += impulse * nx;
         m2.vy += impulse * ny;
      }
    }
  };

  // --- Initialization ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image();
            img.src = m.logoUrl;
            imagesRef.current[m.id] = img;
        }
    });

    // PLINKO START POSITIONS
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH/2 + (Math.random() - 0.5) * 40,
      y: 50 + (i % 2) * 30, // Stack slightly
      vx: (Math.random() - 0.5) * 1,
      vy: 0,
      angle: 0,
      omega: 0,
      finished: false,
      rank: 0
    }));

    audio.resume();
  }, [activeMarbles]); 

  // --- Drawing ---
  const drawLeaderboard = (ctx: CanvasRenderingContext2D, canvasWidth: number, canvasHeight: number) => {
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110;
    const itemHeight = 18;
    const startX = 10; 
    const startY = 90; 

    ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * itemHeight + 10, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.stroke();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    sorted.forEach((m, index) => {
       const y = startY + 10 + index * itemHeight; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#6b7280';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.color; 
       ctx.beginPath();
       ctx.arc(startX + 25, y, 3, 0, Math.PI*2);
       ctx.fill();
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name, startX + 35, y);
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24';
          ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const { offsetWidth, offsetHeight } = canvas;
    if (canvas.width !== offsetWidth || canvas.height !== offsetHeight) {
      canvas.width = offsetWidth;
      canvas.height = offsetHeight;
    }

    ctx.fillStyle = '#1f2937';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // Draw Static Lines
    ctx.strokeStyle = '#4b5563';
    ctx.lineWidth = 6;
    ctx.lineCap = 'round';
    ctx.beginPath();
    linesRef.current.forEach(l => {
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    // Draw Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'teleporter') {
           // ... (Same teleporter draw) ...
           const opacity = obj.timer !== undefined ? obj.timer : 1.0;
           if (opacity > 0.1) {
             ctx.save();
             ctx.translate(obj.x, obj.y);
             ctx.globalAlpha = opacity;
             ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
             ctx.strokeStyle = '#d946ef'; ctx.stroke();
             ctx.fillText(obj.destY! < obj.y ? 'TRAP' : 'IN', -10, 0);
             ctx.restore();
           }
           if (obj.destX) {
               ctx.save(); ctx.translate(obj.destX, obj.destY!);
               ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2);
               ctx.strokeStyle = '#06b6d4'; ctx.stroke();
               ctx.fillText('OUT', -10, 0);
               ctx.restore();
           }
           return;
       }

       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'fan') {
          ctx.fillStyle = 'rgba(255,255,255,0.1)';
          ctx.fillRect(0, -obj.width/2, obj.height||200, obj.width);
          ctx.fillStyle = '#64748b';
          ctx.fillRect(-10, -obj.width/2, 20, obj.width);
       } else if (obj.type === 'repulsor') {
          const pulse = (Math.sin(timeRef.current * obj.speed) + 1) * 0.5;
          ctx.beginPath(); ctx.arc(0,0,obj.width/2 + pulse * 20, 0, Math.PI*2);
          ctx.strokeStyle = '#8b5cf6'; ctx.stroke();
          ctx.beginPath(); ctx.arc(0,0,obj.width/2, 0, Math.PI*2);
          ctx.fillStyle = '#8b5cf6'; ctx.fill();
       } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.beginPath();
             ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
             ctx.strokeStyle = '#d946ef'; 
             ctx.lineWidth = 12;
             ctx.stroke();
       } else {
         // Generic rectangle for slider/spinner/conveyor
         ctx.strokeStyle = obj.type === 'spinner' ? '#ef4444' : '#f59e0b';
         ctx.lineWidth = 8;
         ctx.beginPath();
         ctx.moveTo(-obj.width/2, 0);
         ctx.lineTo(obj.width/2, 0);
         ctx.stroke();
         if (obj.type === 'conveyor') {
             ctx.lineWidth = 2; ctx.strokeStyle = '#fff'; ctx.setLineDash([5,5]);
             ctx.stroke(); ctx.setLineDash([]);
         }
       }
       ctx.restore();
    });

    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    pinsRef.current.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
    });

    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

    // Draw Marbles
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 
      const img = imagesRef.current[m.id];
      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#ffffff'; ctx.fill();
        ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
      }
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = m.color; ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.25, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.4)'; ctx.fill();
      ctx.restore(); 

      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
      if (!m.finished) {
        ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
        ctx.fillText(m.name, m.x, m.y - m.radius - 8);
      }
    });

    ctx.restore(); 
    drawLeaderboard(ctx, canvas.width, canvas.height);
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  });

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  // Camera & Game State
  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  const COURSE_WIDTH = 600;

  // --- Particle System ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 3
      });
    }
  };

  // --- Level Generator (PLINKO VERSION) ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    let currentY = 120;

    // 1. PLINKO START
    // Funnel walls
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 120, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 120, type: 'wall' });

    // Triangle of pins
    const rows = 10;
    for (let r = 0; r < rows; r++) {
       const cols = r + 3;
       const rowY = currentY + r * 45;
       const spacing = 60;
       const rowWidth = (cols - 1) * spacing;
       const startX = (COURSE_WIDTH - rowWidth) / 2;

       for (let c = 0; c < cols; c++) {
           pins.push({
               x: startX + c * spacing,
               y: rowY,
               radius: 7,
               type: 'pin'
           });
       }
    }
    currentY += rows * 45 + 50;

    // Funnel out of Plinko
    lines.push({ x1: 0, y1: currentY - 50, x2: COURSE_WIDTH * 0.35, y2: currentY + 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH * 0.65, y2: currentY + 100, type: 'wall' });
    currentY += 150;

    // 2. OBSTACLES
    const segmentCount = 15;
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Outer Walls
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        // Floor guides
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });

        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 160, angle: 0, speed: 0.08 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 160, angle: Math.PI / 2, speed: -0.08 });

      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `slide_h_top_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 220, width: 220, angle: 0, speed: 2.0, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 220 });
        dynamics.push({ id: `slide_h_bot_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 340, width: 220, angle: 0, speed: -2.5, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 340 });

      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        const gap = 130;
        dynamics.push({ id: `slide_v_L_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 - gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.5 - gap, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_R_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.5 + gap, y: currentY + 250, width: 120, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.5 + gap, initialY: currentY + 250 });

      } else if (type === 'repulsor') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'floor' });

        dynamics.push({ id: `repulse_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 300, width: 60, range: 150, angle: 0, speed: 0.1, force: 3.5 });
        pins.push({ x: COURSE_WIDTH * 0.2, y: currentY + 350, radius: 15, type: 'pin' });
        pins.push({ x: COURSE_WIDTH * 0.8, y: currentY + 350, radius: 15, type: 'pin' });

      } else if (type === 'conveyor') {
        const dirType = Math.floor(Math.random() * 4);
        let cx = COURSE_WIDTH * 0.5; let cy = currentY + 250;
        let w = 250; let h = 100; let ang = 0;

        if (dirType === 0) { ang = 0; cx = COURSE_WIDTH * 0.3; } 
        else if (dirType === 1) { ang = Math.PI; cx = COURSE_WIDTH * 0.7; } 
        else if (dirType === 2) { ang = Math.PI/4; w = 300; h=50; } 
        else { ang = 3*Math.PI/4; w = 300; h=50; }

        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'wall' });

        dynamics.push({ id: `conveyor_${i}`, type: 'conveyor', x: cx, y: cy, width: w, height: h, angle: ang, speed: 0, force: 18 });

      } else if (type === 'teleporter') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.1, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.9, y2: currentY + 150, type: 'floor' });

        const entranceX = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 100 : -100);
        const isTrap = Math.random() < 0.3;
        const exitY = isTrap ? currentY - 500 : currentY + 800;
        const exitX = COURSE_WIDTH * 0.5 + (Math.random() * 200 - 100);

        dynamics.push({ 
            id: `teleport_${i}`, type: 'teleporter', 
            x: entranceX, y: currentY + 250, width: 80, 
            destX: exitX, destY: exitY, 
            angle: 0, speed: 0, 
            blinkPhase: Math.random() * Math.PI, blinkSpeed: 0.05, 
            active: true 
        });
        pins.push({ x: entranceX, y: currentY + 190, radius: 15, type: 'bumper' });

      } else if (type === 'hollow_circle') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });

        dynamics.push({ 
            id: `hollow_${i}`, type: 'hollow_circle', 
            x: COURSE_WIDTH / 2, y: currentY + 280, 
            width: 260, angle: 0, 
            speed: (Math.random() > 0.5 ? 1 : -1) * 0.03, 
            range: Math.PI / 3.5 
        });

      } else if (type === 'laser') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });

        dynamics.push({ 
            id: `laser_${i}`, type: 'laser', 
            x: COURSE_WIDTH * 0.1, y: currentY + 300, 
            width: 0, height: COURSE_WIDTH * 0.8, 
            angle: 0, speed: 0, force: 35, 
            active: true, timer: 0 
        });

      } else if (type === 'funnel') {
        const funnelTopY = currentY + 50;
        const h = 300;
        const exitGap = 65;
        lines.push({ x1: 0, y1: funnelTopY, x2: COURSE_WIDTH/2 - exitGap/2, y2: funnelTopY + h, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: funnelTopY, x2: COURSE_WIDTH/2 + exitGap/2, y2: funnelTopY + h, type: 'wall' });
        pins.push({ x: COURSE_WIDTH/2, y: funnelTopY + h + 60, radius: 25, type: 'bumper' });

      } else if (type === 'fan') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 100, type: 'floor' });

        dynamics.push({ id: `fan_${i}_L`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 350, angle: 0, speed: 0, force: 1.2 });
        dynamics.push({ id: `fan_${i}_R`, type: 'fan', x: COURSE_WIDTH - 20, y: currentY + 350, width: 50, height: 350, angle: Math.PI, speed: 0, force: 1.2 });
      }

      currentY += segmentHeight;
    }

    // Final Stretch
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 200, type: 'floor' });

    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Physics Loop ---
  const update = () => {
    if (isPaused) {
        audio.updateRolling(0);
        return;
    }

    if (raceFinished.current) {
        audio.updateRolling(0); 
        return;
    }

    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;
    const dynamicObjs = dynamicRef.current;

    // Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= p.decay;
        if (p.life <= 0) {
            particlesRef.current.splice(i, 1);
        }
    }

    let totalSpeed = 0;

    // Mercy Rule
    const activeMarblesCount = marbles.filter(m => !m.finished).length;
    if (marbles.length > 1 && activeMarblesCount === 1) {
        const loser = marbles.find(m => !m.finished);
        if (loser) {
            loser.finished = true;
            loser.rank = marbles.length; 
            loser.finishTime = now - startTime.current + 99999; 
        }
    }

    // Dynamic Updates
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'hollow_circle') {
        obj.angle += obj.speed;
      } else if (obj.type === 'slider_h') {
        obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
      } else if (obj.type === 'slider_v') {
        obj.y = obj.initialY! + Math.sin(timeRef.current * 0.015) * (obj.range || 80);
      } else if (obj.type === 'laser') {
        obj.timer = (obj.timer || 0) + 1;
        if (obj.timer > 180) { obj.active = !obj.active; obj.timer = 0; }
      } else if (obj.type === 'teleporter') {
        const val = Math.sin(timeRef.current * (obj.blinkSpeed || 0.05) + (obj.blinkPhase || 0));
        obj.active = val > -0.3; 
        obj.timer = (val + 1) / 2; 
      }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicObjs.forEach(obj => {
      if (obj.type === 'spinner' || obj.type === 'conveyor' || obj.type === 'slider_h' || obj.type === 'slider_v') {
          const halfW = obj.width / 2;
          const dx = Math.cos(obj.angle) * halfW;
          const dy = Math.sin(obj.angle) * halfW;
          dynamicLines.push({
            x1: obj.x - dx, y1: obj.y - dy,
            x2: obj.x + dx, y2: obj.y + dy,
            type: obj.type === 'spinner' ? 'bouncer' : 'floor'
          });
      }
    });

    for (let step = 0; step < STEPS; step++) {
      for (let i = 0; i < marbles.length; i++) {
        const m = marbles[i];
        if (m.finished) continue;

        m.vy += config.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Boundaries
        if (m.x < m.radius) { m.x = m.radius; m.vx *= -0.5; }
        if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx *= -0.5; }

        // Dynamic Field Effects
        dynamicObjs.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const localX = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle);
                const localY = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle);
                if (localX > 0 && localX < (obj.height||200) && Math.abs(localY) < obj.width/2) {
                    m.vx += Math.cos(obj.angle) * (obj.force || 0.5) * dt;
                    m.vy += Math.sin(obj.angle) * (obj.force || 0.5) * dt;
                }
            } else if (obj.type === 'repulsor') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.range || 100)) {
                    const force = (obj.force || 1) * (1 - dist/(obj.range||100));
                    m.vx += (dx/dist) * force * dt * 50;
                    m.vy += (dy/dist) * force * dt * 50;
                }
            } else if (obj.type === 'conveyor') {
               const dx = m.x - obj.x; const dy = m.y - obj.y;
               const localParallel = dx * Math.cos(-obj.angle) - dy * Math.sin(-obj.angle); 
               const localPerp = dx * Math.sin(-obj.angle) + dy * Math.cos(-obj.angle); 
               if (Math.abs(localParallel) < obj.width/2 && Math.abs(localPerp) < (obj.height||50)/2) {
                  m.vx += Math.cos(obj.angle) * (obj.force || 10) * dt;
                  m.vy += Math.sin(obj.angle) * (obj.force || 10) * dt;
               }
            } else if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = (obj.width / 2);
                const thickness = 8;
                if (dist + m.radius >= r - thickness && dist - m.radius <= r + thickness) {
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Not in gap
                        const nx = dx / dist; const ny = dy / dist;
                        const pushSign = dist < r ? -1 : 1;
                        const overlap = (m.radius + thickness) - Math.abs(dist - r);
                        if (overlap > 0) {
                            m.x += nx * pushSign * overlap * 0.5;
                            m.y += ny * pushSign * overlap * 0.5;
                            const dot = m.vx * nx * pushSign + m.vy * ny * pushSign;
                            m.vx -= 2 * dot * nx * pushSign * 0.6;
                            m.vy -= 2 * dot * ny * pushSign * 0.6;
                        }
                    }
                }
            } else if (obj.type === 'teleporter' && obj.active) {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                if (dx*dx + dy*dy < (obj.width/2)**2 && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                     m.x = obj.destX || m.x; m.y = obj.destY || m.y;
                     m.vx *= 0.2; m.vy = (obj.destY||0) < obj.y ? 0 : Math.abs(m.vy) + 2; 
                     teleportCooldowns.current[m.id] = now + 1500; 
                     audio.playPinHit(8); spawnParticles(m.x, m.y, '#06b6d4', 15, 4); 
                }
            } else if (obj.type === 'laser' && obj.active) {
                // Laser Hit Check
                const len = obj.height || 300;
                const x2 = obj.x + Math.cos(obj.angle) * len;
                const y2 = obj.y + Math.sin(obj.angle) * len;
                const A = m.x - obj.x; const B = m.y - obj.y;
                const C = x2 - obj.x; const D = y2 - obj.y;
                const dot = A * C + B * D;
                const lenSq = C * C + D * D;
                let param = -1;
                if (lenSq !== 0) param = dot / lenSq;
                let xx, yy;
                if (param < 0) { xx = obj.x; yy = obj.y; }
                else if (param > 1) { xx = x2; yy = y2; }
                else { xx = obj.x + param * C; yy = obj.y + param * D; }
                const dx = m.x - xx; const dy = m.y - yy;
                if (dx*dx + dy*dy < (m.radius + 6)**2) {
                     m.vx += (dx/Math.sqrt(dx*dx+dy*dy)) * 30 * dt * 10;
                     m.vy += (dy/Math.sqrt(dx*dx+dy*dy)) * 30 * dt * 10;
                     spawnParticles(m.x, m.y, '#ef4444', 3, 4);
                }
            }
        });

        // Collision Logic
        for (const line of linesRef.current) checkLineCollision(m, line);
        for (const dLine of dynamicLines) checkLineCollision(m, dLine, true);
        for (const pin of pinsRef.current) checkPinCollision(m, pin);

        for (let j = i + 1; j < marbles.length; j++) {
           if (!marbles[j].finished) checkMarbleCollision(m, marbles[j]);
        }

        if (m.y > finishLineY.current) {
          m.finished = true;
          m.finishTime = Date.now() - startTime.current;
          m.rank = marbles.filter(b => b.finished).length;
          audio.playPinHit(10);
          spawnParticles(m.x, m.y, '#10b981', 10, 4);
        }

        if (!m.finished) {
            totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
        }
      }
    }

    audio.updateRolling(totalSpeed);

    // Camera
    let targetY = cameraY.current;
    if (isFollowingBet && betMarbleId !== null) {
        const betMarble = marbles.find(m => m.id === betMarbleId);
        if (betMarble && !betMarble.finished) targetY = betMarble.y - 300; 
        else {
             const active = marbles.filter(m => !m.finished).sort((a,b)=>b.y - a.y);
             if (active.length > 0) targetY = active[0].y - 300;
        }
    } else {
        const active = marbles.filter(m => !m.finished).sort((a,b)=>b.y - a.y);
        if (active.length > 0) targetY = active[0].y - 300;
    }
    cameraY.current += (targetY - cameraY.current) * 0.1; // Smooth cam

    // Check Finish
    if (marbles.filter(m => !m.finished).length === 0 && !raceFinished.current) {
        raceFinished.current = true;
        const sorted = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish(); 
        setTimeout(() => onRaceFinish(sorted), 1000);
    }
  };

  const resolveCollisionPhysics = (ball: Marble, nx: number, ny: number, isBouncy: boolean, cx: number, cy: number) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return; 

    const intensity = Math.abs(vDotN);
    if (intensity > 1.0) audio.playBump(intensity);

    const restitution = isBouncy ? 1.4 : config.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    // Friction
    const tx = -ny; const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;
    const jT = -vDotT * 0.2; 
    ball.vx += jT * tx;
    ball.vy += jT * ty;
  };

  const checkLineCollision = (ball: Marble, line: LineSegment, isDynamic = false) => {
    const dx = line.x2 - line.x1; const dy = line.y2 - line.y1;
    const lenSq = dx*dx + dy*dy;
    const t = Math.max(0, Math.min(1, ((ball.x - line.x1) * dx + (ball.y - line.y1) * dy) / lenSq));
    const closeX = line.x1 + t * dx; const closeY = line.y1 + t * dy;
    const distX = ball.x - closeX; const distY = ball.y - closeY;
    const distSq = distX*distX + distY*distY;

    if (distSq < ball.radius * ball.radius) {
      const dist = Math.sqrt(distSq);
      const nx = distX / dist; const ny = distY / dist;
      const overlap = ball.radius - dist;
      ball.x += nx * overlap; ball.y += ny * overlap;
      resolveCollisionPhysics(ball, nx, ny, isDynamic && line.type === 'bouncer', closeX, closeY);
      if (isDynamic) { ball.vx += (Math.random()-0.5); ball.vy += (Math.random()-0.5); }
    }
  };

  const checkPinCollision = (ball: Marble, pin: CircleObstacle) => {
    const dx = ball.x - pin.x; const dy = ball.y - pin.y;
    const distSq = dx*dx + dy*dy;
    const minDist = ball.radius + pin.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist; const ny = dy / dist;
      ball.x += nx * (minDist - dist); ball.y += ny * (minDist - dist);
      resolveCollisionPhysics(ball, nx, ny, pin.type === 'bumper', pin.x + nx*pin.radius, pin.y + ny*pin.radius);
    }
  };

  const checkMarbleCollision = (m1: Marble, m2: Marble) => {
    const dx = m2.x - m1.x; const dy = m2.y - m1.y;
    const distSq = dx*dx + dy*dy;
    const minDist = m1.radius + m2.radius;
    if (distSq < minDist * minDist) {
      const dist = Math.sqrt(distSq);
      const nx = dx / dist; const ny = dy / dist;
      const overlap = (minDist - dist) * 0.5;
      m1.x -= nx * overlap; m1.y -= ny * overlap;
      m2.x += nx * overlap; m2.y += ny * overlap;

      const dvx = m1.vx - m2.vx; const dvy = m1.vy - m2.vy;
      const dot = dvx * nx + dvy * ny;
      if (dot > 0) {
         if (dot > 2) audio.playPinHit(dot * 0.5);
         const impulse = dot * 0.8; 
         m1.vx -= impulse * nx; m1.vy -= impulse * ny;
         m2.vx += impulse * nx; m2.vy += impulse * ny;
      }
    }
  };

  // --- Initial Setup ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img;
        }
    });

    // START POSITIONS
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH/2 + (Math.random() - 0.5) * 60,
      y: 30 + (i % 2) * 25, 
      vx: (Math.random() - 0.5), vy: 0,
      angle: 0, omega: 0, finished: false, rank: 0
    }));

    audio.resume();
  }, [activeMarbles]); // Only reset when activeMarbles changes (new round)

  // --- Drawing ---
  const draw = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Resize
    if (canvas.width !== canvas.offsetWidth || canvas.height !== canvas.offsetHeight) {
      canvas.width = canvas.offsetWidth;
      canvas.height = canvas.offsetHeight;
    }

    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.save();
    const scale = canvas.width / COURSE_WIDTH;
    ctx.scale(scale, scale);
    const camY = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 100));
    ctx.translate(0, -camY);

    // DRAW WALLS
    ctx.strokeStyle = '#4b5563';
    ctx.lineWidth = 6;
    ctx.lineCap = 'round';
    ctx.beginPath();
    linesRef.current.forEach(l => {
      ctx.moveTo(l.x1, l.y1);
      ctx.lineTo(l.x2, l.y2);
    });
    ctx.stroke();

    // DRAW OBSTACLES (Solid Shapes)
    dynamicRef.current.forEach(obj => {
       ctx.save();
       ctx.translate(obj.x, obj.y);
       ctx.rotate(obj.angle);

       if (obj.type === 'spinner') {
           ctx.fillStyle = '#ef4444';
           ctx.shadowColor = 'rgba(239, 68, 68, 0.5)'; ctx.shadowBlur = 15;
           ctx.beginPath();
           ctx.roundRect(-obj.width/2, -6, obj.width, 12, 6);
           ctx.fill();
           ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fill();

       } else if (obj.type === 'slider_h' || obj.type === 'slider_v') {
           ctx.fillStyle = '#f59e0b';
           ctx.shadowColor = 'rgba(245, 158, 11, 0.5)'; ctx.shadowBlur = 10;
           ctx.beginPath();
           ctx.roundRect(-obj.width/2, -10, obj.width, 20, 8);
           ctx.fill();

       } else if (obj.type === 'conveyor') {
           ctx.fillStyle = '#374151';
           ctx.fillRect(-obj.width/2, -obj.height!/2, obj.width, obj.height!);
           // Dashes
           const offset = (timeRef.current * 2) % 40;
           ctx.strokeStyle = '#9ca3af'; ctx.lineWidth = 4; ctx.setLineDash([20, 20]); ctx.lineDashOffset = -offset;
           ctx.beginPath(); ctx.moveTo(-obj.width/2, 0); ctx.lineTo(obj.width/2, 0); ctx.stroke();

       } else if (obj.type === 'fan') {
           // Wind Area
           const grad = ctx.createLinearGradient(0, 0, obj.height!, 0);
           grad.addColorStop(0, 'rgba(100, 200, 255, 0.3)');
           grad.addColorStop(1, 'rgba(100, 200, 255, 0)');
           ctx.fillStyle = grad;
           ctx.fillRect(0, -obj.width/2, obj.height!, obj.width);
           // Fan Base
           ctx.fillStyle = '#64748b';
           ctx.fillRect(-15, -obj.width/2 - 5, 15, obj.width + 10);

       } else if (obj.type === 'repulsor') {
           const pulse = 1 + Math.sin(timeRef.current * 0.1) * 0.1;
           ctx.fillStyle = 'rgba(139, 92, 246, 0.3)';
           ctx.beginPath(); ctx.arc(0,0, (obj.width/2) * pulse * 1.5, 0, Math.PI*2); ctx.fill();
           ctx.fillStyle = '#8b5cf6';
           ctx.beginPath(); ctx.arc(0,0, obj.width/2, 0, Math.PI*2); ctx.fill();

       } else if (obj.type === 'hollow_circle') {
            const r = obj.width / 2;
            const gap = obj.range || 1.0;
            ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 14;
            ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2);
            ctx.stroke();

       } else if (obj.type === 'teleporter') {
           const opacity = obj.timer !== undefined ? obj.timer : 1.0;
           if (opacity > 0.1) {
             ctx.globalAlpha = opacity;
             ctx.fillStyle = '#d946ef';
             ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 20;
             ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
             ctx.globalAlpha = 1.0;
             // Draw swirling effect
             ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
             ctx.beginPath();
             const swirl = (timeRef.current * 0.1) % (Math.PI*2);
             ctx.arc(0,0,obj.width/3, swirl, swirl + Math.PI);
             ctx.stroke();
           }
           if (obj.destX) {
               ctx.save(); ctx.translate(obj.destX - obj.x, obj.destY! - obj.y);
               ctx.strokeStyle = '#06b6d4'; ctx.lineWidth = 4;
               ctx.setLineDash([5,5]);
               ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.stroke();
               ctx.restore();
           }
       } else if (obj.type === 'laser') {
           if (obj.active) {
                ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4;
                ctx.shadowColor = '#f87171'; ctx.shadowBlur = 15;
                ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height!, 0); ctx.stroke();
           }
           ctx.fillStyle = '#333'; ctx.fillRect(-5, -10, 10, 20);
       }
       ctx.restore();
    });

    // DRAW PARTICLES
    particlesRef.current.forEach(p => {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
    });
    ctx.globalAlpha = 1.0;

    // DRAW PINS (Plinko)
    pinsRef.current.forEach(p => {
      ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fillStyle = p.type === 'bumper' ? '#f472b6' : '#9ca3af';
      ctx.fill();
      ctx.strokeStyle = '#000'; ctx.lineWidth = 1; ctx.stroke();
    });

    // DRAW FINISH LINE
    ctx.fillStyle = '#10b981';
    ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 12);
    ctx.fillStyle = '#fff';
    for (let x=0; x<COURSE_WIDTH; x+=40) ctx.fillRect(x, finishLineY.current, 20, 12);

    // DRAW MARBLES
    marblesRef.current.forEach(m => {
      ctx.save();
      ctx.translate(m.x, m.y);
      ctx.rotate(-m.angle); 
      const img = imagesRef.current[m.id];
      // Shadow
      ctx.fillStyle = 'rgba(0,0,0,0.3)'; ctx.beginPath(); ctx.arc(3, 3, m.radius, 0, Math.PI*2); ctx.fill();

      if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#fff'; ctx.fill();
        ctx.save(); ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2); ctx.clip();
        ctx.drawImage(img, -m.radius, -m.radius, m.radius * 2, m.radius * 2);
        ctx.restore();
      } else {
        ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
        ctx.fillStyle = m.color; ctx.fill();
        ctx.fillStyle = '#fff'; ctx.font = 'bold 12px Arial';
        ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
        ctx.fillText(m.name.substring(0, 3).toUpperCase(), 0, 0);
      }

      // Highlight Border
      ctx.beginPath(); ctx.arc(0, 0, m.radius, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(0,0,0,0.2)'; ctx.lineWidth = 1; ctx.stroke();

      // Glossy Shine
      ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.3, 0, Math.PI * 2);
      ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.fill();

      ctx.restore(); 

      // Bet Indicator Ring
      if (m.id === betMarbleId) {
        ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(m.x, m.y, m.radius + 6, 0, Math.PI * 2); ctx.stroke();
      }
      // Name Tag
      if (!m.finished) {
        ctx.fillStyle = '#fff'; ctx.font = '10px Arial'; ctx.textAlign = 'center';
        ctx.shadowColor='black'; ctx.shadowBlur=4;
        ctx.fillText(m.name, m.x, m.y - m.radius - 10);
        ctx.shadowBlur=0;
      }
    });

    ctx.restore(); 

    // UI Overlay: Leaderboard
    const sorted = [...marblesRef.current].sort((a, b) => {
      if (a.finished && b.finished) return a.rank - b.rank;
      if (a.finished) return -1;
      if (b.finished) return 1;
      return b.y - a.y;
    });

    const boxWidth = 110;
    const startX = 10; const startY = 90; 
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.roundRect(startX, startY, boxWidth, sorted.length * 18 + 10, 6);
    ctx.fill();

    ctx.font = 'bold 10px "Roboto Mono"'; 
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    sorted.forEach((m, index) => {
       const y = startY + 10 + index * 18; 
       ctx.fillStyle = index === 0 ? '#fbbf24' : index === 1 ? '#9ca3af' : index === 2 ? '#b45309' : '#9ca3af';
       ctx.fillText(`${index + 1}.`, startX + 5, y);
       ctx.fillStyle = m.finished ? '#10b981' : '#e5e7eb';
       ctx.fillText(m.name.substring(0, 10), startX + 25, y);
       if (m.id === betMarbleId) {
          ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 1;
          ctx.strokeRect(startX + 2, y - 8, boxWidth - 4, 16);
       }
    });
  };

  useEffect(() => {
    const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
    requestRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(requestRef.current!);
  }, [isPaused, activeMarbles, config]); // Add dependencies to ensure fresh closure state if props change

  return (
    <canvas ref={canvasRef} className="w-full h-full block" />
  );
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State (Refs for performance to avoid re-renders during loop)
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Refs to hold latest props (so we don't restart loop on prop change)
  const configRef = useRef(config);
  const pausedRef = useRef(isPaused);

  // Update refs when props change
  useEffect(() => { configRef.current = config; }, [config]);
  useEffect(() => { pausedRef.current = isPaused; }, [isPaused]);

  // Images Cache
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  // Camera & Game State
  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  const COURSE_WIDTH = 600;

  // --- Helper: Particle System ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 3
      });
    }
  };

  // --- Level Generator: PLINKO RESTORED ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    let currentY = 100;

    // --- 1. PLINKO START (Triângulo de Pinos) ---
    // Funnel walls top
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 100, type: 'wall' });

    // The Grid
    const rows = 12;
    for (let r = 0; r < rows; r++) {
       const cols = r + 3; // Pyramid shape
       const rowY = currentY + r * 45;
       const spacing = 55;
       const rowWidth = (cols - 1) * spacing;
       const startX = (COURSE_WIDTH - rowWidth) / 2;

       for (let c = 0; c < cols; c++) {
           pins.push({
               x: startX + c * spacing,
               y: rowY,
               radius: 6,
               type: 'pin'
           });
       }
    }
    currentY += rows * 45 + 50;

    // Funnel out of Plinko
    lines.push({ x1: 0, y1: currentY - 50, x2: COURSE_WIDTH * 0.35, y2: currentY + 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH * 0.65, y2: currentY + 100, type: 'wall' });
    currentY += 150;

    // --- 2. OBSTACLES (Restoring functional logic) ---
    const segmentCount = 15;
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Wall borders
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 160, angle: 0, speed: 0.08 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 160, angle: Math.PI / 2, speed: -0.08 });
      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 280, width: 220, angle: 0, speed: 2.0, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 280 });
      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_1_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.3, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_2_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.7, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.7, initialY: currentY + 250 });
      } else if (type === 'repulsor') {
        dynamics.push({ id: `rep_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 250, width: 80, range: 180, angle: 0, speed: 0.1, force: 4.0 });
        pins.push({ x: COURSE_WIDTH*0.2, y: currentY+300, radius: 15, type:'pin' });
        pins.push({ x: COURSE_WIDTH*0.8, y: currentY+300, radius: 15, type:'pin' });
      } else if (type === 'teleporter') {
        const ex = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 120 : -120);
        dynamics.push({ id: `tp_${i}`, type: 'teleporter', x: ex, y: currentY + 200, width: 70, destX: COURSE_WIDTH/2, destY: currentY + 600, angle: 0, speed: 0, active: true });
        lines.push({ x1: 0, y1: currentY + 100, x2: COURSE_WIDTH, y2: currentY + 100, type: 'floor' });
      } else if (type === 'funnel') {
        const fy = currentY + 50;
        lines.push({ x1: 0, y1: fy, x2: COURSE_WIDTH/2 - 40, y2: fy + 300, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: fy, x2: COURSE_WIDTH/2 + 40, y2: fy + 300, type: 'wall' });
      } else if (type === 'laser') {
        dynamics.push({ id: `lz_${i}`, type: 'laser', x: 50, y: currentY + 200, width: 0, height: 500, angle: 0, speed: 0, force: 40, active: true, timer: 0 });
      } else if (type === 'fan') {
        dynamics.push({ id: `fan_${i}`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 300, angle: 0, speed: 0, force: 1.5 });
      }

      currentY += segmentHeight;
    }

    // Final Stretch
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 200, type: 'floor' });
    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Initialization (Runs ONLY when activeMarbles changes) ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img;
        }
    });

    // Reset Marbles to Top (Plinko Start)
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH/2 + (Math.random() - 0.5) * 50,
      y: 40 + (i * -25), // Stack vertically so they fall one by one or in a stream
      vx: (Math.random() - 0.5) * 2,
      vy: 0,
      angle: 0, omega: 0, finished: false, rank: 0
    }));

    audio.resume();
  }, [activeMarbles]); 

  // --- Physics & Game Loop ---
  const update = () => {
    // Check Pause Ref
    if (pausedRef.current) {
        audio.updateRolling(0);
        return;
    }
    if (raceFinished.current) {
        audio.updateRolling(0);
        return;
    }

    const cfg = configRef.current; // Use Ref
    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;

    // 1. Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    // 2. Update Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'spinner') obj.angle += obj.speed;
       if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
       if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.02) * (obj.range || 80);
       if (obj.type === 'laser') {
           obj.timer = (obj.timer || 0) + 1;
           if (obj.timer > 150) { obj.active = !obj.active; obj.timer = 0; }
       }
       if (obj.type === 'teleporter') {
           const phase = Math.sin(timeRef.current * 0.05);
           obj.active = phase > -0.5;
           obj.timer = (phase + 1) / 2;
       }
    });

    // Create temp collision lines for moving objects
    const dynamicLines: LineSegment[] = [];
    dynamicRef.current.forEach(obj => {
        if (obj.type === 'spinner' || obj.type === 'slider_h' || obj.type === 'slider_v') {
            const hw = obj.width / 2;
            const dx = Math.cos(obj.angle) * hw;
            const dy = Math.sin(obj.angle) * hw;
            dynamicLines.push({
                x1: obj.x - dx, y1: obj.y - dy,
                x2: obj.x + dx, y2: obj.y + dy,
                type: 'bouncer'
            });
        }
    });

    let totalSpeed = 0;

    // 3. Marble Physics Steps
    for (let step = 0; step < STEPS; step++) {
      for (const m of marbles) {
        if (m.finished) continue;

        m.vy += cfg.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Walls
        if (m.x < m.radius) { m.x = m.radius; m.vx *= -0.5; }
        if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx *= -0.5; }

        // Interactions
        dynamicRef.current.forEach(obj => {
            // Fan
            if (obj.type === 'fan') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy); // Simple radial check first
                if (dist < (obj.height || 300) && Math.abs(dy) < obj.width) {
                     m.vx += Math.cos(obj.angle) * (obj.force || 1) * dt;
                     m.vy += Math.sin(obj.angle) * (obj.force || 1) * dt;
                }
            }
            // Repulsor
            if (obj.type === 'repulsor') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.range || 100)) {
                    const f = (1 - dist/(obj.range||100)) * (obj.force||2);
                    m.vx += (dx/dist)*f*dt*40; m.vy += (dy/dist)*f*dt*40;
                }
            }
            // Laser
            if (obj.type === 'laser' && obj.active) {
                 const lx = obj.x + Math.cos(obj.angle)*obj.height!;
                 const ly = obj.y + Math.sin(obj.angle)*obj.height!;
                 // Point to segment distance (simplified)
                 const closeX = Math.max(obj.x, Math.min(lx, m.x)); // Horizontal laser approx
                 const closeY = obj.y; 
                 const dx = m.x - closeX; const dy = m.y - closeY;
                 if (dx*dx+dy*dy < 400 && Math.abs(dy) < 20) {
                     m.vx += (Math.random()-0.5)*50; m.vy += -20;
                     spawnParticles(m.x, m.y, '#ef4444', 5, 5);
                 }
            }
            // Teleporter
            if (obj.type === 'teleporter' && obj.active && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                if (dx*dx+dy*dy < (obj.width/2)**2) {
                    m.x = obj.destX!; m.y = obj.destY!;
                    m.vy = Math.abs(m.vy) + 2;
                    teleportCooldowns.current[m.id] = now + 2000;
                    audio.playPinHit(10);
                    spawnParticles(m.x, m.y, '#06b6d4', 20, 5);
                }
            }
        });

        // Collisions
        for (const line of linesRef.current) checkLine(m, line, cfg);
        for (const dline of dynamicLines) checkLine(m, dline, cfg, true);
        for (const pin of pinsRef.current) checkPin(m, pin, cfg);

        // Marble-Marble
        for (const other of marbles) {
            if (m === other || other.finished) continue;
            const dx = other.x - m.x; const dy = other.y - m.y;
            const distSq = dx*dx + dy*dy;
            const minD = m.radius + other.radius;
            if (distSq < minD*minD) {
                const dist = Math.sqrt(distSq);
                const nx = dx/dist; const ny = dy/dist;
                const pen = (minD - dist) * 0.5;
                m.x -= nx*pen; m.y -= ny*pen;
                other.x += nx*pen; other.y += ny*pen;

                const dvx = m.vx - other.vx; const dvy = m.vy - other.vy;
                const dot = dvx*nx + dvy*ny;
                if (dot > 0) {
                   const J = dot * 0.9;
                   m.vx -= J*nx; m.vy -= J*ny;
                   other.vx += J*nx; other.vy += J*ny;
                   if (J > 2) audio.playPinHit(J*0.2);
                }
            }
        }

        // Finish Check
        if (m.y > finishLineY.current && !m.finished) {
            m.finished = true;
            m.finishTime = now;
            m.rank = marbles.filter(b => b.finished).length;
            spawnParticles(m.x, m.y, '#10b981', 15, 5);
            audio.playPinHit(20);
        }

        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
      }
    }

    audio.updateRolling(totalSpeed);

    // Camera
    let target = cameraY.current;
    if (isFollowingBet && betMarbleId) {
        const b = marbles.find(m => m.id === betMarbleId);
        if (b && !b.finished) target = b.y - 300;
    } else {
        const active = marbles.filter(m => !m.finished).sort((a,b)=>b.y - a.y);
        if (active.length > 0) target = active[0].y - 300;
    }
    cameraY.current += (target - cameraY.current) * 0.1;

    // End Condition
    if (marbles.every(m => m.finished) && !raceFinished.current) {
        raceFinished.current = true;
        const results = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish();
        setTimeout(() => onRaceFinish(results), 1000);
    }
  };

  const checkLine = (m: Marble, line: LineSegment, cfg: PhysicsConfig, isDynamic=false) => {
      const dx = line.x2 - line.x1; const dy = line.y2 - line.y1;
      const lenSq = dx*dx + dy*dy;
      const t = Math.max(0, Math.min(1, ((m.x - line.x1)*dx + (m.y - line.y1)*dy)/lenSq));
      const cx = line.x1 + t*dx; const cy = line.y1 + t*dy;
      const distX = m.x - cx; const distY = m.y - cy;
      const distSq = distX*distX + distY*distY;

      if (distSq < m.radius*m.radius) {
          const dist = Math.sqrt(distSq);
          const nx = distX/dist; const ny = distY/dist;
          m.x += nx * (m.radius - dist);
          m.y += ny * (m.radius - dist);

          const vDotN = m.vx*nx + m.vy*ny;
          if (vDotN < 0) {
              const rest = isDynamic ? 1.5 : cfg.restitution;
              const j = -(1+rest) * vDotN;
              m.vx += j*nx; m.vy += j*ny;
              if (Math.abs(j) > 2) audio.playBump(Math.abs(j));
          }
      }
  };

  const checkPin = (m: Marble, pin: CircleObstacle, cfg: PhysicsConfig) => {
      const dx = m.x - pin.x; const dy = m.y - pin.y;
      const distSq = dx*dx + dy*dy;
      const minD = m.radius + pin.radius;
      if (distSq < minD*minD) {
          const dist = Math.sqrt(distSq);
          const nx = dx/dist; const ny = dy/dist;
          m.x += nx * (minD - dist); m.y += ny * (minD - dist);

          const vDotN = m.vx*nx + m.vy*ny;
          if (vDotN < 0) {
              const rest = pin.type === 'bumper' ? 1.5 : 0.8;
              const j = -(1+rest) * vDotN;
              m.vx += j*nx; m.vy += j*ny;
              audio.playPinHit(Math.abs(j));
          }
      }
  };

  // --- Draw Loop ---
  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (canvas.width !== canvas.offsetWidth) {
          canvas.width = canvas.offsetWidth;
          canvas.height = canvas.offsetHeight;
      }

      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      const scale = canvas.width / COURSE_WIDTH;
      ctx.scale(scale, scale);
      const cam = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 150));
      ctx.translate(0, -cam);

      // 1. Draw Static Lines
      ctx.lineWidth = 5; ctx.lineCap = 'round'; ctx.strokeStyle = '#4b5563';
      ctx.beginPath();
      linesRef.current.forEach(l => { ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); });
      ctx.stroke();

      // 2. Draw Obstacles (Simple Solid Shapes to guarantee visibility)
      dynamicRef.current.forEach(obj => {
          ctx.save();
          ctx.translate(obj.x, obj.y);
          ctx.rotate(obj.angle);

          if (obj.type === 'spinner') {
              ctx.fillStyle = '#ef4444';
              ctx.fillRect(-obj.width/2, -8, obj.width, 16);
              ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fillStyle='#fff'; ctx.fill();
          } else if (obj.type.startsWith('slider')) {
              ctx.fillStyle = '#f59e0b';
              ctx.fillRect(-obj.width/2, -10, obj.width, 20);
          } else if (obj.type === 'repulsor') {
              ctx.fillStyle = 'rgba(139, 92, 246, 0.4)';
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#8b5cf6'; ctx.lineWidth=2; ctx.stroke();
          } else if (obj.type === 'fan') {
              ctx.fillStyle = 'rgba(56, 189, 248, 0.2)';
              ctx.fillRect(0, -obj.width/2, obj.height!, obj.width);
              ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width);
          } else if (obj.type === 'laser' && obj.active) {
              ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; 
              ctx.shadowColor = 'red'; ctx.shadowBlur = 10;
              ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height!, 0); ctx.stroke();
              ctx.shadowBlur = 0;
          } else if (obj.type === 'teleporter') {
              ctx.fillStyle = `rgba(217, 70, 239, ${obj.timer})`;
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              if (obj.destX) {
                  ctx.save(); ctx.translate(obj.destX-obj.x, obj.destY!-obj.y);
                  ctx.strokeStyle = '#06b6d4'; ctx.lineWidth=2; ctx.setLineDash([5,5]);
                  ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.stroke();
                  ctx.restore();
              }
          }
          ctx.restore();
      });

      // 3. Draw Particles
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Draw Pins
      pinsRef.current.forEach(p => {
          ctx.fillStyle = '#9ca3af';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI*2); ctx.fill();
      });

      // 5. Draw Finish
      ctx.fillStyle = '#10b981';
      ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

      // 6. Draw Marbles
      marblesRef.current.forEach(m => {
          ctx.save();
          ctx.translate(m.x, m.y);
          ctx.rotate(-m.angle);

          const img = imagesRef.current[m.id];
          if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.clip();
              ctx.drawImage(img, -m.radius, -m.radius, m.radius*2, m.radius*2);
          } else {
              ctx.fillStyle = m.color;
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.fill();
          }
          // Border
          ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.stroke();

          // Bet Highlight
          if (m.id === betMarbleId) {
              ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 4;
              ctx.stroke();
          }
          ctx.restore();

          if (!m.finished) {
            ctx.fillStyle = 'white'; ctx.font='12px Arial'; ctx.textAlign='center';
            ctx.fillText(m.name, m.x, m.y - m.radius - 10);
          }
      });

      ctx.restore();

      // Leaderboard
      const sorted = [...marblesRef.current].sort((a,b) => {
          if (a.finished && b.finished) return a.rank - b.rank;
          if (a.finished) return -1;
          if (b.finished) return 1;
          return b.y - a.y;
      });

      const baseX = 10, baseY = 90;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(baseX, baseY, 120, sorted.length*20 + 10);
      ctx.font = '10px monospace'; ctx.textAlign='left';
      sorted.forEach((m, i) => {
          ctx.fillStyle = m.id === betMarbleId ? '#fbbf24' : '#fff';
          ctx.fillText(`${i+1}. ${m.name.substring(0,10)}`, baseX + 5, baseY + 15 + (i*20));
      });
  };

  useEffect(() => {
      const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
      requestRef.current = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(requestRef.current!);
  }, []);

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Refs for props to avoid dependency loop in update
  const configRef = useRef(config);
  const pausedRef = useRef(isPaused);

  useEffect(() => { configRef.current = config; }, [config]);
  useEffect(() => { pausedRef.current = isPaused; }, [isPaused]);

  // Images
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  // State
  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  const COURSE_WIDTH = 600;

  // --- Particles ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 3
      });
    }
  };

  // --- Level Generation: PLINKO RESTORED ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    let currentY = 100;

    // 1. PLINKO (Triângulo)
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 100, type: 'wall' });

    const rows = 12;
    for (let r = 0; r < rows; r++) {
       const cols = r + 3;
       const rowY = currentY + r * 45;
       const spacing = 55;
       const rowWidth = (cols - 1) * spacing;
       const startX = (COURSE_WIDTH - rowWidth) / 2;

       for (let c = 0; c < cols; c++) {
           pins.push({ x: startX + c * spacing, y: rowY, radius: 6, type: 'pin' });
       }
    }
    currentY += rows * 45 + 50;

    // Funnel Exit
    lines.push({ x1: 0, y1: currentY - 50, x2: COURSE_WIDTH * 0.35, y2: currentY + 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH * 0.65, y2: currentY + 100, type: 'wall' });
    currentY += 150;

    // 2. OBSTACLES
    const segmentCount = 15;
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 160, angle: 0, speed: 0.08 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 160, angle: Math.PI / 2, speed: -0.08 });
      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 280, width: 220, angle: 0, speed: 2.0, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 280 });
      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_1_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.3, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_2_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.7, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.7, initialY: currentY + 250 });
      } else if (type === 'repulsor') {
        dynamics.push({ id: `rep_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 250, width: 80, range: 180, angle: 0, speed: 0.1, force: 4.0 });
        pins.push({ x: COURSE_WIDTH*0.2, y: currentY+300, radius: 15, type:'pin' });
        pins.push({ x: COURSE_WIDTH*0.8, y: currentY+300, radius: 15, type:'pin' });
      } else if (type === 'teleporter') {
        const ex = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 120 : -120);
        dynamics.push({ id: `tp_${i}`, type: 'teleporter', x: ex, y: currentY + 200, width: 70, destX: COURSE_WIDTH/2, destY: currentY + 600, angle: 0, speed: 0, active: true });
        lines.push({ x1: 0, y1: currentY + 100, x2: COURSE_WIDTH, y2: currentY + 100, type: 'floor' });
      } else if (type === 'funnel') {
        const fy = currentY + 50;
        lines.push({ x1: 0, y1: fy, x2: COURSE_WIDTH/2 - 40, y2: fy + 300, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: fy, x2: COURSE_WIDTH/2 + 40, y2: fy + 300, type: 'wall' });
      } else if (type === 'laser') {
        dynamics.push({ id: `lz_${i}`, type: 'laser', x: 50, y: currentY + 200, width: 0, height: 500, angle: 0, speed: 0, force: 40, active: true, timer: 0 });
      } else if (type === 'fan') {
        dynamics.push({ id: `fan_${i}`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 300, angle: 0, speed: 0, force: 1.5 });
      } else if (type === 'hollow_circle') {
        dynamics.push({ id: `hc_${i}`, type: 'hollow_circle', x: COURSE_WIDTH/2, y: currentY+250, width: 280, angle: 0, speed: 0.04, range: Math.PI/3 });
      }

      currentY += segmentHeight;
    }

    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 200, type: 'floor' });
    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Init ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img;
        }
    });

    // Reset Physics
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH/2 + (Math.random() - 0.5) * 50,
      y: 40 + (i * -25), 
      vx: (Math.random() - 0.5) * 2,
      vy: 0,
      angle: 0, 
      omega: 0, // IMPORTANT: Reset Rotation
      finished: false, 
      rank: 0
    }));

    audio.resume();
  }, [activeMarbles]); 

  // --- Loop ---
  const update = () => {
    if (pausedRef.current) { audio.updateRolling(0); return; }
    if (raceFinished.current) { audio.updateRolling(0); return; }

    const cfg = configRef.current;
    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;

    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    dynamicRef.current.forEach(obj => {
       if (obj.type === 'spinner' || obj.type === 'hollow_circle') obj.angle += obj.speed;
       if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
       if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.02) * (obj.range || 80);
       if (obj.type === 'laser') {
           obj.timer = (obj.timer || 0) + 1;
           if (obj.timer > 150) { obj.active = !obj.active; obj.timer = 0; }
       }
       if (obj.type === 'teleporter') {
           const phase = Math.sin(timeRef.current * 0.05);
           obj.active = phase > -0.5;
           obj.timer = (phase + 1) / 2;
       }
    });

    const dynamicLines: LineSegment[] = [];
    dynamicRef.current.forEach(obj => {
        if (obj.type === 'spinner' || obj.type === 'slider_h' || obj.type === 'slider_v') {
            const hw = obj.width / 2;
            const dx = Math.cos(obj.angle) * hw;
            const dy = Math.sin(obj.angle) * hw;
            dynamicLines.push({
                x1: obj.x - dx, y1: obj.y - dy,
                x2: obj.x + dx, y2: obj.y + dy,
                type: 'bouncer'
            });
        }
    });

    let totalSpeed = 0;

    for (let step = 0; step < STEPS; step++) {
      for (const m of marbles) {
        if (m.finished) continue;

        m.vy += cfg.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Apply Angular Velocity
        m.angle += m.omega * dt;
        m.omega *= 0.99; // Rolling friction/damping

        if (m.x < m.radius) { m.x = m.radius; m.vx *= -0.5; }
        if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx *= -0.5; }

        dynamicRef.current.forEach(obj => {
            if (obj.type === 'fan') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.height || 300) && Math.abs(dy) < obj.width) {
                     m.vx += Math.cos(obj.angle) * (obj.force || 1) * dt;
                     m.vy += Math.sin(obj.angle) * (obj.force || 1) * dt;
                }
            }
            if (obj.type === 'repulsor') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.range || 100)) {
                    const f = (1 - dist/(obj.range||100)) * (obj.force||2);
                    m.vx += (dx/dist)*f*dt*40; m.vy += (dy/dist)*f*dt*40;
                }
            }
            if (obj.type === 'laser' && obj.active) {
                 const lx = obj.x + Math.cos(obj.angle)*obj.height!;
                 const dx = m.x - Math.max(obj.x, Math.min(lx, m.x));
                 const dy = m.y - obj.y;
                 if (dx*dx+dy*dy < 400 && Math.abs(dy) < 20) {
                     m.vx += (Math.random()-0.5)*50; m.vy += -20;
                     spawnParticles(m.x, m.y, '#ef4444', 5, 5);
                 }
            }
            if (obj.type === 'teleporter' && obj.active && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                if (dx*dx+dy*dy < (obj.width/2)**2) {
                    m.x = obj.destX!; m.y = obj.destY!;
                    m.vy = Math.abs(m.vy) + 2;
                    teleportCooldowns.current[m.id] = now + 2000;
                    audio.playPinHit(10);
                    spawnParticles(m.x, m.y, '#06b6d4', 20, 5);
                }
            }
            if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = obj.width/2;
                if (dist + m.radius > r - 8 && dist - m.radius < r + 8) {
                    // Check Gap
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit
                        const nx = dx/dist; const ny = dy/dist;
                        const pushSign = dist < r ? -1 : 1;
                        m.x += nx * pushSign * 2; m.y += ny * pushSign * 2;
                        resolveCollision(m, nx * pushSign, ny * pushSign, cfg, false);
                    }
                }
            }
        });

        for (const line of linesRef.current) checkLine(m, line, cfg);
        for (const dline of dynamicLines) checkLine(m, dline, cfg, true);
        for (const pin of pinsRef.current) checkPin(m, pin, cfg);

        for (const other of marbles) {
            if (m === other || other.finished) continue;
            const dx = other.x - m.x; const dy = other.y - m.y;
            const distSq = dx*dx + dy*dy;
            const minD = m.radius + other.radius;
            if (distSq < minD*minD) {
                const dist = Math.sqrt(distSq);
                const nx = dx/dist; const ny = dy/dist;
                const pen = (minD - dist) * 0.5;
                m.x -= nx*pen; m.y -= ny*pen;
                other.x += nx*pen; other.y += ny*pen;

                const dvx = m.vx - other.vx; const dvy = m.vy - other.vy;
                const dot = dvx*nx + dvy*ny;
                if (dot > 0) {
                   const J = dot * 0.9;
                   m.vx -= J*nx; m.vy -= J*ny;
                   other.vx += J*nx; other.vy += J*ny;

                   // Transfer some spin
                   const spinDiff = m.omega - other.omega;
                   m.omega -= spinDiff * 0.1;
                   other.omega += spinDiff * 0.1;

                   if (J > 2) audio.playPinHit(J*0.2);
                }
            }
        }

        if (m.y > finishLineY.current && !m.finished) {
            m.finished = true;
            m.finishTime = now;
            m.rank = marbles.filter(b => b.finished).length;
            spawnParticles(m.x, m.y, '#10b981', 15, 5);
            audio.playPinHit(20);
        }

        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
      }
    }

    audio.updateRolling(totalSpeed);

    let target = cameraY.current;
    if (isFollowingBet && betMarbleId) {
        const b = marbles.find(m => m.id === betMarbleId);
        if (b && !b.finished) target = b.y - 300;
    } else {
        const active = marbles.filter(m => !m.finished).sort((a,b)=>b.y - a.y);
        if (active.length > 0) target = active[0].y - 300;
    }
    cameraY.current += (target - cameraY.current) * 0.1;

    if (marbles.every(m => m.finished) && !raceFinished.current) {
        raceFinished.current = true;
        const results = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish();
        setTimeout(() => onRaceFinish(results), 1000);
    }
  };

  // --- Physics Helpers (With Rotation) ---
  const resolveCollision = (ball: Marble, nx: number, ny: number, cfg: PhysicsConfig, isDynamic: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return;

    const restitution = isDynamic ? 1.5 : cfg.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    // Friction & Rotation (Impulse based)
    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;

    // Surface velocity relative to spin
    const vSurf = vDotT + ball.omega * ball.radius;

    // Apply friction impulse
    const jT = -vSurf * 0.3; // 0.3 = friction coeff roughly
    ball.vx += jT * tx;
    ball.vy += jT * ty;

    // Spin up the ball
    ball.omega += (jT * 2.5) / ball.radius; // 2.5 is related to moment of inertia for sphere

    if (Math.abs(jN) > 2) audio.playBump(Math.abs(jN));
  };

  const checkLine = (m: Marble, line: LineSegment, cfg: PhysicsConfig, isDynamic=false) => {
      const dx = line.x2 - line.x1; const dy = line.y2 - line.y1;
      const lenSq = dx*dx + dy*dy;
      const t = Math.max(0, Math.min(1, ((m.x - line.x1)*dx + (m.y - line.y1)*dy)/lenSq));
      const cx = line.x1 + t*dx; const cy = line.y1 + t*dy;
      const distX = m.x - cx; const distY = m.y - cy;
      const distSq = distX*distX + distY*distY;

      if (distSq < m.radius*m.radius) {
          const dist = Math.sqrt(distSq);
          const nx = distX/dist; const ny = distY/dist;
          m.x += nx * (m.radius - dist);
          m.y += ny * (m.radius - dist);
          resolveCollision(m, nx, ny, cfg, isDynamic);
      }
  };

  const checkPin = (m: Marble, pin: CircleObstacle, cfg: PhysicsConfig) => {
      const dx = m.x - pin.x; const dy = m.y - pin.y;
      const distSq = dx*dx + dy*dy;
      const minD = m.radius + pin.radius;
      if (distSq < minD*minD) {
          const dist = Math.sqrt(distSq);
          const nx = dx/dist; const ny = dy/dist;
          m.x += nx * (minD - dist); m.y += ny * (minD - dist);
          // Pins are bouncy (bumper or pin)
          resolveCollision(m, nx, ny, { ...cfg, restitution: pin.type === 'bumper' ? 1.5 : 0.7 }, false);
      }
  };

  // --- Draw ---
  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (canvas.width !== canvas.offsetWidth) {
          canvas.width = canvas.offsetWidth;
          canvas.height = canvas.offsetHeight;
      }

      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      const scale = canvas.width / COURSE_WIDTH;
      ctx.scale(scale, scale);
      const cam = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 150));
      ctx.translate(0, -cam);

      // Lines
      ctx.lineWidth = 5; ctx.lineCap = 'round'; ctx.strokeStyle = '#4b5563';
      ctx.beginPath();
      linesRef.current.forEach(l => { ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); });
      ctx.stroke();

      // Obstacles
      dynamicRef.current.forEach(obj => {
          ctx.save();
          ctx.translate(obj.x, obj.y);
          ctx.rotate(obj.angle);

          if (obj.type === 'spinner') {
              ctx.fillStyle = '#ef4444';
              ctx.fillRect(-obj.width/2, -8, obj.width, 16);
              ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fillStyle='#fff'; ctx.fill();
          } else if (obj.type.startsWith('slider')) {
              ctx.fillStyle = '#f59e0b';
              ctx.fillRect(-obj.width/2, -10, obj.width, 20);
          } else if (obj.type === 'repulsor') {
              ctx.fillStyle = 'rgba(139, 92, 246, 0.4)';
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#8b5cf6'; ctx.lineWidth=2; ctx.stroke();
          } else if (obj.type === 'fan') {
              ctx.fillStyle = 'rgba(56, 189, 248, 0.2)';
              ctx.fillRect(0, -obj.width/2, obj.height!, obj.width);
              ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width);
          } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 14;
             ctx.beginPath(); ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2); ctx.stroke();
          } else if (obj.type === 'laser' && obj.active) {
              ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; 
              ctx.shadowColor = 'red'; ctx.shadowBlur = 10;
              ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height!, 0); ctx.stroke();
              ctx.shadowBlur = 0;
          } else if (obj.type === 'teleporter') {
              ctx.fillStyle = `rgba(217, 70, 239, ${obj.timer})`;
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              if (obj.destX) {
                  ctx.save(); ctx.translate(obj.destX-obj.x, obj.destY!-obj.y);
                  ctx.strokeStyle = '#06b6d4'; ctx.lineWidth=2; ctx.setLineDash([5,5]);
                  ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.stroke();
                  ctx.restore();
              }
          }
          ctx.restore();
      });

      // Particles
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // Pins
      pinsRef.current.forEach(p => {
          ctx.fillStyle = '#9ca3af';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI*2); ctx.fill();
      });

      // Finish
      ctx.fillStyle = '#10b981';
      ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

      // Marbles
      marblesRef.current.forEach(m => {
          ctx.save();
          ctx.translate(m.x, m.y);
          ctx.rotate(-m.angle); // Rotate image based on physics angle

          const img = imagesRef.current[m.id];
          if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.clip();
              ctx.drawImage(img, -m.radius, -m.radius, m.radius*2, m.radius*2);
          } else {
              ctx.fillStyle = m.color;
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.fill();
          }
          ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.stroke();

          // Shine
          ctx.fillStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.3, 0, Math.PI*2); ctx.fill();

          // Bet Highlight
          if (m.id === betMarbleId) {
              ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 4; ctx.stroke();
          }
          ctx.restore();

          if (!m.finished) {
            ctx.fillStyle = 'white'; ctx.font='12px Arial'; ctx.textAlign='center';
            ctx.fillText(m.name, m.x, m.y - m.radius - 10);
          }
      });

      ctx.restore();

      // Leaderboard
      const sorted = [...marblesRef.current].sort((a,b) => {
          if (a.finished && b.finished) return a.rank - b.rank;
          if (a.finished) return -1;
          if (b.finished) return 1;
          return b.y - a.y;
      });

      const baseX = 10, baseY = 90;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(baseX, baseY, 120, sorted.length*20 + 10);
      ctx.font = '10px monospace'; ctx.textAlign='left';
      sorted.forEach((m, i) => {
          ctx.fillStyle = m.id === betMarbleId ? '#fbbf24' : '#fff';
          ctx.fillText(`${i+1}. ${m.name.substring(0,10)}`, baseX + 5, baseY + 15 + (i*20));
      });
  };

  useEffect(() => {
      const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
      requestRef.current = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(requestRef.current!);
  }, []);

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;

import React, { useRef, useEffect } from 'react';
import { Marble, PhysicsConfig, LineSegment, CircleObstacle, DynamicObstacle, Particle, ObstacleSettings } from '../types';
import { audio } from '../services/audioService';

interface RaceEngineProps {
  activeMarbles: Marble[];
  config: PhysicsConfig;
  obstacleSettings: ObstacleSettings;
  onRaceFinish: (results: Marble[]) => void;
  betMarbleId: number | null;
  isPaused: boolean;
  isFollowingBet: boolean;
}

const RaceEngine: React.FC<RaceEngineProps> = ({ activeMarbles, config, obstacleSettings, onRaceFinish, betMarbleId, isPaused, isFollowingBet }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const requestRef = useRef<number>();

  // Physics State
  const marblesRef = useRef<Marble[]>([]);
  const linesRef = useRef<LineSegment[]>([]);
  const pinsRef = useRef<CircleObstacle[]>([]);
  const dynamicRef = useRef<DynamicObstacle[]>([]);
  const particlesRef = useRef<Particle[]>([]); 
  const teleportCooldowns = useRef<Record<number, number>>({});

  // Refs for props to avoid dependency loop in update
  const configRef = useRef(config);
  const pausedRef = useRef(isPaused);

  useEffect(() => { configRef.current = config; }, [config]);
  useEffect(() => { pausedRef.current = isPaused; }, [isPaused]);

  // Images Cache
  const imagesRef = useRef<Record<number, HTMLImageElement>>({});

  // Camera & Game State
  const cameraY = useRef(0);
  const raceFinished = useRef(false);
  const finishLineY = useRef(0);
  const startTime = useRef(0);
  const timeRef = useRef(0);

  const COURSE_WIDTH = 600;

  // --- Particle System ---
  const spawnParticles = (x: number, y: number, color: string, count: number = 5, speed: number = 2) => {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const velocity = Math.random() * speed;
      particlesRef.current.push({
        x,
        y,
        vx: Math.cos(angle) * velocity,
        vy: Math.sin(angle) * velocity,
        life: 1.0,
        decay: 0.02 + Math.random() * 0.03,
        color: color,
        size: 1 + Math.random() * 3
      });
    }
  };

  // --- Level Generator: PLINKO RESTORED ---
  const generateLevel = () => {
    const lines: LineSegment[] = [];
    const pins: CircleObstacle[] = [];
    const dynamics: DynamicObstacle[] = [];

    let currentY = 100;

    // --- 1. PLINKO START (Triângulo de Pinos) ---
    // Funnel walls top
    lines.push({ x1: 0, y1: 0, x2: COURSE_WIDTH * 0.4, y2: 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: 0, x2: COURSE_WIDTH * 0.6, y2: 100, type: 'wall' });

    // The Grid
    const rows = 12;
    for (let r = 0; r < rows; r++) {
       const cols = r + 3; // Pyramid shape
       const rowY = currentY + r * 45;
       const spacing = 55;
       const rowWidth = (cols - 1) * spacing;
       const startX = (COURSE_WIDTH - rowWidth) / 2;

       for (let c = 0; c < cols; c++) {
           pins.push({
               x: startX + c * spacing,
               y: rowY,
               radius: 6,
               type: 'pin'
           });
       }
    }
    currentY += rows * 45 + 50;

    // Funnel out of Plinko
    lines.push({ x1: 0, y1: currentY - 50, x2: COURSE_WIDTH * 0.35, y2: currentY + 100, type: 'wall' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH * 0.65, y2: currentY + 100, type: 'wall' });
    currentY += 150;

    // --- 2. OBSTACLES ---
    const segmentCount = 15;
    const segmentHeight = 450;

    const pickObstacleType = () => {
        const options = [];
        if (obstacleSettings.spinner) options.push({ type: 'spinner', weight: 15 });
        if (obstacleSettings.slider) {
            options.push({ type: 'slider_h', weight: 12 });
            options.push({ type: 'slider_v', weight: 12 });
        }
        if (obstacleSettings.repulsor) options.push({ type: 'repulsor', weight: 10 });
        if (obstacleSettings.conveyor) options.push({ type: 'conveyor', weight: 10 });
        if (obstacleSettings.teleporter) options.push({ type: 'teleporter', weight: 12 });
        if (obstacleSettings.hollow_circle) options.push({ type: 'hollow_circle', weight: 10 });
        if (obstacleSettings.laser) options.push({ type: 'laser', weight: 8 });
        if (obstacleSettings.funnel) options.push({ type: 'funnel', weight: 6 });
        if (obstacleSettings.fan) options.push({ type: 'fan', weight: 8 });

        if (options.length === 0) return 'none';
        const totalWeight = options.reduce((sum, opt) => sum + opt.weight, 0);
        let random = Math.random() * totalWeight;
        for (const opt of options) {
            if (random < opt.weight) return opt.type;
            random -= opt.weight;
        }
        return options[0].type;
    };

    for (let i = 0; i < segmentCount; i++) {
      const type = pickObstacleType();

      // Wall borders
      lines.push({ x1: 0, y1: currentY - 50, x2: 0, y2: currentY + segmentHeight, type: 'wall' });
      lines.push({ x1: COURSE_WIDTH, y1: currentY - 50, x2: COURSE_WIDTH, y2: currentY + segmentHeight, type: 'wall' });

      if (type === 'spinner') {
        lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.3, y2: currentY + 100, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.7, y2: currentY + 100, type: 'floor' });
        dynamics.push({ id: `spin_${i}_1`, type: 'spinner', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 160, angle: 0, speed: 0.08 });
        dynamics.push({ id: `spin_${i}_2`, type: 'spinner', x: COURSE_WIDTH * 0.7, y: currentY + 350, width: 160, angle: Math.PI / 2, speed: -0.08 });
      } else if (type === 'slider_h') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.2, y2: currentY + 150, type: 'floor' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.8, y2: currentY + 150, type: 'floor' });
        dynamics.push({ id: `slide_h_${i}`, type: 'slider_h', x: COURSE_WIDTH / 2, y: currentY + 280, width: 220, angle: 0, speed: 2.0, range: 170, initialX: COURSE_WIDTH / 2, initialY: currentY + 280 });
      } else if (type === 'slider_v') {
        lines.push({ x1: 0, y1: currentY + 50, x2: COURSE_WIDTH * 0.3, y2: currentY + 150, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: currentY + 50, x2: COURSE_WIDTH * 0.7, y2: currentY + 150, type: 'wall' });
        dynamics.push({ id: `slide_v_1_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.3, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.3, initialY: currentY + 250 });
        dynamics.push({ id: `slide_v_2_${i}`, type: 'slider_v', x: COURSE_WIDTH * 0.7, y: currentY + 250, width: 100, angle: 0, speed: 1.5, range: 80, initialX: COURSE_WIDTH * 0.7, initialY: currentY + 250 });
      } else if (type === 'repulsor') {
        dynamics.push({ id: `rep_${i}`, type: 'repulsor', x: COURSE_WIDTH / 2, y: currentY + 250, width: 80, range: 180, angle: 0, speed: 0.1, force: 4.0 });
        pins.push({ x: COURSE_WIDTH*0.2, y: currentY+300, radius: 15, type:'pin' });
        pins.push({ x: COURSE_WIDTH*0.8, y: currentY+300, radius: 15, type:'pin' });
      } else if (type === 'teleporter') {
        const ex = COURSE_WIDTH * 0.5 + (Math.random() > 0.5 ? 120 : -120);
        dynamics.push({ id: `tp_${i}`, type: 'teleporter', x: ex, y: currentY + 200, width: 70, destX: COURSE_WIDTH/2, destY: currentY + 600, angle: 0, speed: 0, active: true });
        lines.push({ x1: 0, y1: currentY + 100, x2: COURSE_WIDTH, y2: currentY + 100, type: 'floor' });
      } else if (type === 'funnel') {
        const fy = currentY + 50;
        lines.push({ x1: 0, y1: fy, x2: COURSE_WIDTH/2 - 40, y2: fy + 300, type: 'wall' });
        lines.push({ x1: COURSE_WIDTH, y1: fy, x2: COURSE_WIDTH/2 + 40, y2: fy + 300, type: 'wall' });
      } else if (type === 'laser') {
        dynamics.push({ id: `lz_${i}`, type: 'laser', x: 50, y: currentY + 200, width: 0, height: 500, angle: 0, speed: 0, force: 40, active: true, timer: 0 });
      } else if (type === 'fan') {
        dynamics.push({ id: `fan_${i}`, type: 'fan', x: 20, y: currentY + 200, width: 50, height: 300, angle: 0, speed: 0, force: 1.5 });
      } else if (type === 'hollow_circle') {
        dynamics.push({ id: `hc_${i}`, type: 'hollow_circle', x: COURSE_WIDTH/2, y: currentY+250, width: 280, angle: 0, speed: 0.04, range: Math.PI/3 });
      }

      currentY += segmentHeight;
    }

    // Final Stretch
    lines.push({ x1: 0, y1: currentY, x2: COURSE_WIDTH * 0.2, y2: currentY + 200, type: 'floor' });
    lines.push({ x1: COURSE_WIDTH, y1: currentY, x2: COURSE_WIDTH * 0.8, y2: currentY + 200, type: 'floor' });
    finishLineY.current = currentY + 250;

    linesRef.current = lines;
    pinsRef.current = pins;
    dynamicRef.current = dynamics;
  };

  // --- Initialization (Runs ONLY when activeMarbles changes) ---
  useEffect(() => {
    generateLevel();
    raceFinished.current = false;
    startTime.current = Date.now();
    cameraY.current = 0;
    timeRef.current = 0;
    teleportCooldowns.current = {};
    particlesRef.current = [];

    // Preload Images
    activeMarbles.forEach(m => {
        if (m.logoUrl) {
            const img = new Image(); img.src = m.logoUrl; imagesRef.current[m.id] = img;
        }
    });

    // Reset Marbles to Top (Plinko Start)
    marblesRef.current = activeMarbles.map((m, i) => ({
      ...m,
      x: COURSE_WIDTH/2 + (Math.random() - 0.5) * 50,
      y: 40 + (i * -25), 
      vx: (Math.random() - 0.5) * 2,
      vy: 0,
      angle: 0, 
      omega: 0, // Reset Angular Velocity
      finished: false, 
      rank: 0
    }));

    audio.resume();
  }, [activeMarbles]); 

  // --- Physics & Game Loop ---
  const update = () => {
    // Check Pause Ref
    if (pausedRef.current) {
        audio.updateRolling(0);
        return;
    }
    if (raceFinished.current) {
        audio.updateRolling(0);
        return;
    }

    const cfg = configRef.current; // Use Ref
    const STEPS = 8;
    const dt = 1 / STEPS;
    timeRef.current += 1;
    const now = Date.now();

    const marbles = marblesRef.current;

    // 1. Update Particles
    for (let i = particlesRef.current.length - 1; i >= 0; i--) {
        const p = particlesRef.current[i];
        p.x += p.vx; p.y += p.vy; p.life -= p.decay;
        if (p.life <= 0) particlesRef.current.splice(i, 1);
    }

    // 2. Update Dynamic Obstacles
    dynamicRef.current.forEach(obj => {
       if (obj.type === 'spinner' || obj.type === 'hollow_circle') obj.angle += obj.speed;
       if (obj.type === 'slider_h') obj.x = obj.initialX! + Math.sin(timeRef.current * 0.02) * (obj.range || 100);
       if (obj.type === 'slider_v') obj.y = obj.initialY! + Math.sin(timeRef.current * 0.02) * (obj.range || 80);
       if (obj.type === 'laser') {
           obj.timer = (obj.timer || 0) + 1;
           if (obj.timer > 150) { obj.active = !obj.active; obj.timer = 0; }
       }
       if (obj.type === 'teleporter') {
           const phase = Math.sin(timeRef.current * 0.05);
           obj.active = phase > -0.5;
           obj.timer = (phase + 1) / 2;
       }
    });

    // Create temp collision lines for moving objects
    const dynamicLines: LineSegment[] = [];
    dynamicRef.current.forEach(obj => {
        if (obj.type === 'spinner' || obj.type === 'slider_h' || obj.type === 'slider_v') {
            const hw = obj.width / 2;
            const dx = Math.cos(obj.angle) * hw;
            const dy = Math.sin(obj.angle) * hw;
            dynamicLines.push({
                x1: obj.x - dx, y1: obj.y - dy,
                x2: obj.x + dx, y2: obj.y + dy,
                type: 'bouncer'
            });
        }
    });

    let totalSpeed = 0;

    // 3. Marble Physics Steps
    for (let step = 0; step < STEPS; step++) {
      for (const m of marbles) {
        if (m.finished) continue;

        m.vy += cfg.gravity * dt;
        m.x += m.vx * dt;
        m.y += m.vy * dt;

        // Apply Angular Velocity (Rotation)
        m.angle += m.omega * dt;
        m.omega *= 0.99; // Rolling friction

        // Walls
        if (m.x < m.radius) { m.x = m.radius; m.vx *= -0.5; }
        if (m.x > COURSE_WIDTH - m.radius) { m.x = COURSE_WIDTH - m.radius; m.vx *= -0.5; }

        // Interactions
        dynamicRef.current.forEach(obj => {
            // Fan
            if (obj.type === 'fan') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.height || 300) && Math.abs(dy) < obj.width) {
                     m.vx += Math.cos(obj.angle) * (obj.force || 1) * dt;
                     m.vy += Math.sin(obj.angle) * (obj.force || 1) * dt;
                }
            }
            // Repulsor
            if (obj.type === 'repulsor') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                if (dist < (obj.range || 100)) {
                    const f = (1 - dist/(obj.range||100)) * (obj.force||2);
                    m.vx += (dx/dist)*f*dt*40; m.vy += (dy/dist)*f*dt*40;
                }
            }
            // Laser
            if (obj.type === 'laser' && obj.active) {
                 const lx = obj.x + Math.cos(obj.angle)*obj.height!;
                 const dx = m.x - Math.max(obj.x, Math.min(lx, m.x));
                 const dy = m.y - obj.y;
                 if (dx*dx+dy*dy < 400 && Math.abs(dy) < 20) {
                     m.vx += (Math.random()-0.5)*50; m.vy += -20;
                     spawnParticles(m.x, m.y, '#ef4444', 5, 5);
                 }
            }
            // Teleporter
            if (obj.type === 'teleporter' && obj.active && (!teleportCooldowns.current[m.id] || now > teleportCooldowns.current[m.id])) {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                if (dx*dx+dy*dy < (obj.width/2)**2) {
                    m.x = obj.destX!; m.y = obj.destY!;
                    m.vy = Math.abs(m.vy) + 2;
                    teleportCooldowns.current[m.id] = now + 2000;
                    audio.playPinHit(10);
                    spawnParticles(m.x, m.y, '#06b6d4', 20, 5);
                }
            }
            // Hollow Circle
            if (obj.type === 'hollow_circle') {
                const dx = m.x - obj.x; const dy = m.y - obj.y;
                const dist = Math.sqrt(dx*dx + dy*dy);
                const r = obj.width/2;
                if (dist + m.radius > r - 8 && dist - m.radius < r + 8) {
                    // Check Gap
                    let angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += Math.PI * 2;
                    let rot = obj.angle % (Math.PI * 2);
                    if (rot < 0) rot += Math.PI * 2;
                    let diff = Math.abs(angle - rot);
                    if (diff > Math.PI) diff = Math.PI * 2 - diff; 
                    if (diff > (obj.range || 1.0)/2) { // Hit
                        const nx = dx/dist; const ny = dy/dist;
                        const pushSign = dist < r ? -1 : 1;
                        m.x += nx * pushSign * 2; m.y += ny * pushSign * 2;
                        resolveCollision(m, nx * pushSign, ny * pushSign, cfg, false);
                    }
                }
            }
        });

        // Collisions
        for (const line of linesRef.current) checkLine(m, line, cfg);
        for (const dline of dynamicLines) checkLine(m, dline, cfg, true);
        for (const pin of pinsRef.current) checkPin(m, pin, cfg);

        // Marble-Marble
        for (const other of marbles) {
            if (m === other || other.finished) continue;
            const dx = other.x - m.x; const dy = other.y - m.y;
            const distSq = dx*dx + dy*dy;
            const minD = m.radius + other.radius;
            if (distSq < minD*minD) {
                const dist = Math.sqrt(distSq);
                const nx = dx/dist; const ny = dy/dist;
                const pen = (minD - dist) * 0.5;
                m.x -= nx*pen; m.y -= ny*pen;
                other.x += nx*pen; other.y += ny*pen;

                const dvx = m.vx - other.vx; const dvy = m.vy - other.vy;
                const dot = dvx*nx + dvy*ny;
                if (dot > 0) {
                   const J = dot * 0.9;
                   m.vx -= J*nx; m.vy -= J*ny;
                   other.vx += J*nx; other.vy += J*ny;

                   // Transfer spin
                   const spinDiff = m.omega - other.omega;
                   m.omega -= spinDiff * 0.1;
                   other.omega += spinDiff * 0.1;

                   if (J > 2) audio.playPinHit(J*0.2);
                }
            }
        }

        // Finish Check
        if (m.y > finishLineY.current && !m.finished) {
            m.finished = true;
            m.finishTime = now;
            m.rank = marbles.filter(b => b.finished).length;
            spawnParticles(m.x, m.y, '#10b981', 15, 5);
            audio.playPinHit(20);
        }

        if (!m.finished) totalSpeed += Math.sqrt(m.vx*m.vx + m.vy*m.vy);
      }
    }

    audio.updateRolling(totalSpeed);

    // Camera
    let target = cameraY.current;
    if (isFollowingBet && betMarbleId) {
        const b = marbles.find(m => m.id === betMarbleId);
        if (b && !b.finished) target = b.y - 300;
    } else {
        const active = marbles.filter(m => !m.finished).sort((a,b)=>b.y - a.y);
        if (active.length > 0) target = active[0].y - 300;
    }
    cameraY.current += (target - cameraY.current) * 0.1;

    // End Condition
    if (marbles.every(m => m.finished) && !raceFinished.current) {
        raceFinished.current = true;
        const results = [...marbles].sort((a, b) => a.rank - b.rank);
        audio.playFinish();
        setTimeout(() => onRaceFinish(results), 1000);
    }
  };

  // --- Physics Helper: Resolve + Rotation ---
  const resolveCollision = (ball: Marble, nx: number, ny: number, cfg: PhysicsConfig, isDynamic: boolean) => {
    const vDotN = ball.vx * nx + ball.vy * ny;
    if (vDotN > 0) return;

    const restitution = isDynamic ? 1.5 : cfg.restitution;
    const jN = -(1 + restitution) * vDotN;
    ball.vx += jN * nx;
    ball.vy += jN * ny;

    // Friction Impulses for Rotation
    const tx = -ny;
    const ty = nx;
    const vDotT = ball.vx * tx + ball.vy * ty;

    // Surface velocity relative to spin
    const vSurf = vDotT + ball.omega * ball.radius;

    // Apply friction impulse
    const jT = -vSurf * 0.3; 
    ball.vx += jT * tx;
    ball.vy += jT * ty;

    // Spin up the ball
    ball.omega += (jT * 2.5) / ball.radius;

    if (Math.abs(jN) > 2) audio.playBump(Math.abs(jN));
  };

  const checkLine = (m: Marble, line: LineSegment, cfg: PhysicsConfig, isDynamic=false) => {
      const dx = line.x2 - line.x1; const dy = line.y2 - line.y1;
      const lenSq = dx*dx + dy*dy;
      const t = Math.max(0, Math.min(1, ((m.x - line.x1)*dx + (m.y - line.y1)*dy)/lenSq));
      const cx = line.x1 + t*dx; const cy = line.y1 + t*dy;
      const distX = m.x - cx; const distY = m.y - cy;
      const distSq = distX*distX + distY*distY;

      if (distSq < m.radius*m.radius) {
          const dist = Math.sqrt(distSq);
          const nx = distX/dist; const ny = distY/dist;
          m.x += nx * (m.radius - dist);
          m.y += ny * (m.radius - dist);
          resolveCollision(m, nx, ny, cfg, isDynamic);
      }
  };

  const checkPin = (m: Marble, pin: CircleObstacle, cfg: PhysicsConfig) => {
      const dx = m.x - pin.x; const dy = m.y - pin.y;
      const distSq = dx*dx + dy*dy;
      const minD = m.radius + pin.radius;
      if (distSq < minD*minD) {
          const dist = Math.sqrt(distSq);
          const nx = dx/dist; const ny = dy/dist;
          m.x += nx * (minD - dist); m.y += ny * (minD - dist);
          resolveCollision(m, nx, ny, { ...cfg, restitution: pin.type === 'bumper' ? 1.5 : 0.7 }, false);
      }
  };

  // --- Draw Loop ---
  const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (canvas.width !== canvas.offsetWidth) {
          canvas.width = canvas.offsetWidth;
          canvas.height = canvas.offsetHeight;
      }

      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      const scale = canvas.width / COURSE_WIDTH;
      ctx.scale(scale, scale);
      const cam = Math.max(0, Math.min(cameraY.current, finishLineY.current - canvas.height/scale + 150));
      ctx.translate(0, -cam);

      // 1. Draw Static Lines
      ctx.lineWidth = 5; ctx.lineCap = 'round'; ctx.strokeStyle = '#4b5563';
      ctx.beginPath();
      linesRef.current.forEach(l => { ctx.moveTo(l.x1, l.y1); ctx.lineTo(l.x2, l.y2); });
      ctx.stroke();

      // 2. Draw Obstacles (Solid Shapes)
      dynamicRef.current.forEach(obj => {
          ctx.save();
          ctx.translate(obj.x, obj.y);
          ctx.rotate(obj.angle);

          if (obj.type === 'spinner') {
              ctx.fillStyle = '#ef4444';
              ctx.fillRect(-obj.width/2, -8, obj.width, 16);
              ctx.beginPath(); ctx.arc(0,0,5,0,Math.PI*2); ctx.fillStyle='#fff'; ctx.fill();
          } else if (obj.type.startsWith('slider')) {
              ctx.fillStyle = '#f59e0b';
              ctx.fillRect(-obj.width/2, -10, obj.width, 20);
          } else if (obj.type === 'repulsor') {
              ctx.fillStyle = 'rgba(139, 92, 246, 0.4)';
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              ctx.strokeStyle = '#8b5cf6'; ctx.lineWidth=2; ctx.stroke();
          } else if (obj.type === 'fan') {
              ctx.fillStyle = 'rgba(56, 189, 248, 0.2)';
              ctx.fillRect(0, -obj.width/2, obj.height!, obj.width);
              ctx.fillStyle = '#64748b'; ctx.fillRect(-10, -obj.width/2, 20, obj.width);
          } else if (obj.type === 'hollow_circle') {
             const r = obj.width / 2;
             const gap = obj.range || 1.0;
             ctx.strokeStyle = '#d946ef'; ctx.lineWidth = 14;
             ctx.beginPath(); ctx.arc(0, 0, r, gap/2, Math.PI * 2 - gap/2); ctx.stroke();
          } else if (obj.type === 'laser' && obj.active) {
              ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 4; 
              ctx.shadowColor = 'red'; ctx.shadowBlur = 10;
              ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(obj.height!, 0); ctx.stroke();
              ctx.shadowBlur = 0;
          } else if (obj.type === 'teleporter') {
              ctx.fillStyle = `rgba(217, 70, 239, ${obj.timer})`;
              ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.fill();
              if (obj.destX) {
                  ctx.save(); ctx.translate(obj.destX-obj.x, obj.destY!-obj.y);
                  ctx.strokeStyle = '#06b6d4'; ctx.lineWidth=2; ctx.setLineDash([5,5]);
                  ctx.beginPath(); ctx.arc(0,0,obj.width/2,0,Math.PI*2); ctx.stroke();
                  ctx.restore();
              }
          }
          ctx.restore();
      });

      // 3. Draw Particles
      particlesRef.current.forEach(p => {
          ctx.globalAlpha = p.life;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI*2); ctx.fill();
      });
      ctx.globalAlpha = 1.0;

      // 4. Draw Pins
      pinsRef.current.forEach(p => {
          ctx.fillStyle = '#9ca3af';
          ctx.beginPath(); ctx.arc(p.x, p.y, p.radius, 0, Math.PI*2); ctx.fill();
      });

      // 5. Draw Finish
      ctx.fillStyle = '#10b981';
      ctx.fillRect(0, finishLineY.current, COURSE_WIDTH, 10);

      // 6. Draw Marbles (With Rotation)
      marblesRef.current.forEach(m => {
          ctx.save();
          ctx.translate(m.x, m.y);
          ctx.rotate(-m.angle); // Rotate based on physics angle

          const img = imagesRef.current[m.id];
          if (m.logoUrl && img && img.complete && img.naturalHeight !== 0) {
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.clip();
              ctx.drawImage(img, -m.radius, -m.radius, m.radius*2, m.radius*2);
          } else {
              ctx.fillStyle = m.color;
              ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.fill();
          }
          // Border
          ctx.strokeStyle = '#000'; ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(0,0,m.radius,0,Math.PI*2); ctx.stroke();

          // Shine/Gloss
          ctx.fillStyle = 'rgba(255,255,255,0.3)';
          ctx.beginPath(); ctx.arc(-m.radius*0.3, -m.radius*0.3, m.radius*0.3, 0, Math.PI*2); ctx.fill();

          // Bet Highlight
          if (m.id === betMarbleId) {
              ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 4;
              ctx.stroke();
          }
          ctx.restore();

          if (!m.finished) {
            ctx.fillStyle = 'white'; ctx.font='12px Arial'; ctx.textAlign='center';
            ctx.fillText(m.name, m.x, m.y - m.radius - 10);
          }
      });

      ctx.restore();

      // Leaderboard
      const sorted = [...marblesRef.current].sort((a,b) => {
          if (a.finished && b.finished) return a.rank - b.rank;
          if (a.finished) return -1;
          if (b.finished) return 1;
          return b.y - a.y;
      });

      const baseX = 10, baseY = 90;
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(baseX, baseY, 120, sorted.length*20 + 10);
      ctx.font = '10px monospace'; ctx.textAlign='left';
      sorted.forEach((m, i) => {
          ctx.fillStyle = m.id === betMarbleId ? '#fbbf24' : '#fff';
          ctx.fillText(`${i+1}. ${m.name.substring(0,10)}`, baseX + 5, baseY + 15 + (i*20));
      });
  };

  useEffect(() => {
      const loop = () => { update(); draw(); requestRef.current = requestAnimationFrame(loop); };
      requestRef.current = requestAnimationFrame(loop);
      return () => cancelAnimationFrame(requestRef.current!);
  }, []);

  return <canvas ref={canvasRef} className="w-full h-full block" />;
};

export default RaceEngine;
